function DelayedMoveAwayFromTarget(oUnit, iTimeToRun, tPositionToRunFrom, iDelayBeforeStarting)
    WaitSeconds(iDelayBeforeStarting)
    MoveAwayFromTargetTemporarily(oUnit, iTimeToRun, tPositionToRunFrom)
end

function MoveAwayFromTargetTemporarily(oUnit, iTimeToRun, tPositionToRunFrom)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MoveAwayFromTargetTemporarily'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bMoveInStages = false --set to true later if hardly have any time to run, but in reality this functionality isn't expected to be used in most cases, left in since took a while to get it to work to a basic level, but turns out it's probably better to just move in a straight line rather than trying multiple move orders

    local tUnitPosition = oUnit:GetPosition()
    local oBP = oUnit:GetBlueprint()
    local iUnitSpeed = (oBP.Physics.MaxSpeed or 0)
    if iUnitSpeed > 0 then
        local iDistanceToMove = (iTimeToRun + 1) * iUnitSpeed
        --local tRevisedPositionToRunFrom

        local iCurFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oUnit)
        local iAngleFromUnitToBomb
        if tUnitPosition[1] == tPositionToRunFrom[1] and tUnitPosition[3] == tPositionToRunFrom[3] then
            iAngleFromUnitToBomb = iCurFacingDirection - 180
            if iAngleFromUnitToBomb < 0 then iAngleFromUnitToBomb = iAngleFromUnitToBomb + 360 end
        else
            iAngleFromUnitToBomb = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tPositionToRunFrom)
        end

        local iAngleAdjFactor
        local iFacingAngleWanted = iAngleFromUnitToBomb + 180
        if iFacingAngleWanted >= 360 then iFacingAngleWanted = iFacingAngleWanted - 360 end

        local iTurnRate = (oBP.Physics.TurnRate or 90)
        local iBackupDist = (oBP.Physics.BackUpDistance or 0)
        local iTimeToTurn
        local bBackupInsteadOfTurning = false
        local iDistToBomb = AiBotUtilities.GetDistanceBetweenPositions(tPositionToRunFrom, oUnit:GetPosition())
        if iBackupDist >= 4 then
            bBackupInsteadOfTurning = true
            iTimeToTurn = 0
            if AiBotUtilities.GetAngleDifference(iCurFacingDirection, iFacingAngleWanted) <= 90 then
                iFacingAngleWanted = iCurFacingDirection
            else
                iFacingAngleWanted = iCurFacingDirection + 180
                if iFacingAngleWanted >= 360 then iFacingAngleWanted = iFacingAngleWanted - 360 end
            end
            iDistanceToMove = iDistanceToMove + math.min(iDistToBomb, iDistanceToMove * 0.5)
        else
            if iTurnRate <= 0 then iTimeToTurn = 0 else iTimeToTurn = math.abs(iFacingAngleWanted - iCurFacingDirection) / iTurnRate end
            if iDistToBomb * 2 / iUnitSpeed <= iTimeToTurn then
                iFacingAngleWanted = iCurFacingDirection
                iDistanceToMove = iDistanceToMove + iDistToBomb
            end
        end

        if iTimeToTurn > iTimeToRun and not(bBackupInsteadOfTurning) then bMoveInStages = true end

        local tTempLocationToMove

        if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop for move commands for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iTimeToRun='..iTimeToRun..'; iCurFacingDirection='..iCurFacingDirection..'; iAngleFromUnitToBomb='..iAngleFromUnitToBomb..'; iFacingAngleWanted='..iFacingAngleWanted..'; tUnitStartPosition='..repru(oUnit:GetPosition())..'; tPositionToRunFrom='..repru(tPositionToRunFrom)..'; bBackupInsteadOfTurning='..tostring(bBackupInsteadOfTurning)) end
        AiBotOrders.IssueTrackedClearCommands(oUnit)
        TrackTemporaryUnitMicro(oUnit, iTimeToRun)
        tTempLocationToMove = oUnit:GetPosition()
        local iDistanceAlreadyMoved = 0


        --Turn around while moving away if we're not facing the right direction:
        if bMoveInStages then
            local iInitialAngleAdj = 30
            local iAngleMaxSingleAdj = 45
            local iTempDistanceAwayToMove = 3
            local iDistanceIncreasePerCycle = 1.5
            local iDistanceIncreaseCompoundFactor = 1.5
            local iLoopCount = 0

            if math.abs(iCurFacingDirection - iFacingAngleWanted) > (iAngleMaxSingleAdj + iInitialAngleAdj) then
                local iTempAngleDirectionToMove = iCurFacingDirection

                if iCurFacingDirection - iFacingAngleWanted > 0 then
                    if iCurFacingDirection - iFacingAngleWanted > 180 then iAngleAdjFactor = 1 --Clockwise
                    else iAngleAdjFactor = -1 --AntiClockwise
                    end

                elseif iCurFacingDirection - iFacingAngleWanted < -180 then iAngleAdjFactor = -1
                else iAngleAdjFactor = 1
                end --Clockwise



                while iLoopCount < 6 do
                    iLoopCount = iLoopCount + 1

                    iTempAngleDirectionToMove = iCurFacingDirection + (iInitialAngleAdj + iLoopCount * iAngleMaxSingleAdj) * iAngleAdjFactor
                    if iTempAngleDirectionToMove > 360 then iTempAngleDirectionToMove = iTempAngleDirectionToMove - 360
                    elseif iTempAngleDirectionToMove < 0 then iTempAngleDirectionToMove = iTempAngleDirectionToMove + 360
                    end

                    if bDebugMessages == true then LOG(sFunctionRef..': iLoopCount='..iLoopCount..'; iTempAngleDirectionToMove='..iTempAngleDirectionToMove..'; iInitialAngleAdj='..iInitialAngleAdj..'; iAngleAdjFactor='..iAngleAdjFactor..'; iCurFacingDirection='..iCurFacingDirection..'; iFacingAngleWanted='..iFacingAngleWanted) end


                    iTempDistanceAwayToMove = iTempDistanceAwayToMove + iDistanceIncreasePerCycle * iDistanceIncreasePerCycle * (iDistanceIncreaseCompoundFactor ^ iLoopCount - 1)
                    tTempLocationToMove = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iTempAngleDirectionToMove, iTempDistanceAwayToMove, true, false, true)
                    AiBotOrders.IssueTrackedMove(oUnit, tTempLocationToMove, 0.25, true, 'TempMA', true)
                    if bDebugMessages == true then LOG(sFunctionRef..': Just issued move order to tTempLocationToMove='..repru(tTempLocationToMove)..'; iTempAngleDirectionToMove='..iTempAngleDirectionToMove) end
                    if math.abs(iTempAngleDirectionToMove - iFacingAngleWanted) <= iAngleMaxSingleAdj then break
                    elseif math.abs(iTempAngleDirectionToMove - iFacingAngleWanted) > 360 then
                        AiBotUtilities.ErrorHandler('Something has gone wrong with dodge micro, will stop trying to turn around')
                        break
                    end
                end
                iDistanceAlreadyMoved = AiBotUtilities.GetDistanceBetweenPositions(tTempLocationToMove, tPositionToRunFrom)
            end
        end
        --Should now be facing close to the right direction, so move further in this direction


        --If are backing up, then consider queuing up multiple move orders
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we should backup, bBackupInsteadOfTurning='..tostring(bBackupInsteadOfTurning or false)) end
        if bBackupInsteadOfTurning and iBackupDist - 1 > 0 and iDistanceToMove > iDistanceAlreadyMoved then
            --First stop and wait 1 tick (so we can actually backup)
            TrackTemporaryUnitMicro(oUnit, iTimeToRun)
            --For backing up to work reliably the unit should be stationery
            if oUnit:IsUnitState('Moving') then
                AiBotOrders.IssueTrackedClearCommands(oUnit)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitTicks(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
            local iPlateauWanted = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition())
            local iCurDistToMove
            local iTotalTimeWaited = 0
            local bFirstCycle = true
            while iDistanceAlreadyMoved < iDistanceToMove and AiBotUnitInfo.IsUnitValid(oUnit) do

                if bFirstCycle then
                    while AiBotUnitInfo.IsUnitValid(oUnit) and AiBotUnitInfo.GetUnitSpeed(oUnit) >= 0.75 and iTotalTimeWaited <= 9 do
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(1)
                        iTotalTimeWaited = iTotalTimeWaited + 1
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        if bDebugMessages == true then LOG(sFunctionRef..': Speed after waiting 1 tick='..AiBotUnitInfo.GetUnitSpeed(oUnit)..'; iTotalTimeWaited in ticks='..iTotalTimeWaited) end
                    end
                    if not(AiBotUnitInfo.IsUnitValid(oUnit)) then break end
                end


                iCurDistToMove = math.min(iBackupDist - 1, math.max(1, iDistanceToMove - iDistanceAlreadyMoved))
                local tViaPoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iFacingAngleWanted, iCurDistToMove + iDistanceAlreadyMoved, true, false, true)
                if NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tViaPoint) == iPlateauWanted then
                    --Are we either an amphibious/hover unit, of a land unit on the same island, or a naval unit on the same pond
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAmphibious + categories.AIR, oUnit.UnitId)
                            or (EntityCategoryContains(categories.LAND, oUnit.UnitId) and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition()) == NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tViaPoint))
                            or (EntityCategoryContains(categories.NAVAL, oUnit.UnitId) and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeNavy, oUnit:GetPosition()) == NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeNavy, tViaPoint)) then
                        AiBotOrders.IssueTrackedMove(oUnit, tViaPoint, 0.25, true, 'BckupDodMv', true)
                        iDistanceAlreadyMoved = iDistanceAlreadyMoved + iCurDistToMove
                        if bDebugMessages == true then LOG(sFunctionRef..': Backing up to via point, iCurDistToMove='..iCurDistToMove..'; iDistanceAlreadyMoved='..iDistanceAlreadyMoved) end
                    else
                        --Abort
                        break
                    end
                else
                    break
                end
                bFirstCycle = false
            end
        end
        if not(bBackupInsteadOfTurning) or iDistanceToMove < iDistanceAlreadyMoved then
            local tNewTargetIgnoringGrouping = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iFacingAngleWanted, math.max(1, iDistanceToMove - iDistanceAlreadyMoved), true, false, true)
            if bDebugMessages == true then LOG(sFunctionRef..': Finished trying to face the right direction, tNewTargetIgnoringGrouping='..repru(tNewTargetIgnoringGrouping)..'; tUnitPosition='..repru(tUnitPosition)..'; iDistanceToMove='..iDistanceToMove..'; iDistanceAlreadyMoved='..iDistanceAlreadyMoved) end
            if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAir, oUnit.UnitId) then
                AiBotOrders.IssueTrackedMove(oUnit, tNewTargetIgnoringGrouping, 0.25, true, 'TempGA', true)
                if bDebugMessages == true then LOG(sFunctionRef..': Dodging bomb for air unit, tNewTargetIgnoringGrouping='..repru(tNewTargetIgnoringGrouping)..'; Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
            else
                local tNewTargetInSameGroup = AiBotMap.GetPositionAtOrNearTargetInPathingGroup(tUnitPosition, tNewTargetIgnoringGrouping, 0, 0, oUnit, true, false)
                if tNewTargetInSameGroup then
                    if bDebugMessages == true then LOG(sFunctionRef..': Starting bomber dodge for unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; tNewTargetInSameGroup='..repru(tNewTargetInSameGroup)) end

                    AiBotOrders.IssueTrackedMove(oUnit, tNewTargetInSameGroup, 0.25, true, 'TempMA', true)
                    TrackTemporaryUnitMicro(oUnit, iTimeToRun)
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code at time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetBombTarget(weapon, projectile)
    --based on CalcBallisticAcceleration

    --Copy of CalcBallisticAcceleration core part of calculation to determine bomb target; ignores multiple bombs
    local acc = 4.75
    if projectile and projectile.GetLauncher and not(projectile:BeenDestroyed()) then
        local launcher = projectile:GetLauncher()
        if launcher then
            -- Get projectile position and velocity
            -- velocity needs to multiplied by 10 due to being returned /tick instead of /s
            local proj = {pos=projectile:GetPosition(), vel=VMult(Vector(launcher:GetVelocity()), 10)}
            local entity = launcher:GetTargetEntity()

            local target
            if entity and IsUnit(entity) then
                -- target is a entity
                target = {pos=entity:GetPosition(), vel=VMult(Vector(entity:GetVelocity()), 10)}
            else
                -- target is something else i.e. attack ground
                target = {pos=weapon:GetCurrentTargetPos(), vel=Vector(0, 0, 0)}
            end

            -- calculate flat(exclude y-axis) distance and velocity between projectile and target
            if AiBotUtilities.IsTableEmpty(target) == false and AiBotUtilities.IsTableEmpty(proj.pos) == false and target.pos and target.vel and proj.pos and target.pos then
                local dist = {pos=XZDist(proj.pos, target.pos), vel=XZDist(proj.vel, target.vel)}

                -- how many seconds until the bomb hits the target in xz-space
                local time = dist.pos / dist.vel
                if time == 0 then return acc end

                -- find out where the target will be at that point in time (it could be moving)
                target.tpos = {target.pos[1] + time * target.vel[1], 0, target.pos[3] + time * target.vel[3]}
                -- what is the height at that future position
                target.tpos[2] = GetSurfaceHeight(target.tpos[1], target.tpos[3])
                return target.tpos
            end
        end
    elseif not(projectile) then
        if weapon.GetCurrentTarget then
            if weapon:GetCurrentTarget().GetPosition then return weapon:GetCurrentTarget():GetPosition() end
        end
        if weapon.GetCurrentTargetPos then
            if weapon:GetCurrentTargetPos() then return weapon:GetCurrentTargetPos() end
        end
    end
    return nil
end

function FriendlyGunshipsAvoidBomb(oBomber, oWeapon, projectile)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'FriendlyGunshipsAvoidBomb'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local tBombTarget = GetBombTarget(oWeapon, projectile)
    if tBombTarget then
        local iBombSize = oWeapon:GetBlueprint().DamageRadius
        if bDebugMessages == true then LOG(sFunctionRef..': Near start, oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; tBombTarget='..repru(tBombTarget)..'; iBombSize='..iBombSize) end
        if iBombSize then
            local iCategoriesToRun = AiBotUnitInfo.refCategoryGunship
            local iRadiusSize = iBombSize + 10
            local aiBrain = oBomber:GetAIBrain()
            local tUnitsToRun = aiBrain:GetUnitsAroundPoint(iCategoriesToRun, tBombTarget, iRadiusSize, 'Ally')
            if AiBotUtilities.IsTableEmpty(tUnitsToRun) == false then
                local tTemporaryDestination = AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.reftAirRallyPoint]
                if AiBotUtilities.IsTableEmpty(tTemporaryDestination) then
                    --Campaign cutscene like fort clarke assault - wont exist yet
                    if not(ScenarioInfo.OpEnded) then
                        AiBotUtilities.ErrorHandler('Dont have an air rally point')
                    end
                    --Backup - try and get the start position of the first unit
                    tTemporaryDestination = AiBotMap.GetPlayerStartPosition(tUnitsToRun[1]:GetAIBrain())
                end

                local tAltTempDestination
                local oCurUnitBrain
                local iTeam = aiBrain.AiBotTeam
                local iCurDistToBomb, iCurAngleFromBomb, bMoveToAltDestination
                local iAngleFromBombToBase = AiBotUtilities.GetAngleFromAToB(tBombTarget, tTemporaryDestination)
                local bCampaignMap = AiBotMap.bIsCampaignMap
                for iUnit, oUnit in tUnitsToRun do
                    oCurUnitBrain = oUnit:GetAIBrain()
                    if oCurUnitBrain.AiBotAI and oCurUnitBrain.AiBotTeam == iTeam then
                        if not(oUnit[AiBotUnitInfo.refbEasyBrain]) then
                            --If gunship runs to temp destination is it likely to be going the wrong way to avoid the bomb? if so then have it run in a different direction
                            iCurDistToBomb = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tBombTarget)
                            bMoveToAltDestination = false
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurDistToBomb='..iCurDistToBomb..'; ANgle from bomb='..AiBotUtilities.GetAngleFromAToB(tBombTarget, oUnit:GetPosition())..'; iAngleFromBombToBase='..iAngleFromBombToBase) end
                            if iCurDistToBomb >= 4 then
                                iCurAngleFromBomb = AiBotUtilities.GetAngleFromAToB(tBombTarget, oUnit:GetPosition())
                                if AiBotUtilities.GetAngleDifference(iCurAngleFromBomb, iAngleFromBombToBase) > 50 then
                                    bMoveToAltDestination = true
                                    tAltTempDestination = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iCurAngleFromBomb, iRadiusSize, true, false, bCampaignMap)
                                end
                            end
                            AiBotOrders.IssueTrackedClearCommands(oUnit)
                            if bMoveToAltDestination then
                                AiBotOrders.IssueTrackedMove(oUnit, tAltTempDestination, 3, false, 'AhwRunH', true)
                            else
                                AiBotOrders.IssueTrackedMove(oUnit, tTemporaryDestination, 3, false, 'AhwRunT', true)
                            end
                            TrackTemporaryUnitMicro(oUnit, 4) --takes roughly 4s for bomb to land
                        end
                    end
                end
            end
        end
    else
        if bDebugMessages == true then LOG(sFunctionRef..': tBombTarget is nil') end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DodgeBomb(oBomber, oWeapon, projectile)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DodgeBombsFiredByUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tBombTarget = GetBombTarget(oWeapon, projectile)
    if bDebugMessages == true then LOG(sFunctionRef..': Start fo code for bomber '..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; is tBombTarget nil='..tostring(tBombTarget == nil)..'; Time='..GetGameTimeSeconds()) end
    --LOUD - recall Sprouto saying that bombs home in on target, so dont try and dodge
    if tBombTarget and not(AiBotUtilities.bLoudModActive) then
        if bDebugMessages == true then LOG(sFunctionRef..': bomb fired by oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; Dist to target from bomber='..AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tBombTarget)..'; Bomber speed='..AiBotUnitInfo.GetUnitSpeed(oBomber)) end
        oBomber[AiBotUnitInfo.refiLastDodgeBombEvent] = GetGameTimeSeconds()
        local iBombSize = 2.5
        if oWeapon.GetBlueprint then iBombSize = math.max(iBombSize, (oWeapon:GetBlueprint().DamageRadius or iBombSize)) end
        local iTimeToRun = 2.4 --T1, was 1.75 for v83 and earlier but it turned out to not be long enough for a t1 engi to dodge a t1 bomber
        if iBombSize > 2.5 then iTimeToRun = math.min(2.9, iTimeToRun + (iBombSize - 2.5) * 0.5) end --increased the min to 2.9 as of v84
        if EntityCategoryContains(categories.TECH2, oBomber.UnitId) then
            iBombSize = 3
            iTimeToRun = 2.4 --1.95 for v83 and earlier
            if iBombSize > 3 then iTimeToRun = math.min(2.9, iTimeToRun + (iBombSize - 3) * 0.5) end --increased the min to 2.9 as of v84
        elseif EntityCategoryContains(categories.TECH3, oBomber.UnitId) then
            iTimeToRun = 2.5
            --Consider recording for special asf suicide logic
            if bDebugMessages == true then LOG(sFunctionRef..': Will consider logic for suiciding into strat bomber') end
            ForkThread(AiBotAir.ConsiderRecordingStratBomberToSuicideInto, oBomber)
        end --Some t2 bombers do damage in a spread (cybran, uef)
        --local iTimeToRun = math.min(7, iBombSize + 1)
        local iRadiusSize = iBombSize + 2.5 --was +1 for v83 and earlier, but found if an engi was running towards the bomb target already it wouldn't get picked up and would die

        local iBomberArmyIndex = oBomber:GetAIBrain():GetArmyIndex()

        if bDebugMessages == true then
            LOG(sFunctionRef..': oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; Bomber position='..repru(oBomber:GetPosition())..'; tBombTarget='..repru(tBombTarget)..'; Dist between position and target='..AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tBombTarget)..'; Angle='..AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tBombTarget)..'; Bomber facing direction='..AiBotUnitInfo.GetUnitFacingAngle(oBomber)..'; will draw bomb target in black')
            AiBotUtilities.DrawLocation(tBombTarget, 3, 20)
        end --black ring around target

        local tAllUnitsInArea = GetUnitsInRect(Rect(tBombTarget[1]-iRadiusSize, tBombTarget[3]-iRadiusSize, tBombTarget[1]+iRadiusSize, tBombTarget[3]+iRadiusSize))
        local bDontCheckIfFriendlyGunships = true
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of units in rectangle around bomb radius empty='..tostring(AiBotUtilities.IsTableEmpty(tAllUnitsInArea))) end
        if AiBotUtilities.IsTableEmpty(tAllUnitsInArea) == false then
            local tMobileLandAndGunshipsInArea
            if iBombSize <= 9 then tMobileLandAndGunshipsInArea = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMobileLand - categories.EXPERIMENTAL, tAllUnitsInArea)
            else
                if EntityCategoryContains(categories.EXPERIMENTAL, oBomber.UnitId) then
                    tMobileLandAndGunshipsInArea = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGunship, tAllUnitsInArea)
                    bDontCheckIfFriendlyGunships = false --we get friendly gunships to split up via separate logic
                    iTimeToRun = math.max(iTimeToRun + 1.5, 5.5) --v68 - increased time from iTimeToRun, 3.5 due to issue with ahwassa bomb damage being spread over time
                    table.insert(AiBotAir.tiRecentExpBomberTargets, {tBombTarget[1], tBombTarget[2], tBombTarget[3]}) --NOTE: GetTimeForExpBomberToTurnToRally assumes this is updated here (i.e. called via fork thread so this code runs after GetTimeForExpBomberToTurnToRally)
                    ForkThread(AiBotAir.RemoveFirstExpBomberTarget, 10)
                    --also track last target
                    --oBomber[AiBotAir.refiExpLastBombTarget] = {tBombTarget[1], tBombTarget[2], tBombTarget[3]}
                else
                    tMobileLandAndGunshipsInArea = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMobileLand - categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryGunship, tAllUnitsInArea)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Are including gunships in the category of unit to consider dodging') end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of mobile land units in rectangle around bomb radius empty='..tostring(AiBotUtilities.IsTableEmpty(tMobileLandAndGunshipsInArea))) end
            if AiBotUtilities.IsTableEmpty(tMobileLandAndGunshipsInArea) == false then
                local oCurBrain
                local tNearbyFixedShields
                function AreUnderFixedShield(oUnitConsidering)
                    if not(tNearbyFixedShields) and not(oUnitConsidering:GetAIBrain().AiBotTeam == oBomber:GetAIBrain().AiBotTeam) then
                        tNearbyFixedShields = {}
                        local iTargetPlateauOrZero, iTargetLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnitConsidering:GetPosition())
                        if (iTargetPlateauOrZero or 0) > 0 then
                            local tTargetLZData = AiBotMap.tAllPlateaus[iTargetPlateauOrZero][AiBotMap.subrefPlateauLandZones][iTargetLandOrWaterZone]
                            local tTargetLZTeamData = tTargetLZData[AiBotMap.subrefLZTeamData][oUnitConsidering:GetAIBrain().AiBotTeam]
                            if (tTargetLZTeamData[AiBotMap.subrefLZSValue] or 0) >= 250 then
                                tNearbyFixedShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield, tTargetLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                            end
                        end
                    end
                    if tNearbyFixedShields[1] then
                        for iShield, oShield in tNearbyFixedShields do
                            if not(oShield.Dead) and oShield:GetFractionComplete() == 1 and oShield.MyShield.GetHealth and oShield.MyShield:GetHealth() > 0 then
                                if AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oUnitConsidering:GetPosition()) < (oShield:GetBlueprint().Defense.Shield.ShieldSize or 10) * 0.5 - 1 then
                                    return true
                                end
                            end
                        end
                    end
                    return false
                end
                for iUnit, oUnit in tMobileLandAndGunshipsInArea do
                    if not(oUnit.Dead) and oUnit.GetUnitId and oUnit.GetPosition and oUnit.GetAIBrain then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Does unit already have micro active='..tostring((oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false))..'; refbLowerPriorityMicroActive='..tostring(oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive] or false)..'; iTimeToRun='..iTimeToRun..'; AreUnderFixedShield='..tostring(AreUnderFixedShield(oUnit) or false)) end
                        oCurBrain = oUnit:GetAIBrain()
                        if oCurBrain.AiBotAI and not(oCurBrain.AiBotIsDefeated) and not(oCurBrain:IsDefeated()) and IsEnemy(oCurBrain:GetArmyIndex(), iBomberArmyIndex) then
                            if not(oUnit[AiBotUnitInfo.refbEasyBrain]) then
                                --ACU specific
                                if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then
                                    local aiBrain = oCurBrain
                                    --If ACU is upgrading might not want to cancel
                                    local bDontTryAndDodge = false
                                    if oUnit:IsUnitState('Upgrading') then
                                        --Are we facing a T1 bomb?
                                        if EntityCategoryContains(categories.TECH1, oBomber.UnitId) then
                                            bDontTryAndDodge = true
                                        else
                                            --Facing T2+ bomb, so greater risk if we dont try and dodge; dont dodge if are almost complete
                                            if oUnit:GetWorkProgress() >= 0.9 then
                                                bDontTryAndDodge = true
                                            else
                                                --Is it a T2 bomber, and there arent many bombers nearby?
                                                if EntityCategoryContains(categories.TECH2, oBomber.UnitId) then
                                                    local tNearbyBombers = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryBomber + AiBotUnitInfo.refCategoryGunship - categories.TECH1, oUnit:GetPosition(), 100, 'Enemy')
                                                    if AiBotUtilities.IsTableEmpty(tNearbyBombers) == true then
                                                        bDontTryAndDodge = true
                                                    else
                                                        local iEnemyBomberCount = 0
                                                        for iEnemy, oEnemy in tNearbyBombers do
                                                            if AiBotUnitInfo.IsUnitValid(oEnemy) then
                                                                iEnemyBomberCount = iEnemyBomberCount + 1
                                                                if iEnemyBomberCount >= 4 then break end
                                                            end
                                                        end
                                                        if iEnemyBomberCount < 4 then bDontTryAndDodge = true end
                                                    end
                                                end
                                            end
                                        end
                                    elseif oUnit:IsUnitState('Teleporting') then
                                        bDontTryAndDodge = true
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': bDontTryAndDodge after checking if upgrading='..tostring(bDontTryAndDodge)) end
                                    if not(bDontTryAndDodge) then
                                        --Is there a significant enemy land threat and we are against a T1 bomber?
                                        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition(), true, oUnit)
                                        if iLandZone > 0 and EntityCategoryContains(categories.TECH1, oBomber.UnitId) and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam][AiBotMap.subrefTThreatEnemyCombatTotal] * 1.2 > math.min(300, AiBotUnitInfo.GetCombatThreatRating({ oUnit }, false, false, false, false, false, false, false)) then
                                            bDontTryAndDodge = true
                                        end
                                    end

                                    if not(bDontTryAndDodge) then
                                        if oUnit[AiBotUnitInfo.refbSpecialMicroActive] and not(EntityCategoryContains(categories.AIR, oUnit.UnitId)) and not(oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive]) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will move in a circle as micro is already active') end
                                            MoveInCircleTemporarily(oUnit, iTimeToRun)
                                        else
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will move away from bomb target temporarily') end
                                            MoveAwayFromTargetTemporarily(oUnit, iTimeToRun, tBombTarget)
                                            oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] = GetGameTimeSeconds()
                                        end
                                    end

                                else
                                    --If we are already in the process of dodging then dont try dodging some more, unless our micro is about to expire
                                    if oUnit[AiBotUnitInfo.refbSpecialMicroActive] and not(oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive]) and (oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 0) - GetGameTimeSeconds() > 0.5 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Unit has recently tried dodging so dont want to give it another dodge order as it might end up not moving') end
                                    else
                                        --Are we a mobile shield that isn't on the same team as the bomber? If so, then dont worry about dodging
                                        if not(EntityCategoryContains(AiBotUnitInfo.refCategoryMobileLandShield, oUnit.UnitId)) or not(oUnit.MyShield.GetHealth) or oUnit.MyShield:GetHealth() == 0 or not(oUnit.MyShield.Enabled) or oUnit.MyShield.DepletedByEnergy then
                                            if bDontCheckIfFriendlyGunships or not(EntityCategoryContains(AiBotUnitInfo.refCategoryGunship, oUnit.UnitId)) or not(oUnit:GetAIBrain().AiBotTeam == oBomber:GetAIBrain().AiBotTeam) then
                                                if not(EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId)) or (oUnit:GetWorkProgress() or 0) == 0 or not(AreUnderFixedShield(oUnit)) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': about to call moveawayfromtargettemporarily') end
                                                    MoveAwayFromTargetTemporarily(oUnit, iTimeToRun, tBombTarget)
                                                    oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] = GetGameTimeSeconds()
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    else
        if bDebugMessages == true then LOG(sFunctionRef..': tBombTarget is nil or are in LOUD') end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedRemovalOfTargetToAvoid(tTargetLZTeamData, tTargetToAvoid, iDelayInSeconds)
    WaitSeconds(iDelayInSeconds)
    if AiBotUtilities.IsTableEmpty(tTargetLZTeamData[AiBotMap.reftiLocationsToAvoid]) == false then
        for iEntry, tEntry in tTargetLZTeamData[AiBotMap.reftiLocationsToAvoid] do
            if tEntry[1] == tTargetToAvoid[1] and tEntry[3] == tTargetToAvoid[3] then
                table.remove(tTargetLZTeamData[AiBotMap.reftiLocationsToAvoid], iEntry)
                break
            end
        end
    end
end

function ConsiderDodgingShot(oUnit, oWeapon)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderDodgingShot'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(ScenarioInfo.Options.AiBotDodgeMicro == 2) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout, oUnit.UnitId)) then
        local oWeaponBP = oWeapon.Blueprint or oWeapon.bp
        if bDebugMessages == true then
            LOG(sFunctionRef..': Just fired, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit combat range='..(oUnit[AiBotUnitInfo.refiCombatRange] or 'nil')..'; oWeaponBP.RangeCategory='..(oWeaponBP.RangeCategory or 'nil'))
            if oWeapon.GetCurrentTarget then
                LOG(sFunctionRef..': Is current target valid='..tostring(AiBotUnitInfo.IsUnitValid(oWeapon:GetCurrentTarget()))..'; Weapon category='..(oWeaponBP.WeaponCategory or 'nil')..'; ManualFire='..tostring(oWeaponBP.ManualFire or false))
                if not(AiBotUnitInfo.IsUnitValid(oWeapon:GetCurrentTarget())) then
                    LOG(sFunctionRef..': Invalid target, will do reprs of it:'..reprs(oWeapon:GetCurrentTarget())..' will also draw black square around the weapon target position which is '..repru(oWeapon:GetCurrentTargetPos()))
                    local tCurTargetPos = oWeapon:GetCurrentTargetPos()
                    if AiBotUtilities.IsTableEmpty(tCurTargetPos) == false then
                        AiBotUtilities.DrawLocation(tCurTargetPos, nil, 3, 200)
                    end
                else
                    LOG(sFunctionRef..': Valid target='..oWeapon:GetCurrentTarget().UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oWeapon:GetCurrentTarget()))
                end
            else
                LOG(sFunctionRef..': Dont have a current target for this weapon')
            end
        end
        --Direct fire, t1 mobile arti, t2 mobile missile launchers, Cruiser missiles, and experimental land
        if oWeapon.GetCurrentTarget and (oWeaponBP.WeaponCategory == 'Direct Fire' or oWeaponBP.WeaponCategory == 'Direct Fire Naval' or oWeaponBP.WeaponCategory == 'Direct Fire Experimental' or (oWeaponBP.WeaponCategory == 'Artillery' and EntityCategoryContains(categories.TECH1, oUnit.UnitId)) or (oWeaponBP.WeaponCategory == 'Missile' and oWeaponBP.MaxRadius <= 80) or (not(AiBotUtilities.bFAFActive) and (oUnit[AiBotUnitInfo.refiCombatRange] or 0) > 0 and (oWeaponBP.RangeCategory == 'UWRC_IndirectFire' or oWeaponBP.RangeCategory == 'UWRC_DirectFire'))) or (oWeaponBP.WeaponCategory == 'Indirect Fire' and oWeaponBP.MuzzleVelocity <= 25) or (oWeaponBP.WeaponCategory == 'Missile' and not(oWeaponBP.ManualFire)) then
            if bDebugMessages == true then LOG(sFunctionRef..': Have a valid weapon category, will see if have targets to consider dodging') end
            local oWeaponTarget
            local iRadiusSize = math.min(5, 1 + math.max(oWeaponBP.DamageRadius + 0.5 + 7 * (oWeaponBP.FiringRandomness or 0), 1))
            local tWeaponTarget
            if oWeapon.GetCurrentTarget and not(oWeapon:BeenDestroyed()) then oWeaponTarget = oWeapon:GetCurrentTarget() end
            local bConsiderUnitsInArea = false
            if not(AiBotUnitInfo.IsUnitValid(oWeaponTarget)) or EntityCategoryContains(categories.NAVAL * categories.MOBILE, oWeaponTarget.UnitId) or ((oWeaponBP.DamageRadius or 0) >= 1 and ((oWeaponBP.FiringTolerance or 0) >= 0.5 or oWeapon.WeaponCategory == 'Artillery')) then bConsiderUnitsInArea = true end

            local tUnitsToConsiderDodgeFor = {}

            function ConsiderAddingUnitToTable(oCurUnit, bIncludeBusyUnits)
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we should add oCurUnit='..oCurUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oCurUnit)..'; Brain='..oCurUnit:GetAIBrain().Nickname..'; Unit state='..AiBotUnitInfo.GetUnitState(oCurUnit)..'; Special micro active='..tostring(oCurUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Time='..GetGameTimeSeconds()..'; refiGameTimeToResetMicroActive='..(oCurUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 'nil')..'; are under fixed shield='..tostring(AreUnderFixedShield(oCurUnit) or false)) end
                local aiBrain = oCurUnit:GetAIBrain()
                --AiBotEasy - dont dodge unless damaged ACU dodging t1 arti fire
                if aiBrain.AiBotAI and (not(aiBrain.AiBotEasy) or (oCurUnit[AiBotACU.refbTreatingAsACU] and oCurUnit:GetHealthPercent() < 0.9 and EntityCategoryContains(AiBotUnitInfo.refCategoryIndirect * categories.TECH1, oUnit.UnitId))) and (not(aiBrain[refiMaxUnitsToDodgeMicroAtOnce]) or aiBrain[refiCurUnitsDodging] < aiBrain[refiMaxUnitsToDodgeMicroAtOnce]) and (bIncludeBusyUnits or (not(oCurUnit:IsUnitState('Upgrading')) and (not(oCurUnit[AiBotUnitInfo.refbSpecialMicroActive]) or oCurUnit[AiBotUnitInfo.refbLowerPriorityMicroActive]))) then
                    if EntityCategoryContains(categories.AIR + categories.STRUCTURE, oCurUnit.UnitId) then
                        --Do nothing
                    elseif EntityCategoryContains(categories.MOBILE, oCurUnit.UnitId) then
                        if oCurUnit:GetFractionComplete() == 1 and AiBotUnitInfo.IsUnitValid(oCurUnit) then
                            if not(oUnit[AiBotUnitInfo.refbEasyBrain]) then
                                --Engineers - dont dodge if almost done construction or dodging bomb and under fixed shield
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oCurUnit.UnitId) and (oCurUnit:GetWorkProgress() >= 0.4 and (oCurUnit:GetWorkProgress() >= 0.95 or ((oWeaponBP.Damage or 100) <= 50 and (oCurUnit:GetWorkProgress() >= 0.8 or oCurUnit:GetFocusUnit().UnitId and EntityCategoryContains(categories.DEFENSE, oCurUnit:GetFocusUnit().UnitId))))) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Wont dodge shot as almost done with construction or low damaage shot and we are building defensive unit, work progress='..oCurUnit:GetWorkProgress()..'; Weapon damage='..(oWeaponBP.Damage or 'nil')) end
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': Added unit to table of units to consider dodging for') end
                                    table.insert(tUnitsToConsiderDodgeFor, oCurUnit)
                                end
                            end
                        end
                    end
                end
            end
            local bIncludeBusyUnits = false
            if oWeaponBP.Damage >= 5000 then bIncludeBusyUnits = true end
            if not(bConsiderUnitsInArea) then
                --Is it a unit with a shield?
                if EntityCategoryContains(categories.SHIELD, oWeaponTarget.UnitId) then
                    --local iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oWeaponTarget, true)
                    if oUnit.MyShield.GetHealth and oUnit.MyShield:GetHealth() > 0 then --was 0.2 pre-v130, and 0.05 pre v150
                        ConsiderAddingUnitToTable(oWeaponTarget, bIncludeBusyUnits)
                    end
                else
                    ConsiderAddingUnitToTable(oWeaponTarget, bIncludeBusyUnits)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Dont want to consider units in area so will only consider oWeaponTarget') end

            else
                --Does the weapon have an aoe?
                if bDebugMessages == true then LOG(sFunctionRef..': oWeaponBP.DamageRadius='..(oWeaponBP.DamageRadius or 'nil')..'; will consider units in an area if it is an aoe attack, oWeaponTarget='..(oWeaponTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oWeaponTarget) or 'nil')) end
                if (oWeaponBP.DamageRadius or 0) > 0.1 then
                    --Get all units in area
                    if oWeaponTarget then
                        tWeaponTarget = oWeaponTarget:GetPosition()
                        --Add to list of locations in the zone to avoid if its an AiBot unit  and we arent getting close to unit cap and early-mid game
                        --Commented out as not sure it makes things better
                        --[[if oWeaponTarget:GetAIBrain().AiBotAI and GetGameTimeSeconds() <= 1800 and (oWeaponTarget:GetAIBrain()[AiBotOverseer.refiExpectedRemainingCap] or 0) >= 200 and tWeaponTarget[2] >= AiBotMap.iMapWaterHeight then
                            local tTargetLZData, tTargetLZTeamData = AiBotMap.GetLandOrWaterZoneData(tWeaponTarget, true, oWeaponTarget:GetAIBrain().AiBotTeam)
                            local iExistingEntries = 0
                            if AiBotUtilities.IsTableEmpty(tTargetLZTeamData[AiBotMap.reftiLocationsToAvoid]) == false then
                                iExistingEntries = table.getn(tTargetLZTeamData[AiBotMap.reftiLocationsToAvoid])
                            else
                                tTargetLZTeamData[AiBotMap.reftiLocationsToAvoid] = {}
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iExistingEntries in locations to avoid='..iExistingEntries..'; if <10 then will insert') end
                            if iExistingEntries < 10 then
                                local tTargetToAvoid = {tWeaponTarget[1], tWeaponTarget[2], tWeaponTarget[3]}
                                table.insert(tTargetLZTeamData[AiBotMap.reftiLocationsToAvoid], tTargetToAvoid)
                                ForkThread(DelayedRemovalOfTargetToAvoid, tTargetLZTeamData, tTargetToAvoid, 3)
                            end
                        end--]]
                    else
                        tWeaponTarget = oWeapon:GetCurrentTargetPos()
                    end

                    if AiBotUtilities.IsTableEmpty(tWeaponTarget) == false then
                        if bDebugMessages == true then LOG(sFunctionRef..': iRadiusSize='..iRadiusSize..'; based ond amage radius='..oWeaponBP.DamageRadius..'; and firing randomness='..(oWeaponBP.FiringRandomness or 'nil')..'; will draw weapon target')
                            AiBotUtilities.DrawLocation(tWeaponTarget, 1)
                        end
                        local tAllUnitsInArea = GetUnitsInRect(Rect(tWeaponTarget[1]-iRadiusSize, tWeaponTarget[3]-iRadiusSize, tWeaponTarget[1]+iRadiusSize, tWeaponTarget[3]+iRadiusSize))
                        if AiBotUtilities.IsTableEmpty(tAllUnitsInArea) == false then
                            --Do we have shield units in the area with at least 20% shield? Will assume shield covers all the units
                            local tShieldsInArea = EntityCategoryFilterDown(categories.SHIELD, tAllUnitsInArea)
                            local bUnderMobileShield = false
                            if AiBotUtilities.IsTableEmpty(tShieldsInArea) == false then
                                local iCurShield, iMaxShield
                                for iShield, oShield in tShieldsInArea do
                                    iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, true)
                                    if bDebugMessages == true then LOG(sFunctionRef..': oCurUnit='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; iCurShield='..iCurShield..'; iMaxShield='..iMaxShield) end
                                    if (iCurShield or 0) > (iMaxShield or 0) * 0.2 then
                                        bUnderMobileShield = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Unit has at least 20% shield remaining so wont dodge') end
                                        break
                                    end
                                end
                            end
                            if not(bUnderMobileShield) then
                                for iNearbyUnit, oNearbyUnit in tAllUnitsInArea do
                                    --Exclude shields (note we also exclude shields that are directly targeted further above)
                                    if oUnit.MyShield.GetHealth and oUnit.MyShield:GetHealth() > 0 and (oUnit:GetBlueprint().Defense.Shield.ShieldSize or 0) > 1.5 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Mobile shield that is still active so wont try and dodge') end
                                    else
                                        ConsiderAddingUnitToTable(oNearbyUnit, bIncludeBusyUnits)
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of units to consider dodging empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToConsiderDodgeFor))..'; Weapon damage='..oWeaponBP.Damage) end
            if AiBotUtilities.IsTableEmpty(tUnitsToConsiderDodgeFor) == false then
                local bOnlyDodgeIfNotMoving = false
                --Calculate time to impact
                local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oWeapon:GetCurrentTargetPos())
                local iMaxTimeToRun = 3
                if oWeaponBP.WeaponCategory == 'Artillery' or ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and oWeaponBP.BallisticArc == 'RULEUBA_HighArc') then
                    iDistToTarget = iDistToTarget + 15
                    iMaxTimeToRun = 0.8
                elseif oWeaponBP.WeaponCategory == 'Missile' or oWeaponBP.Label == 'MissileWeapon' or oWeaponBP.Label == 'MissileRack' then
                    iDistToTarget = iDistToTarget + 10
                    iMaxTimeToRun = 0.8
                    if tWeaponTarget and iRadiusSize then
                        bOnlyDodgeIfNotMoving = true
                    end
                end
                local iShotSpeed = oWeaponBP.MuzzleVelocity
                if (iShotSpeed or 0) > 0 then --laser is 0
                    local iTimeUntilImpact = iDistToTarget / iShotSpeed
                    local bCancelDodge = false
                    local iHoverMaxTimeToRun

                    if iMaxTimeToRun < 1.1 then iHoverMaxTimeToRun = 1.1 end
                    if bDebugMessages == true then LOG(sFunctionRef..': Dist to target='..iDistToTarget..'; Shot speed='..iShotSpeed..'; iTimeUntilImpact='..iTimeUntilImpact..'; Is weapon target a bot='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryLightAttackBot, (oWeaponTarget.UnitId or 'uel0001')))..'; bOnlyDodgeIfNotMoving='..tostring(bOnlyDodgeIfNotMoving)..'; tWeaponTarget='..repru(tWeaponTarget)..'; iRadiusSize='..(iRadiusSize or 'nil')..'; oWeaponBP.WeaponCategory='..(oWeaponBP.WeaponCategory or 'nil')..'; oWeaponBP.Label='..(oWeaponBP.Label or 'nil')..'; bOnlyDodgeIfNotMoving='..tostring(bOnlyDodgeIfNotMoving)) end
                    if iTimeUntilImpact > 0.8 or (oWeaponTarget and EntityCategoryContains(AiBotUnitInfo.refCategoryLightAttackBot, oWeaponTarget.UnitId) and iTimeUntilImpact >= 0.2) then
                        for iTarget, oTarget in tUnitsToConsiderDodgeFor do
                            bCancelDodge = false
                            if bDebugMessages == true then LOG(sFunctionRef..': oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..'; Weapon damage='..oWeaponBP.Damage..'; Target health='..oTarget:GetHealth()) end
                            --Does the shot do enough damage that we want to try and dodge it? (experimentals - consider high damage shots like ythotha ball)
                            if ((oTarget[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oTarget)) < 12500 or oWeaponBP.Damage >= 3000) and (oWeaponBP.Damage / oTarget:GetHealth() >= 0.01 or (EntityCategoryContains(categories.COMMAND, oTarget.UnitId) and ((oWeaponBP.WeaponCategory == 'Artillery' and EntityCategoryContains(categories.INDIRECTFIRE - categories.TECH3, oUnit.UnitId) and (oWeaponBP.Damage / oTarget:GetHealth() >= 0.0035)) or (oWeaponBP.WeaponCategory == 'Missile' and EntityCategoryContains(categories.INDIRECTFIRE - categories.TECH3, oUnit.UnitId) and (oWeaponBP.Damage / oTarget:GetHealth() >= 0.006))))) then
                                --Dont bother dodging if missile attack and we are moving away from it
                                if bOnlyDodgeIfNotMoving then
                                    local tFirstOrder = oUnit[AiBotOrders.reftiLastOrders][1]
                                    if bDebugMessages == true then LOG(sFunctionRef..': Only want to dodge if we are moving and will be far away from the waepon target, order type='..(tFirstOrder[AiBotOrders.subrefiOrderType] or 'nil')..'; Dist from weapon target='..AiBotUtilities.GetDistanceBetweenPositions(tWeaponTarget, oUnit:GetPosition())..'; iRadiusSize='..iRadiusSize) end
                                    if tFirstOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueMove and AiBotUtilities.GetDistanceBetweenPositions(tWeaponTarget, oUnit:GetPosition()) > 2 + iRadiusSize then
                                        bCancelDodge = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Dodging missile - we are already planning on moving away from the missile') end
                                    end
                                end
                                if not(bCancelDodge) then
                                    --Do we think we can dodge the shot?
                                    --If we are a large unit then only dodge if will be a while for the shot to hit
                                    local oBP = oTarget:GetBlueprint()
                                    if not(oBP.SizeX) then oBP = __blueprints[oTarget.UnitId] end
                                    local iAverageSize = (oBP.SizeX + oBP.SizeZ) * 0.5
                                    local iExpectedTimeWanted = math.min(2.5, 0.4 + iAverageSize * 1.5 / oBP.Physics.MaxSpeed)
                                    if bDebugMessages == true then LOG(sFunctionRef..': iAverageSize='..iAverageSize..'; Is unit underwater='..tostring(AiBotUnitInfo.IsUnitUnderwater(oTarget))..'; SizeY='..oBP.SizeY..'; Terrain height='..GetTerrainHeight(oTarget:GetPosition()[1], oTarget:GetPosition()[3])..'; Surface height='..GetSurfaceHeight(oTarget:GetPosition()[1], oTarget:GetPosition()[3])..'; water height='..AiBotMap.iMapWaterHeight..'; aoe='..(oWeaponBP.DamageRadius or 'nil')..'; oTarget max speed='..oBP.Physics.MaxSpeed..'; iTimeUntilImpact='..iTimeUntilImpact..'; iExpectedTimeWanted='..iExpectedTimeWanted..'; speed of oTarget='..AiBotUnitInfo.GetUnitSpeed(oTarget)) end
                                    if iAverageSize < 0.89 or ((iTimeUntilImpact >= 2 or not(EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId)) and (iTimeUntilImpact > iExpectedTimeWanted) or (oTarget and iTimeUntilImpact >= 1.2 and oWeaponBP.Damage >= 300 and iTimeUntilImpact + 0.3 > iExpectedTimeWanted and oBP.Physics.MaxSpeed >= 4 and AiBotUnitInfo.GetUnitSpeed(oTarget) >= 2.5))) then
                                        --Are we not underwater?
                                        if not(AiBotUnitInfo.IsUnitUnderwater(oTarget)) then
                                            --If dealing with an ACU then drastically reduce the dodge time so we can overcharge if we havent recently and have enemies in range and enough power
                                            if EntityCategoryContains(categories.COMMAND, oTarget.UnitId) then
                                                if oTarget:IsUnitState('Teleporting') or (oTarget:IsUnitState('Upgrading') and AiBotUnitInfo.GetUnitHealthPercent(oTarget) >= 0.9 - oTarget:GetWorkProgress()) then
                                                    --Dont cancel upgrade/teleport
                                                    bCancelDodge = true
                                                    --Dont have ACU dodge missiles if it is retreating (since missiles arent homing)
                                                elseif oTarget:IsUnitState('Moving') and GetGameTimeSeconds() - (oTarget[AiBotACU.refiTimeLastWantedToRun] or 0) <= 2 and oWeaponBP.WeaponCategory == 'Missile' and EntityCategoryContains(categories.INDIRECTFIRE - categories.STRUCTURE, oUnit.UnitId) and oTarget[AiBotOrders.reftiLastOrders][oTarget[AiBotOrders.refiOrderCount]][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueMove and AiBotUtilities.GetDistanceBetweenPositions(oTarget[AiBotOrders.reftiLastOrders][oTarget[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition], oTarget:GetPosition()) >= 5 then
                                                    bCancelDodge = true
                                                elseif AiBotConditions.CanUnitUseOvercharge(oTarget:GetAIBrain(), oTarget) and (GetGameTimeSeconds() - (oTarget[AiBotUnitInfo.refiTimeOfLastOverchargeShot] or 0)) > 5 then
                                                    --If we have units we can hit then cancel
                                                    if oTarget:GetHealth() >= 5000 and (GetGameTimeSeconds() - (oTarget[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= 2 or AiBotUtilities.IsTableEmpty(oTarget:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat, oTarget:GetPosition(), oTarget[AiBotUnitInfo.refiDFRange], 'Enemy')) == false) then
                                                        bCancelDodge = true
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will cancel dodge as we can overcharge instead, time since last overcharge='..(GetGameTimeSeconds() - (oTarget[AiBotUnitInfo.refiTimeOfLastOverchargeShot] or 0))..'; Brain energy stored='..oTarget:GetAIBrain():GetEconomyStored('ENERGY')) end
                                                    else
                                                        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition(), true, oUnit)
                                                        local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam]
                                                        if tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 200 then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Reducing dodge time drastically as have ACU that can overcharge enemies in range but it also wants to dodge a shot; will cancel if damage is very low that are dodging. oWeaponBP.Damage='..oWeaponBP.Damage) end
                                                            if oWeaponBP.Damage <= 100 then
                                                                bCancelDodge = true
                                                            else
                                                                iMaxTimeToRun = math.min(0.8, iMaxTimeToRun) --(M27 uses 0.9; if set too low then ACU may not actually move)
                                                            end
                                                        end
                                                    end
                                                end
                                            elseif EntityCategoryContains(categories.EXPERIMENTAL, oTarget.UnitId) then
                                                --If we are a GC, Monkey or Ythotha that has an enemy experimental nearby but not in range, then cancel dodging as want to get in range to be able to  fire
                                                local oTargetBP = oTarget:GetBlueprint()
                                                if not(oTargetBP.SizeX) then oTargetBP = __blueprints[oTarget.UnitId] end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Deciding if experimental wants to dodge shot, iDistToTarget='..iDistToTarget..'; Damage='..oWeaponBP.Damage..'; Experimental size='..math.max(oTargetBP.SizeX, oTargetBP.SizeZ)..'; Time since last weapon event='..GetGameTimeSeconds() - (oTarget[AiBotUnitInfo.refiLastWeaponEvent] or 0)) end
                                                --Dont dodge at all if we have fired recently and the damage isn't massive
                                                if GetGameTimeSeconds() - (oTarget[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= 5 and oWeaponBP.Damage <= 4000 then
                                                    bCancelDodge = true
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Target is an experimental that has fired recently and the damage isnt massive so we dont want to dodge, weapon damage='..(oWeaponBP.Damage or 'nil')) end
                                                elseif iDistToTarget <= 90 and math.max(oTargetBP.SizeX, oTargetBP.SizeZ) >= 7 and (GetGameTimeSeconds() - (oTarget[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= 20 or oWeaponBP.Damage <= 4000) then --megalith and fatboy
                                                    bCancelDodge = true
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Megalith or fatboy in size so wont dodge shot') end
                                                else
                                                    local tLastOrder = oTarget[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]]
                                                    if tLastOrder[AiBotOrders.refiOrderIssueAttack] and AiBotUnitInfo.IsUnitValid(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental + categories.COMMAND, tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId) and (not(EntityCategoryContains(AiBotUnitInfo.refCategoryYthotha, tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId)) or oWeaponBP.Damage <= 4000) then
                                                        bCancelDodge = true
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Target '..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..' was trying to attack an enemy exp or ACU, targets target='..tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tLastOrder[AiBotOrders.subrefoOrderUnitTarget])..'; so will cancel dodge') end
                                                    end
                                                end
                                                if not(bCancelDodge) and not(oUnit[AiBotUnitInfo.refbCanKite]) then
                                                    --Special case - if dealing with say a GC that is trying to dodge a shot from a ythotha, then get its facing to that unit, and dont dodge if angle dif is so large that it would likely cause it to stop firing at the unit if it was to dodge
                                                    if oTarget.UnitId == 'ual0401' and oUnit.UnitId and AiBotUtilities.GetDistanceBetweenPositions(oTarget:GetPosition(), oUnit:GetPosition()) <= oTarget[AiBotUnitInfo.refiDFRange] then
                                                        local iCurFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oTarget)
                                                        local iAngleToAttacker = AiBotUtilities.GetAngleFromAToB(oTarget:GetPosition(), oUnit:GetPosition())
                                                        local iAngleDif = AiBotUtilities.GetAngleDifference(iCurFacingAngle, iAngleToAttacker)
                                                        if iAngleDif > 15 then bCancelDodge = true end
                                                        if bDebugMessages == true then LOG(sFunctionRef..'; Considering whether to abort dodge, iAngleDif='..iAngleDif..'; bCancelDodge='..tostring(bCancelDodge)) end
                                                    end
                                                end
                                            end

                                            if not(bCancelDodge) then
                                                iMaxTimeToRun = math.min(2.5, iMaxTimeToRun)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will try to dodge shot. iTimeUntilImpact='..iTimeUntilImpact..'; iMaxTimeToRun='..iMaxTimeToRun..'; iAverageSize='..iAverageSize) end
                                                if iHoverMaxTimeToRun and EntityCategoryContains(categories.HOVER, oTarget.UnitId) then
                                                    DodgeShot(oTarget, oUnit, oWeapon, math.min(math.max(0.95, iTimeUntilImpact), iHoverMaxTimeToRun))
                                                elseif iAverageSize < 1 and iTimeUntilImpact <= 1.1 and oBP.Physics.MaxSpeed >= 3 and oBP.Physics.MaxAcceleration >= 3 and not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher, oTarget.UnitId)) then
                                                    AltDodgeShot(oTarget, oUnit, oWeapon, math.min(iTimeUntilImpact, iMaxTimeToRun))
                                                else
                                                    DodgeShot(oTarget, oUnit, oWeapon, math.min(iTimeUntilImpact, iMaxTimeToRun))
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DodgeShot(oTarget, oOptionalWeapon, oAttacker, iTimeToDodge)
    --Should have already checked oTarget is a valid unit that has a chance of dodging the shot in time before claling this
    --Gets unit to move at a slightly different angle to its current facing direction for iTimeToDodge
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DodgeShot'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..'; oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..' owned by brain '..oTarget:GetAIBrain().Nickname..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oTarget))..'; oAttacker='..(oAttacker.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oAttacker) or 'nil')..'; Attacker assigned LZ for oUnit team='..(oAttacker[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][oTarget:GetAIBrain().AiBotTeam][2] or 'nil')) end

    local bAdjustDodgeMicroCount = false
    local bContinue = true
    if not(ScenarioInfo.Options.AiBotDodgeMicro == 1) then
        local aiBrain = oTarget:GetAIBrain()
        local iCurUnitsDodging = aiBrain[refiCurUnitsDodging]
        local iMaxUnitsToDodge = aiBrain[refiMaxUnitsToDodgeMicroAtOnce]
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if have too many units dodging at once, aiBrain[refiCurUnitsDodging]='..tostring(iCurUnitsDodging)..' ('..type(iCurUnitsDodging)..'); aiBrain[refiMaxUnitsToDodgeMicroAtOnce]='..tostring(iMaxUnitsToDodge)..' ('..type(iMaxUnitsToDodge)..')') end
        if type(iCurUnitsDodging) == 'number' and type(iMaxUnitsToDodge) == 'number' and iCurUnitsDodging >= iMaxUnitsToDodge then
            bContinue = false
        else
            aiBrain[refiCurUnitsDodging] = (type(iCurUnitsDodging) == 'number' and iCurUnitsDodging or 0) + 1
            bAdjustDodgeMicroCount = true
        end
    end
    if bContinue then

        AiBotOrders.UpdateRecordedOrders(oTarget)
        local tCurDestination
        local bAttackMove = false
        --ACU special - if ACU wants to run, then ignore hte last order and instead treat it as tyring to run to base
        if (oTarget[AiBotACU.refiTimeLastWantedToRun] and GetGameTimeSeconds() - (oTarget[AiBotACU.refiTimeLastWantedToRun] or -100) <= 5) or ((EntityCategoryContains(categories.COMMAND, oTarget.UnitId) and AiBotUnitInfo.GetUnitHealthPercent(oTarget) <= 0.6 and not(oTarget[AiBotACU.refbUseACUAggressively]) and oTarget:GetAIBrain()[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 1)) then
            local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oTarget:GetPosition(), true, oTarget:GetAIBrain().AiBotTeam)

            if tLZOrWZTeamData then
                if AiBotConditions.BaseIsSafeToRetreatTo(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], oTarget:GetAIBrain().AiBotTeam) or (AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) and not(tLZOrWZData[AiBotMap.subrefWZTeamData])) then
                    tCurDestination = {tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][1], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][2], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
                    if bDebugMessages == true then LOG(sFunctionRef..': setting ACU tCurDestination as the closest friendly base if it is in a valid zone, as it has recently tried running') end
                else
                    local iCurDistLessRange
                    local iClosestEnemyDistLessRange = 10000
                    local oClosestEnemy
                    function ConsiderNearestEnemy(tEnemies)
                        for iEnemy, oEnemy in tEnemies do
                            if not(oEnemy.Dead) then
                                iCurDistLessRange = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oTarget:GetPosition()) - (oEnemy[AiBotUnitInfo.refiDFRange] or 0)
                                if iCurDistLessRange < iClosestEnemyDistLessRange then
                                    iClosestEnemyDistLessRange = iCurDistLessRange
                                    oClosestEnemy = oEnemy
                                end
                            end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                        ConsiderNearestEnemy(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies])
                        --If have water zone check for nearby land zones if we arent underwater
                    elseif tLZOrWZData[AiBotMap.subrefWZTeamData] and not(AiBotUnitInfo.IsUnitUnderwater(oTarget)) then
                        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestCombatEnemies]) == false then
                            ConsiderNearestEnemy(tLZOrWZTeamData[AiBotMap.reftoNearestCombatEnemies])
                        end
                        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                            local iTeam = oTarget:GetAIBrain().AiBotTeam
                            for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefAdjacentLandZones] do
                                local tAdjLZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]]
                                local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                    ConsiderNearestEnemy(tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies])
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': the base isnt safe and we have nearby DF enemies so will assume wanted to run from nearest DF enemy, oClosestEnemy='..oClosestEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy)) end
                    if oClosestEnemy then
                        local iAngleFromNearestEnemy = AiBotUtilities.GetAngleFromAToB(oClosestEnemy:GetPosition(), oTarget:GetPosition())
                        local tPotentialMovePoint
                        local iDistToMove = 10
                        local iPlateauWanted = NavUtils.GetLabel(AiBotMap.refPathingTypeAmphibious, oTarget:GetPosition())
                        local bHaveMovePoint
                        for iAngleAdjust = 0, 45, 15 do
                            for iAngleFactor = -1, 1 do
                                if iAngleFactor == -1 or iAngleAdjust > 0 then
                                    tPotentialMovePoint = AiBotUtilities.MoveInDirection(oTarget:GetPosition(), iAngleFromNearestEnemy + iAngleAdjust * iAngleFactor, iDistToMove, false, false, false)
                                    if AiBotUtilities.IsTableEmpty(tPotentialMovePoint) == false and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeAmphibious,  tPotentialMovePoint) == iPlateauWanted then
                                        tCurDestination = {tPotentialMovePoint[1], tPotentialMovePoint[2], tPotentialMovePoint[3]}
                                        bHaveMovePoint = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have a run location we can path to, iAngleFactor='..iAngleFactor..'; iAngleAdjust='..iAngleAdjust) end
                                        break
                                    end
                                end
                                if bHaveMovePoint then break end
                            end
                            if bHaveMovePoint then break end
                        end
                    end
                end
            end
        elseif EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher + AiBotUnitInfo.refCategoryIndirect - categories.EXPERIMENTAL, oTarget.UnitId) then
            local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oTarget:GetPosition(), true, oTarget:GetAIBrain().AiBotTeam)
            if tLZOrWZTeamData then tCurDestination = {tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][1], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][2], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][3]} end
        elseif oTarget[AiBotOrders.refiOrderCount] > 0 then
            if oTarget[AiBotOrders.reftMoveDestinationIgnoredDueToMicro] then tCurDestination = {oTarget[AiBotOrders.reftMoveDestinationIgnoredDueToMicro][1], oTarget[AiBotOrders.reftMoveDestinationIgnoredDueToMicro][2], oTarget[AiBotOrders.reftMoveDestinationIgnoredDueToMicro][3]}
            else
                local tLastOrder = oTarget[AiBotOrders.reftiLastOrders][oTarget[AiBotOrders.refiOrderCount]]
                tCurDestination = tLastOrder[AiBotOrders.subreftOrderPosition]
                if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack or tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAggressiveMove or tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAggressiveFormMove then
                    bAttackMove = true
                end
            end
        end

        local iCurFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oTarget)
        local iAngleToDestination
        if tCurDestination then iAngleToDestination = AiBotUtilities.GetAngleFromAToB(oTarget:GetPosition(), tCurDestination)
        else
            iAngleToDestination = iCurFacingAngle
            tCurDestination = oTarget:GetPosition()
        end

        local oBP = oTarget:GetBlueprint()
        if not(oBP.SizeX) then oBP = __blueprints[oTarget.UnitId] end
        local iSpeed = oBP.Physics.MaxSpeed
        local iDistanceToRun = (iTimeToDodge + (AiBotLand.iTicksPerLandCycle - 1) / 10) * iSpeed
        local iUnitSize = oBP.SizeX + oBP.SizeZ
        local iAngleAdjust = math.max(15, oBP.Physics.TurnRate * 0.3)
        if iUnitSize >= 2 then
            if iUnitSize >= 4 then iAngleAdjust = iAngleAdjust * 2.5
            else iAngleAdjust = iAngleAdjust * 1.75
            end
            if EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oTarget.UnitId) then
                iAngleAdjust = math.min(iAngleAdjust, 30)
            end
        end
        local bRunAwayFromNearestEnemy = false

        --Non-experimental skirmishers - try to move at an adjustment to the angle to the destination rather htan the unit facing direction so less likely to move into range of enemy
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if have skirmisher or ACU; ACU time since last wanted to retreat (if this was an ACU)='..GetGameTimeSeconds() - (oTarget[AiBotACU.refiTimeLastWantedToRun] or 0)..'; Time since last wanted to retreat for non-ACU='..GetGameTimeSeconds() - (oTarget[AiBotUnitInfo.refiTimeLastTriedRetreating] or 0)..'; oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]='..(oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) or 'nil')) end
        if EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher - categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryLandScout, oTarget.UnitId) or (oTarget[AiBotUnitInfo.refiTimeLastTriedRetreating] and GetGameTimeSeconds() - oTarget[AiBotUnitInfo.refiTimeLastTriedRetreating] <= math.max(2, AiBotLand.iTicksPerLandCycle * 0.1 + 0.1)) or (EntityCategoryContains(categories.COMMAND, oTarget.UnitId) and oTarget[AiBotACU.refiTimeLastWantedToRun] and GetGameTimeSeconds() - oTarget[AiBotACU.refiTimeLastWantedToRun] <= 3)
                --MMLs - we might be near PD meaning dodging will take us in range of it
                or ((oTarget[AiBotUnitInfo.refiIndirectRange] or 0) > 0 and not(EntityCategoryContains(categories.TECH1, oTarget.UnitId)) and not(oTarget[AiBotUnitInfo.refbSpecialMicroActive]) and not(oTarget[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueMove)) then
            if bDebugMessages == true then LOG(sFunctionRef..': Is oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] valid='..tostring(AiBotUnitInfo.IsUnitValid(oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]))) end
            if AiBotUnitInfo.IsUnitValid(oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) and (oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 0) > 0 then
                local iDistToNearestEnemy = AiBotUtilities.GetDistanceBetweenPositions(oTarget:GetPosition(), oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())
                --If we went towards this unit are we likely getting into its DF range?
                if bDebugMessages == true then LOG(sFunctionRef..': iDistToNearestEnemy='..iDistToNearestEnemy..'; Target[refoClosestEnemyFromLastCloseToEnemyUnitCheck] DF range='..(oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] or 'nil')) end
                if iDistToNearestEnemy - 10 < oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] then
                    bRunAwayFromNearestEnemy = true
                end
            end
            if not(bRunAwayFromNearestEnemy) then
                local iAngleDifToDestination = AiBotUtilities.GetAngleDifference(iCurFacingAngle, iAngleToDestination)
                if bDebugMessages == true then LOG(sFunctionRef..': iAngleDifToDestination='..iAngleDifToDestination..'; iAngleAdjust='..iAngleAdjust) end
                if iAngleDifToDestination >= math.max(iAngleAdjust, 45) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Increasing angle adjust as have a skirmisher or retreating ACU, iAngleAdjust before increase='..iAngleAdjust..'; iAngleDifToDestination='..iAngleDifToDestination) end
                    iAngleAdjust = math.max(iAngleAdjust, iAngleDifToDestination * 0.7)
                end
            end
        end

        if AiBotUtilities.GetAngleDifference(iCurFacingAngle + iAngleAdjust, iAngleToDestination) > AiBotUtilities.GetAngleDifference(iCurFacingAngle - iAngleAdjust, iAngleToDestination) then
            iAngleAdjust = iAngleAdjust * -1
        end
        local iAngleToMove = iCurFacingAngle + iAngleAdjust
        if bRunAwayFromNearestEnemy then
            local iAngleToNearestEnemy = AiBotUtilities.GetAngleFromAToB(oTarget:GetPosition(), oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())
            --If we move the planned angle, will that mean we get closer to this enemy significantly?
            if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether our current angle will take us too close to nearest enemy, oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]='..oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck])..'; iAngleToNearestEnemy='..iAngleToNearestEnemy..'; iAngleToMove currently='..iAngleToMove..'; Angle dif='..AiBotUtilities.GetAngleDifference(iAngleToNearestEnemy, iAngleToMove)) end
            if AiBotUtilities.GetAngleDifference(iAngleToNearestEnemy, iAngleToMove) <= 100 then
                --Want to move in opposite direction to nearest enemy; if we were already moving this way then want to change slightly so we hopefully dodge the shot while also still running
                local iAngleFromNearestEnemy = iAngleToNearestEnemy - 180
                if iAngleFromNearestEnemy < 0 then iAngleFromNearestEnemy = iAngleFromNearestEnemy + 360 end
                if bDebugMessages == true then LOG(sFunctionRef..': Dif between angle from nearest enemy and angle to destination='..AiBotUtilities.GetAngleDifference(iAngleFromNearestEnemy, iAngleToDestination)) end
                if AiBotUtilities.GetAngleDifference(iAngleFromNearestEnemy, iAngleToDestination) < 20 then
                    --Move either +15 or -15 from nearest enemy, based on which gives the greatest dif to our current angletodestination
                    if AiBotUtilities.GetAngleDifference(iAngleFromNearestEnemy + 15, iAngleToDestination) > AiBotUtilities.GetAngleDifference(iAngleFromNearestEnemy - 15, iAngleToDestination) then
                        iAngleToMove = iAngleFromNearestEnemy + 15
                    else
                        iAngleToMove = iAngleFromNearestEnemy - 15
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iAngleToMove so we run from nearest enemy='..iAngleToMove) end
                else
                    iAngleToMove = iAngleFromNearestEnemy
                    if bDebugMessages == true then LOG(sFunctionRef..': Will move in opposite direction to nearest enemy, iAngleFromNearestEnemy='..iAngleFromNearestEnemy) end
                end
            end
        end

        local tTempDestination

        for iAngleAdjust = 0, 90 do
            for iAngleMod = -1, 1, 2 do
                if iAngleAdjust == 0 then
                    tTempDestination = AiBotUtilities.MoveInDirection(oTarget:GetPosition(), iAngleToMove, iDistanceToRun, false, false, false)
                    if bDebugMessages == true then LOG(sFunctionRef..': bae angle with no adjust, is tTempDestination in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tTempDestination))..'; tTempDestination='..repru(tTempDestination)) end
                    if not(AiBotConditions.IsLocationInPlayableArea(tTempDestination)) then
                        tTempDestination = nil
                    end
                    break
                else
                    tTempDestination = AiBotUtilities.MoveInDirection(oTarget:GetPosition(), iAngleToMove + iAngleMod * iAngleAdjust, iDistanceToRun, false, false, false)
                    if bDebugMessages == true then LOG(sFunctionRef..': iAngleToMove='..iAngleToMove..'; iAngleAdjust='..iAngleAdjust..'; iAngleMod='..iAngleMod..'; is tTempDestination in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tTempDestination))..'; tTempDestination='..repru(tTempDestination)) end
                    if not(AiBotConditions.IsLocationInPlayableArea(tTempDestination)) then
                        tTempDestination = nil
                    end
                    if tTempDestination then break end
                end
            end
            if tTempDestination then break end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': oTarget (ie unit that is dodging)='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..'; clearing current orders which have a possible destination of '..repru(tCurDestination)..'; and giving an order to move to '..repru(tTempDestination)..'; Dist from our position to temp position='..AiBotUtilities.GetDistanceBetweenPositions(oTarget:GetPosition(), tTempDestination)..'; iAngleAdjust='..iAngleAdjust..'; Unit size='..iUnitSize..'; iTimeToDodge='..iTimeToDodge) end
        if tTempDestination then
            --AiBotOrders.IssueTrackedClearCommands(oTarget)
            TrackTemporaryUnitMicro(oTarget, iTimeToDodge)
            if bAdjustDodgeMicroCount then
                AiBotUtilities.DelayChangeVariable(oTarget:GetAIBrain(), refiCurUnitsDodging, -1, iTimeToDodge, nil, nil, nil, nil, true)
            end
            AiBotOrders.IssueTrackedMove(oTarget, tTempDestination, 0.25, false, 'MiDod1', true)
            --Also send an order to go to the destination that we had before
            if bAttackMove then
                AiBotOrders.IssueTrackedAttackMove(oTarget, tCurDestination, 0.25, true, 'MiDod2', true)
            else
                --AiBotOrders.IssueTrackedMove(oTarget, tCurDestination, 0.25, true, 'MiDod3', true)
                --Disabled for v89 given new 'get goal' position and increase in the micro dodge distance
            end
        elseif bDebugMessages == true then LOG(sFunctionRef..': Wont give dodge order as couldnt find anywhere valid to move to')
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AltDodgeShot(oTarget, oWeapon, oAttacker, iTimeToDodge)
    --Intended for units like LABs, making use of new logic to change existing move order
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AltDodgeShot'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..'; oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oTarget))) end
    local bAdjustDodgeMicroCount = false
    local bContinue = true
    if not(ScenarioInfo.Options.AiBotDodgeMicro == 1) then
        local aiBrain = oTarget:GetAIBrain()
        local iCurUnitsDodging = aiBrain[refiCurUnitsDodging]
        local iMaxUnitsToDodge = aiBrain[refiMaxUnitsToDodgeMicroAtOnce]
        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether have too many units dodging at once, aiBrain[refiCurUnitsDodging]='..tostring(iCurUnitsDodging)..' ('..type(iCurUnitsDodging)..'); aiBrain[refiMaxUnitsToDodgeMicroAtOnce]='..tostring(iMaxUnitsToDodge)..' ('..type(iMaxUnitsToDodge)..')') end
        if type(iCurUnitsDodging) == 'number' and type(iMaxUnitsToDodge) == 'number' and iCurUnitsDodging >= iMaxUnitsToDodge then
            bContinue = false
        else
            aiBrain[refiCurUnitsDodging] = (type(iCurUnitsDodging) == 'number' and iCurUnitsDodging or 0) + 1
            bAdjustDodgeMicroCount = true
        end
    end
    if bContinue then
        AiBotOrders.UpdateRecordedOrders(oTarget)
        local iCurFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oTarget)
        local iAngleToMove = iCurFacingAngle + 120
        if iAngleToMove > 360 then iAngleToMove = iAngleToMove - 360 end
        local oBP = oTarget:GetBlueprint()
        local iSpeed = oBP.Physics.MaxSpeed
        local iDistanceToRun = iTimeToDodge * iSpeed
        local tTempDestination = AiBotUtilities.MoveInDirection(oTarget:GetPosition(), iAngleToMove, iDistanceToRun, true, false, true)
        TrackTemporaryUnitMicro(oTarget, iTimeToDodge)
        if bAdjustDodgeMicroCount then
            AiBotUtilities.DelayChangeVariable(oTarget:GetAIBrain(), refiCurUnitsDodging, -1, iTimeToDodge, nil, nil, nil, nil, true)
        end
        AiBotOrders.IssueTrackedMove(oTarget, tTempDestination, 0.1, false, 'MiAltDod1', true)
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function EnableUnitMicroUntilManuallyTurnOff(oUnit, bLowerPriorityMicro)
    oUnit[AiBotUnitInfo.refbSpecialMicroActive] = true
    if bLowerPriorityMicro then oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive] = true
    else
        if oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive] then oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive] = nil end
    end
    oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] = GetGameTimeSeconds()
    oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] = -1
end

function TrackTemporaryUnitMicro(oUnit, iSecondsActiveFor, sOptionalAdditionalTrackingVar, bLowerPriorityMicro)
    --Where we are doing all actions upfront can call this to enable micro and then turn the flag off after set period of time
    --Note that air logic currently doesnt make use of this
    --bLowerPriorityMicro - if this is true then this will be ignored by 'higher priority micro'
    --if iSecondsActiveFor is 0 then treat as infinite and dont reset the flag
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TrackTemporaryUnitMicro'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    oUnit[AiBotUnitInfo.refbSpecialMicroActive] = true
    if bLowerPriorityMicro then oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive] = true
    else
        if oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive] then oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive] = nil end
    end
    oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] = GetGameTimeSeconds()
    oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds() + iSecondsActiveFor
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oUnit[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; oUnit[AiBotUnitInfo.refiGameTimeMicroStarted]='..oUnit[AiBotUnitInfo.refiGameTimeMicroStarted]..'; oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive]='..oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive]..'; iSecondsActiveFor='..iSecondsActiveFor) end
    if iSecondsActiveFor == 0 then
        --Do nothing
    else
        ForkThread(ForkedResetMicroFlag, oUnit, iSecondsActiveFor - 0.01, sOptionalAdditionalTrackingVar)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ForkedResetMicroFlag(oUnit, iTimeToWait, sOptionalAdditionalTrackingVar, bCalledFromResetChecker)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ForkedResetMicroFlag'

    oUnit[AiBotUnitInfo.refbSpecialMicroActive] = true --As if we are calling an action for the micro that clears commands, then that will reset the micro flag
    if iTimeToWait > 0 then
        WaitSeconds(iTimeToWait)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if AiBotUnitInfo.IsUnitValid(oUnit) then

        if bDebugMessages == true then LOG(sFunctionRef..': Checking if micro flag can be reset to false for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time='..GetGameTimeSeconds()..'; Time to reset flag='..(oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 'nil')..'; oUnit[AiBotUnitInfo.refbSpecialMicroActive] before reset='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
        if GetGameTimeSeconds() + 0.02 > oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
            if bDebugMessages == true then LOG(sFunctionRef..': Have reset flag') end
            oUnit[refbMicroResetChecker] = nil
            oUnit[AiBotUnitInfo.refbSpecialMicroActive] = false
            if bDebugMessages == true then LOG(sFunctionRef..': Turning off special micro1') end
            oUnit[AiBotUnitInfo.refbLowerPriorityMicroActive] = nil
            if sOptionalAdditionalTrackingVar then
                oUnit[sOptionalAdditionalTrackingVar] = false
            end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Will try waiting one more cycle to see if we need to reset the flag unless already got an active reset checker, MicroResetChecker='..tostring(oUnit[refbMicroResetChecker] or false)) end
            if not(oUnit[refbMicroResetChecker]) or bCalledFromResetChecker then
                oUnit[refbMicroResetChecker] = true
                ForkThread(ForkedResetMicroFlag,oUnit, math.max(oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] - GetGameTimeSeconds() - 0.01, 0.2), sOptionalAdditionalTrackingVar, true)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ForkedMoveInCircleOld(oUnit, iTimeToRun, bDontTreatAsMicroAction, bDontClearCommandsFirst, iCircleSizeOverride, iTickWaitOverride)
    --More intensive version of MoveAwayFromTargetTemporarily, intended e.g. for ACUs
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ForkedMoveInCircle'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local refbActiveCircleMicro = 'AiBotMicroActiveCircleMicro'

    if bDebugMessages == true then LOG(sFunctionRef..': GameTime='..GetGameTimeSeconds()..'; Unit has active circle micro='..tostring(oUnit[refbActiveCircleMicro] or false)) end
    if not(oUnit[refbActiveCircleMicro]) then

        --KEY CONFIG SETTINGS: (these will work sometimes but not always against an aeon strat)
        local iInitialAngleAdj = 15
        local iInitialDistanceAdj = -1
        local iDistanceAwayToMove = (iCircleSizeOverride or 2)
        local iAngleMaxSingleAdj = 45
        local iTicksBetweenOrders = (iTickWaitOverride or 4)

        if iDistanceAwayToMove > oUnit:GetBlueprint().Physics.MaxSpeed * 1.5 then
            iAngleMaxSingleAdj = math.max(25, iAngleMaxSingleAdj * 2.5 / iDistanceAwayToMove)
        end



        local iStartTime = GetGameTimeSeconds()
        oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] = iStartTime
        local iLoopCount = 0
        local iMaxLoop = iTimeToRun * 10 + 1
        --Distance from point A to point B will be much less than distanceaway to move, since that is the distance from the centre (radius) rather than the distance between 1 points on the circle edge; for simplicity will assume that distance is 0.25 of the distance from the centre
        if bDontTreatAsMicroAction then iMaxLoop = math.ceil(iTimeToRun / (iDistanceAwayToMove / oUnit:GetBlueprint().Physics.MaxSpeed)) * 4 end
        local tUnitStartPosition = oUnit:GetPosition()

        local iCurFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oUnit)
        local iAngleAdjFactor = 1

        local tTempLocationToMove

        local bRecentMicro = false
        local iRecentMicroThreshold = 1
        local iGameTime = GetGameTimeSeconds()
        if oUnit[AiBotUnitInfo.refbSpecialMicroActive] and iGameTime - oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] < iRecentMicroThreshold then bRecentMicro = true end
        if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop for move commands for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iTimeToRun='..iTimeToRun..'; iStartTime='..iStartTime..'; iCurFacingDirection='..iCurFacingDirection..'; tUnitStartPosition='..repru(tUnitStartPosition)..'; bRecentMicro='..tostring((bRecentMicro or false))..'; bDontClearCommandsFirst='..tostring(bDontClearCommandsFirst or false)..'; oUnit[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive])..'; oUnit[AiBotUnitInfo.refiGameTimeMicroStarted]='..(oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] or 'nil')..'; GameTime='..iGameTime..'; Dif='..iGameTime-(oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] or 0)..'; bDontTreatAsMicroAction='..tostring((bDontTreatAsMicroAction or false))) end
        if bRecentMicro == false and not(bDontClearCommandsFirst) then
            AiBotOrders.IssueTrackedClearCommands(oUnit)
            if bDebugMessages == true then LOG(sFunctionRef..': Issued clear commands order to the unit') end
        end
        if not(bDontTreatAsMicroAction) then
            TrackTemporaryUnitMicro(oUnit, iTimeToRun, refbActiveCircleMicro)
            if bDebugMessages == true then LOG(sFunctionRef..': Will temporarily track the unit micro. iTimeToRun='..(iTimeToRun or 'nil')) end
        else
            TrackTemporaryUnitMicro(oUnit, iTimeToRun)
        end

        local iTempAngleDirectionToMove = iCurFacingDirection + iInitialAngleAdj * iAngleAdjFactor
        local iTempDistanceAwayToMove
        local bTimeToStop = false
        if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; refbSpecialMicroActive='..tostring((oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false))..'; iMaxLoop='..iMaxLoop) end
        while bTimeToStop == false do
            iLoopCount = iLoopCount + 1
            if iLoopCount > iMaxLoop then break
            elseif AiBotUnitInfo.IsUnitValid(oUnit) == false then break end --No longer give error message as may be calling this for intel scouts now

            iTempAngleDirectionToMove = iTempAngleDirectionToMove + iAngleMaxSingleAdj * iAngleAdjFactor
            if iTempAngleDirectionToMove > 360 then iTempAngleDirectionToMove = iTempAngleDirectionToMove - 360 end
            --end
            iTempDistanceAwayToMove = iDistanceAwayToMove
            if iLoopCount == 1 then iTempDistanceAwayToMove = iDistanceAwayToMove + iInitialDistanceAdj end
            tTempLocationToMove = AiBotUtilities.MoveInDirection(tUnitStartPosition, iTempAngleDirectionToMove, iTempDistanceAwayToMove, true, false, true)
            AiBotOrders.IssueTrackedMove(oUnit, tTempLocationToMove, 0.25, true, 'MiCirc1', true)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(iTicksBetweenOrders)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if not(bDontTreatAsMicroAction) and not((oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] == iStartTime and GetGameTimeSeconds() - iStartTime < iTimeToRun)) then bTimeToStop = true end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ForkedMoveInCircle(oUnit, iTimeToRun, bDontTreatAsMicroAction, bDontClearCommandsFirst, iCircleSizeOverride, iTickWaitOverride)
    --More intensive version of MoveAwayFromTargetTemporarily, intended e.g. for ACUs
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ForkedMoveInCircle'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local refbActiveCircleMicro = 'AiBotMicroActiveCircleMicro'

    if bDebugMessages == true then LOG(sFunctionRef..': GameTime='..GetGameTimeSeconds()..'; Unit has active circle micro='..tostring(oUnit[refbActiveCircleMicro] or false)) end
    if not(oUnit[refbActiveCircleMicro]) then

        --KEY CONFIG SETTINGS: (these will work sometimes but not always against an aeon strat)
        local iDistanceAwayToMove = (iCircleSizeOverride or 2)
        local iAngleMaxSingleAdj = 20 --pre v101 was 120; see v101 devlog for testing that did; in 2 scenarios 20 degrees performed the best, although I suspect given the variance that in some scenarios it could be worse
        local iTicksBetweenOrders = (iTickWaitOverride or 1) --prev 4 (pre the change to readjust move orders instead of clearing I think)

        if iDistanceAwayToMove > oUnit:GetBlueprint().Physics.MaxSpeed * 1.5 then
            iAngleMaxSingleAdj = math.max(25, iAngleMaxSingleAdj * 2.5 / iDistanceAwayToMove)
        end



        local iStartTime = GetGameTimeSeconds()
        oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] = iStartTime
        local iLoopCount = 0
        local iMaxLoop = iTimeToRun * 10 + 1
        --Distance from point A to point B will be much less than distanceaway to move, since that is the distance from the centre (radius) rather than the distance between 1 points on the circle edge; for simplicity will assume that distance is 0.25 of the distance from the centre
        if bDontTreatAsMicroAction then iMaxLoop = math.ceil(iTimeToRun / (iDistanceAwayToMove / oUnit:GetBlueprint().Physics.MaxSpeed)) * 4 end
        local tUnitStartPosition = oUnit:GetPosition()

        local iCurFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oUnit)


        local iAngleAdjFactor = 1

        local tTempLocationToMove

        local bRecentMicro = false
        local iRecentMicroThreshold = 1
        local iGameTime = GetGameTimeSeconds()
        if oUnit[AiBotUnitInfo.refbSpecialMicroActive] and iGameTime - oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] < iRecentMicroThreshold then bRecentMicro = true end
        if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop for move commands for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iTimeToRun='..iTimeToRun..'; iStartTime='..iStartTime..'; iCurFacingDirection='..iCurFacingDirection..'; tUnitStartPosition='..repru(tUnitStartPosition)..'; bRecentMicro='..tostring((bRecentMicro or false))..'; bDontClearCommandsFirst='..tostring(bDontClearCommandsFirst or false)..'; oUnit[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive])..'; oUnit[AiBotUnitInfo.refiGameTimeMicroStarted]='..(oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] or 'nil')..'; GameTime='..iGameTime..'; Dif='..iGameTime-(oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] or 0)..'; bDontTreatAsMicroAction='..tostring((bDontTreatAsMicroAction or false))..'; iAngleMaxSingleAdj='..iAngleMaxSingleAdj..'; iTicksBetweenOrders='..iTicksBetweenOrders) end
        if bRecentMicro == false and not(bDontClearCommandsFirst) then
            AiBotOrders.UpdateRecordedOrders(oUnit)
            local tLastOrder = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]]
            if not(tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueMove) then
                AiBotOrders.IssueTrackedClearCommands(oUnit)
                if bDebugMessages == true then LOG(sFunctionRef..': Issued clear commands order to the unit') end
            elseif bDebugMessages == true then LOG(sFunctionRef..': Unit last order was a move order so wont clear orders')
            end
        end
        if not(bDontTreatAsMicroAction) then
            TrackTemporaryUnitMicro(oUnit, iTimeToRun, refbActiveCircleMicro)
            if bDebugMessages == true then LOG(sFunctionRef..': Will temporarily track the unit micro. iTimeToRun='..(iTimeToRun or 'nil')) end
        else
            TrackTemporaryUnitMicro(oUnit, iTimeToRun)
        end

        local bTimeToStop = false
        if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; refbSpecialMicroActive='..tostring((oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false))..'; iMaxLoop='..iMaxLoop) end
        while bTimeToStop == false do
            iLoopCount = iLoopCount + 1
            if iLoopCount > iMaxLoop then break
            elseif AiBotUnitInfo.IsUnitValid(oUnit) == false then break end --No longer give error message as may be calling this for intel scouts now


            tTempLocationToMove = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), AiBotUnitInfo.GetUnitFacingAngle(oUnit) + iAngleMaxSingleAdj, iDistanceAwayToMove, true, false, true)
            AiBotOrders.IssueTrackedMove(oUnit, tTempLocationToMove, 0.25, false, 'MiCirc1', true)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(iTicksBetweenOrders)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if not(bDontTreatAsMicroAction) and not((oUnit[AiBotUnitInfo.refiGameTimeMicroStarted] == iStartTime and GetGameTimeSeconds() - iStartTime < iTimeToRun)) then bTimeToStop = true end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MoveInCircleTemporarily(oUnit, iTimeToRun, bDontTreatAsMicroAction, bDontClearCommandsFirst, iCircleSizeOverride, iTickWaitOverride)
    ForkThread(ForkedMoveInCircle, oUnit, iTimeToRun, bDontTreatAsMicroAction, bDontClearCommandsFirst, iCircleSizeOverride, iTickWaitOverride)
end

function GetOverchargeTarget(tLZData, aiBrain, oUnitWithOvercharge, bOnlyConsiderEnemiesInRange)
    --should have already confirmed overcharge action is available using CanUnitUseOvercharge
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetOverchargeTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnitWithOvercharge[refbOnlyOverchargeHighValueTargets]='..tostring(oUnitWithOvercharge[AiBotACU.refbOnlyOverchargeHighValueTargets]  or false)..'; Brain='..oUnitWithOvercharge:GetAIBrain().Nickname) end
    local oOverchargeTarget
    if not(oUnitWithOvercharge[AiBotUnitInfo.refbEasyBrain]) then
        --Do we have positive energy income? If not, then only overcharge if ACU is low on health as an emergency
        local reftiAngleFromACUToUnit = 'AiBotAngleFromACUToUnit'
        local reftiDistFromACUToUnit = 'AiBotDistFromACUToUnit'
        local toStructuresAndACU

        --Subfunction
        function IsBuildingOrACUBlockingShot(oFiringUnit, oTargetUnit)
            --Assumes have already been through tBlockingUnits and set their angle to the firing unit, so we just need to compare to firing unit
            if bDebugMessages == true then LOG(sFunctionRef..': Will see if any buildings or ACU are blocking the shot; if dont get log saying result was false then means was true') end
            if AiBotUtilities.IsTableEmpty(toStructuresAndACU) == false then
                local iAngleToTargetUnit = AiBotUtilities.GetAngleFromAToB(oFiringUnit:GetPosition(), oTargetUnit:GetPosition())
                local iDistToTargetUnit = AiBotUtilities.GetDistanceBetweenPositions(oFiringUnit:GetPosition(), oTargetUnit:GetPosition())
                local iCurAngleDif
                if bDebugMessages == true then LOG(sFunctionRef..': iAngleToTargetUnit='..iAngleToTargetUnit..'; iDistToTargetUnit='..iDistToTargetUnit) end
                for iUnit, oUnit in toStructuresAndACU do
                    if not(oUnit == oTargetUnit) and iDistToTargetUnit > oUnit[reftiDistFromACUToUnit][aiBrain:GetArmyIndex()] then
                        iCurAngleDif = iAngleToTargetUnit - oUnit[reftiAngleFromACUToUnit][aiBrain:GetArmyIndex()]
                        if iCurAngleDif < 0 then iCurAngleDif = iCurAngleDif + 360 end
                        if bDebugMessages == true then LOG(sFunctionRef..': Checking if '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' will block a shot from the ACU to the target '..oTargetUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTargetUnit)..'; iCurAngleDif='..iCurAngleDif..'; 180 / iDistToTargetUnit='..180 / iDistToTargetUnit..'; oUnit[reftiAngleFromACUToUnit][aiBrain:GetArmyIndex()]='..oUnit[reftiAngleFromACUToUnit][aiBrain:GetArmyIndex()]..'; oUnit[reftiDistFromACUToUnit]='..oUnit[reftiDistFromACUToUnit][aiBrain:GetArmyIndex()]..'; angle from ACU to unit='..oUnit[reftiAngleFromACUToUnit][aiBrain:GetArmyIndex()]) end
                        if iCurAngleDif <= math.max(8, 180 / iDistToTargetUnit) then
                            return true
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': End of code, will return false') end
            return false
        end

        --Subfunction
        function WillShotHit(oFiringUnit, oTargetUnit)
            --Check for units in a transport
            if oTargetUnit:IsUnitState('Attached') or AiBotLogic.IsShotBlocked(oFiringUnit, oTargetUnit) or IsBuildingOrACUBlockingShot(oFiringUnit, oTargetUnit) then
                if bDebugMessages == true then LOG(sFunctionRef..': oTargetUnit='..oTargetUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTargetUnit)..'; shot is blocked so wont hit. IsShotBlocked='..tostring(AiBotLogic.IsShotBlocked(oFiringUnit, oTargetUnit))) end
                return false
            else return true
            end
        end

        local tUnitPosition = oUnitWithOvercharge:GetPosition()
        local iACURange = oUnitWithOvercharge[AiBotUnitInfo.refiDFRange]
        if (iACURange or 0) > 0 then
            local iOverchargeArea = 2.5

            --Consider flagging to only target high value targets if we have big gun upgrade
            if oUnitWithOvercharge[AiBotACU.refiUpgradeCount] >= 2 and not(oUnitWithOvercharge[AiBotACU.refbOnlyOverchargeHighValueTargets]) and (oUnitWithOvercharge:HasEnhancement('MicrowaveLaserGenerator') or oUnitWithOvercharge:HasEnhancement('BlastAttack')) then
                oUnitWithOvercharge[AiBotACU.refbOnlyOverchargeHighValueTargets] = true
            end
            if bDebugMessages == true then LOG(sFunctionRef..' FInished considering if want to set to only OC high value targets due to big gun, oUnitWithOvercharge[AiBotACU.refbOnlyOverchargeHighValueTargets]='..tostring(oUnitWithOvercharge[AiBotACU.refbOnlyOverchargeHighValueTargets] or false)..'; Upgrade count='..(oUnitWithOvercharge[AiBotACU.refiUpgradeCount] or 'nil')..'; Unit has laser or splash='..tostring((oUnitWithOvercharge:HasEnhancement('MicrowaveLaserGenerator') or oUnitWithOvercharge:HasEnhancement('BlastAttack')))) end

            --First locate where any blocking units are - will assume non-wall structures larger than a T1 pgen will block the shot, and ACUs will block
            local iMaxSearchDistance
            if bOnlyConsiderEnemiesInRange then iMaxSearchDistance = iACURange - 1
            else iMaxSearchDistance = 50
            end
            toStructuresAndACU = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryStructure - categories.SIZE4 + categories.COMMAND, tUnitPosition, iMaxSearchDistance, 'Enemy')

            if bDebugMessages == true then LOG(sFunctionRef..': First locating blocking units; is table empty='..tostring(AiBotUtilities.IsTableEmpty(toStructuresAndACU))..'; iACURange='..iACURange..'; iOverchargeArea='..iOverchargeArea) end
            if AiBotUtilities.IsTableEmpty(toStructuresAndACU) == false then
                for iUnit, oUnit in toStructuresAndACU do
                    if not(oUnit[reftiAngleFromACUToUnit]) then
                        oUnit[reftiAngleFromACUToUnit] = {}
                        oUnit[reftiDistFromACUToUnit] = {}
                    end
                    oUnit[reftiAngleFromACUToUnit][aiBrain:GetArmyIndex()] = AiBotUtilities.GetAngleFromAToB(tUnitPosition, oUnit:GetPosition())
                    oUnit[reftiDistFromACUToUnit][aiBrain:GetArmyIndex()] = AiBotUtilities.GetDistanceBetweenPositions(tUnitPosition, oUnit:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': Angle from oUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to our ACU='..repru(oUnit[reftiAngleFromACUToUnit])..'; distance='..repru(oUnit[reftiDistFromACUToUnit])) end

                    --If enemy ACU is nearby and low health then target as top priority
                    if oUnit[reftiDistFromACUToUnit][aiBrain:GetArmyIndex()] < (iACURange - 2) and EntityCategoryContains(categories.COMMAND, oUnit.UnitId) and oUnit:GetHealth() < 1400 then
                        oOverchargeTarget = oUnit
                    end
                end
            end


            if not(oOverchargeTarget) then
                --Cycle through every land combat non-ACU, and/or surface naval, unit within firing range to see if can find one that reduces the damage the most, or failing that does the most mass damage; will include all navy on the assumption isshotblocked will trigger if shot will go underwater (as otherwise we might ignore sera T2 destroyers)
                local tEnemyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileLand - categories.COMMAND + AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryAllNavy, tUnitPosition, iACURange, 'Enemy')

                local iMostMassDamage = 0
                local oMostMassDamage, iKillsExpected
                local iMaxOverchargeDamage = (aiBrain:GetEconomyStored('ENERGY') * 0.9) * 0.25
                local iCurDamageDealt, iCurKillsExpected
                if bDebugMessages == true then LOG(sFunctionRef..': Will consider enemy mobile units and PD within 2 of the ACU max range; is the table empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyUnits))) end
                if AiBotUtilities.IsTableEmpty(tEnemyUnits) == false then
                    for iUnit, oUnit in tEnemyUnits do
                        --Reduce range to consider if unit is moving and isn't moving towards ACU
                        if not(oUnit:IsUnitState('Moving')) or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnitWithOvercharge:GetPosition()) < iACURange - 1 or AiBotUtilities.GetAngleDifference(AiBotUnitInfo.GetUnitFacingAngle(oUnit), AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oUnitWithOvercharge:GetPosition())) <= 25 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if shot will hit for ACU '..(oUnitWithOvercharge.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitWithOvercharge) or 'nil')..' to hit oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..' unit position='..repru(oUnit:GetPosition())..'; Is unit underwater='..tostring(AiBotUnitInfo.IsUnitUnderwater(oUnit))..'; Will shot hit='..tostring(WillShotHit(oUnitWithOvercharge, oUnit))) end
                            if WillShotHit(oUnitWithOvercharge, oUnit) then
                                iCurDamageDealt, iCurKillsExpected = AiBotLogic.GetDamageFromOvercharge(aiBrain, oUnit, iOverchargeArea, iMaxOverchargeDamage)
                                if bDebugMessages == true then LOG(sFunctionRef..': Shot will hit enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; damage result='..iCurDamageDealt) end
                                if iCurDamageDealt > iMostMassDamage then
                                    iMostMassDamage = iCurDamageDealt
                                    oMostMassDamage = oUnit
                                    iKillsExpected = iCurKillsExpected

                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished searching through enemy mobile untis and PD in range, iMostMassDamage='..iMostMassDamage..'; iKillsExpected='..(iKillsExpected or 0)..'; Energy stored %='..aiBrain:GetEconomyStoredRatio('ENERGY')..'; E stored='..aiBrain:GetEconomyStored('ENERGY')) end

                --if iMostMobileCombatMassDamage >= 80 then
                --    oOverchargeTarget = oMostCombatMassDamage
                if (not(oUnitWithOvercharge[AiBotACU.refbOnlyOverchargeHighValueTargets]) and iMostMassDamage >= 200 or iKillsExpected >= 3 or (iKillsExpected >= 1 and iMostMassDamage >= 100) or (iMostMassDamage >= 60 and aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.9 and (aiBrain:GetEconomyStored('ENERGY') >= 10000 or (aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] >= 1 and aiBrain:GetEconomyStored('ENERGY') >= 8000))))
                        or (oUnitWithOvercharge[AiBotACU.refbOnlyOverchargeHighValueTargets] and (iMostMassDamage >= 500 or iKillsExpected >= 6 or (oOverchargeTarget and EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oOverchargeTarget.UnitId)))) then --e.g. striker is 56 mass; lobo is 36
                    oOverchargeTarget = oMostMassDamage
                    if bDebugMessages == true then LOG(sFunctionRef..': Have a mobile or PD unit in range that will do enough damage to, oOverchargeTarget='..oOverchargeTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOverchargeTarget)) end
                else
                    --Check we aren't running before considering whether to target walls or T2 PDs
                    if GetGameTimeSeconds() - (oUnitWithOvercharge[AiBotACU.refiTimeLastWantedToRun] or -30) >= 30 then
                        --No decent combat targets; Check for lots of walls that might be blocking our path (dont reduce ACU range given these are structures)
                        --Only consider overcharging walls if no enemies within our combat range + 3
                        if not(oUnitWithOvercharge[AiBotACU.refbOnlyOverchargeHighValueTargets]) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPlayerWallSegments]) == false and table.getn(tLZData[AiBotMap.subrefLZPlayerWallSegments]) >= 9 then
                            local tAllEnemies = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryNavalSurface, tUnitPosition, math.min(iMaxSearchDistance, iACURange + 3), 'Enemy')
                            if AiBotUtilities.IsTableEmpty(tAllEnemies) then
                                tEnemyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryWall, tUnitPosition, iACURange, 'Enemy')
                                if bDebugMessages == true then LOG(sFunctionRef..': iMostMassDamage='..iMostMassDamage..'; so will check for walls and other structure targets; is table of wall units empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyUnits))) end
                                if AiBotUtilities.IsTableEmpty(tEnemyUnits) == false and table.getn(tEnemyUnits) >= 5 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have at least 5 wall units in range, so potential blockage; size='..table.getn(tEnemyUnits)) end
                                    local bSuspectedPathBlock = false
                                    --If more than 10 then assume blocking our path

                                    if table.getn(tEnemyUnits) >= 10 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': At least 10 wall units so assuming a blockage') end
                                        bSuspectedPathBlock = true
                                    else
                                        local tFirstWall = tEnemyUnits[1]:GetPosition()
                                        for iWall, oWall in tEnemyUnits do
                                            if iWall > 1 then
                                                if AiBotUtilities.GetDistanceBetweenPositions(oWall:GetPosition(), tFirstWall) >= 4 then
                                                    bSuspectedPathBlock = true
                                                    break
                                                end
                                            end
                                        end
                                    end
                                    if bSuspectedPathBlock then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Think enemy has walls in a line so will overcharge them unless they are all closer to our base than us') end
                                        iMostMassDamage = 0
                                        oMostMassDamage = nil
                                        bSuspectedPathBlock = false

                                        local iOurDistToBase = AiBotUtilities.GetDistanceBetweenPositions(tUnitPosition, AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()])
                                        local iWallDistToBase
                                        for iWall, oUnit in tEnemyUnits do
                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()]) <= iOurDistToBase + 4 then
                                                bSuspectedPathBlock = true
                                                break
                                            end
                                        end
                                        if bSuspectedPathBlock then
                                            for iWall, oUnit in tEnemyUnits do
                                                if WillShotHit(oUnitWithOvercharge, oUnit) then
                                                    iCurDamageDealt = AiBotLogic.GetDamageFromOvercharge(aiBrain, oUnit, iOverchargeArea, iMaxOverchargeDamage, true)
                                                    if iCurDamageDealt > iMostMassDamage then
                                                        iMostMassDamage = iCurDamageDealt
                                                        oMostMassDamage = oUnit
                                                    end
                                                end
                                            end
                                            if oMostMassDamage then oOverchargeTarget = oMostMassDamage end
                                        elseif bDebugMessages == true then LOG(sFunctionRef..': Walls are all closer to our base than we are so probably not blocking us')
                                        end
                                    elseif bDebugMessages == true then LOG(sFunctionRef..': Dont think the walls are in a line so wont try and OC')
                                    end
                                end
                            end
                        end
                        if not(oOverchargeTarget) and not(oUnitWithOvercharge[AiBotACU.refbOnlyOverchargeHighValueTargets]) then
                            --Check further away incase enemy has T2 PD that can see us
                            if bDebugMessages == true then LOG(sFunctionRef..': Checking if any T2 PD further away') end
                            tEnemyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryT2PlusPD, tUnitPosition, iMaxSearchDistance, 'Enemy')
                            if AiBotUtilities.IsTableEmpty(tEnemyUnits) == false then
                                if bDebugMessages == true then LOG(sFunctionRef..': Have enemy T2 defence that can hit us but is out of our range - considering if OC it will bring us in range of T1 PD, and/or if shot is blocked, and/or if the T2PD cant even see us') end
                                local tNearbyT1PD
                                local iNearestT1PD = 10000
                                local iCurDistance
                                if 50 - iACURange > 0 then tNearbyT1PD = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryPD * categories.TECH1, tUnitPosition, 50 - iACURange, 'Enemy') end
                                if AiBotUtilities.IsTableEmpty(tNearbyT1PD) == false then
                                    for iT1PD, oT1PD in tNearbyT1PD do
                                        iCurDistance = AiBotUtilities.GetDistanceBetweenPositions(oT1PD:GetPosition(), tUnitPosition)
                                        if iCurDistance < iNearestT1PD then iNearestT1PD = iCurDistance end
                                    end
                                end

                                for iUnit, oEnemyT2PD in tEnemyUnits do
                                    --Can we get in range of the T2 PD without getting in range of the T1 PD? (approximates just based on distances rather than considering the likely path to take)
                                    if AiBotUtilities.GetDistanceBetweenPositions(oEnemyT2PD:GetPosition(), tUnitPosition) - iACURange + 2 < iNearestT1PD then
                                        if AiBotLogic.IsShotBlocked(oUnitWithOvercharge, oEnemyT2PD) == false then
                                            --Can the T2 PD see us?
                                            if AiBotUnitInfo.CanSeeUnit(oEnemyT2PD:GetAIBrain(), oUnitWithOvercharge) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Setting target to T2 PD') end
                                                oOverchargeTarget = oEnemyT2PD
                                                break
                                            else
                                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy T2 PDs owner can see our ACU') end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        if not(oOverchargeTarget) and not(oUnitWithOvercharge[AiBotACU.refbOnlyOverchargeHighValueTargets]) then
                            --Consider all structures (can do ACU max range since before when structures were considered we were looking at reduced range)
                            tEnemyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryStructure, tUnitPosition, iACURange, 'Enemy')
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering all enemy structures within range of ACU; is table empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyUnits))) end
                            --local iMostMobileCombatMassDamage = 0
                            --local oMostCombatMassDamage
                            if AiBotUtilities.IsTableEmpty(tEnemyUnits) == false then
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering other enemy structures in range; iMostMassDamage before looking='..iMostMassDamage) end
                                for iUnit, oUnit in tEnemyUnits do
                                    if WillShotHit(oUnitWithOvercharge, oUnit) then
                                        iCurDamageDealt, iCurKillsExpected = AiBotLogic.GetDamageFromOvercharge(aiBrain, oUnit, iOverchargeArea, iMaxOverchargeDamage)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Shot will hit enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; damage result='..iCurDamageDealt) end
                                        if iCurDamageDealt > iMostMassDamage then
                                            iMostMassDamage = iCurDamageDealt
                                            oMostMassDamage = oUnit
                                            iKillsExpected = iCurKillsExpected
                                        end
                                    end
                                end
                            end
                            if iMostMassDamage >= 110 then
                                oOverchargeTarget = oMostMassDamage
                            end
                        end
                    end
                end
            end
        end
        if oOverchargeTarget == nil then
            if bDebugMessages == true then LOG(sFunctionRef..': No OC targets found') end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Overcharge target='..oOverchargeTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOverchargeTarget)) end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return oOverchargeTarget
end

function TurnAirUnitAndMoveToTarget(oBomber, tDirectionToMoveTo, iMaxAcceptableAngleDif, iOptionalSecondsToMoveAtEndIfFarFromTarget)
    --Based on hoverbomb logic - may give unexpected results if not using with T3 bombers
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TurnAirUnitAndMoveToTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; Does bomber fire salvo='..tostring(AiBotUnitInfo.DoesBomberFireSalvo(oBomber) or false)..'; GameTime='..GetGameTimeSeconds()) end

    --First delay microing until finished our salvo if dealing with T1-T3 bomber
    if AiBotUnitInfo.DoesBomberFireSalvo(oBomber) and EntityCategoryContains(AiBotUnitInfo.refCategoryBomber - categories.EXPERIMENTAL, oBomber.UnitId) then
        if bDebugMessages == true then LOG(sFunctionRef..': Will wait a second so bomber can finish firing') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1.1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting for bomber '..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; is bomber valid='..tostring(AiBotUnitInfo.IsUnitValid(oBomber))) end
    end
    if AiBotUnitInfo.IsUnitValid(oBomber) then
        local bContinue = true
        if AiBotUtilities.IsTableEmpty(tDirectionToMoveTo) then
            if AiBotMap.bIsCampaignMap and ((ScenarioInfo.OpEnded and GetGameTimeSeconds() <= 120) or (oBomber:GetAIBrain().HostileCampaignAI and tonumber(ScenarioInfo.Options.CmpAIDelay) > GetGameTimeSeconds())) then
                bContinue = false
            else
                --Set direction to move to to the start position
                tDirectionToMoveTo = AiBotMap.PlayerStartPoints[oBomber:GetAIBrain():GetArmyIndex()]
            end
        end
        --Campaign special override - ignore microing if near start of game and a cutscene
        if AiBotMap.bIsCampaignMap and ScenarioInfo.OpEnded and GetGameTimeSeconds() <= 120 and bContinue then bContinue = false end
        --If bomber already has micro active then dont run this
        if bContinue and oBomber[AiBotUnitInfo.refbSpecialMicroActive] and not(oBomber[AiBotUnitInfo.refbLowerPriorityMicroActive]) and (not(oBomber[AiBotUnitInfo.refiGameTimeToResetMicroActive]) or GetGameTimeSeconds() < oBomber[AiBotUnitInfo.refiGameTimeToResetMicroActive]) then
            --Wait 1 second just in cae temporary delay
            WaitSeconds(1)
            if oBomber[AiBotUnitInfo.refbSpecialMicroActive] and not(oBomber[AiBotUnitInfo.refbLowerPriorityMicroActive]) then
                bContinue = false
            end
        end

        local aiBrain
        local bAdjustHoverMicroCount = false
        if bContinue then
            aiBrain = oBomber:GetAIBrain()
            local iCurUnitsHoverMicroing = aiBrain[refiCurUnitsHoverMicroing]
            local iMaxUnitsToHover = aiBrain[refiMaxUnitsToHoverMicroAtOnce]
            if iMaxUnitsToHover then
                if bDebugMessages == true then LOG(sFunctionRef..': Checking if reached hover micro limit, aiBrain[refiMaxUnitsToHoverMicroAtOnce]='..tostring(iMaxUnitsToHover)..' ('..type(iMaxUnitsToHover)..'); aiBrain[refiCurUnitsHoverMicroing]='..tostring(iCurUnitsHoverMicroing)..' ('..type(iCurUnitsHoverMicroing)..'); oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; Time='..GetGameTimeSeconds()) end
                if type(iCurUnitsHoverMicroing) == 'number' and type(iMaxUnitsToHover) == 'number' and iCurUnitsHoverMicroing >= iMaxUnitsToHover then
                    AiBotOrders.IssueTrackedMove(oBomber, tDirectionToMoveTo, 2, false, 'NoMiAirMv', false)
                    bContinue = false
                else
                    aiBrain[refiCurUnitsHoverMicroing] = (type(iCurUnitsHoverMicroing) == 'number' and iCurUnitsHoverMicroing or 0) + 1
                    bAdjustHoverMicroCount = true
                end
            end
        end
        if bContinue then
            local iStartTime = GetGameTimeSeconds()
            --local iAngleToTarget

            --Config:
            local iTicksBetweenOrders = 5
            local iDistanceAwayToMove = 10
            local iAngleAdjust = 50


            --Other variables:
            local iActualAngleToUse
            local iCurAngleDif
            local iAngleAdjustToUse
            local iFacingDirection
            local iAngleToTarget

            local iCurTick = 0
            local bTriedMovingForwardsAndTurning = false
            local iDistToTarget
            local tTempTarget

            local iMaxMicroTime = 5 --will micro for up to 5 seconds
            if EntityCategoryContains(categories.EXPERIMENTAL, oBomber.UnitId) then iMaxMicroTime = 10 end



            --Clear trackers so we dont think we're targeting anything - commented out as this is called via the clearairunitassignmenttracker so causes issues
            --M27AirOverseer.ClearAirUnitAssignmentTrackers(aiBrain, oBomber, true)
            TrackTemporaryUnitMicro(oBomber, 60) --60s is redundancy


            if not(oBomber[AiBotUnitInfo.refbEasyBrain]) or EntityCategoryContains(categories.EXPERIMENTAL, oBomber.UnitId) then
                while GetGameTimeSeconds() - iStartTime < iMaxMicroTime do
                    iCurTick = iCurTick + 1

                    iFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oBomber)
                    iAngleToTarget = AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tDirectionToMoveTo)
                    iCurAngleDif = iFacingDirection - iAngleToTarget
                    iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tDirectionToMoveTo)
                    --e.g. if bomber is facing 350 degrees, and the target is at 10 degrees, then it means there's only a dif of 20 degrees, but we want the bomber to go 350+50, rather than 350-50.  Facing - Angle would result in a positive value
                    --if instead bomber was facing 10 degrees, and the target was 30 degrees, then would get -20 as the result, and so want to also increase
                    --the effect of the below is that when bomber is facing 350 degrees and target 10 degrees, it will treat the difference as being 350 - 10 - 360 = -20, and want the bomber to go 350+50; if insteadbomber 10 and target 30, then dif = -20 and no adjustment made
                    if math.abs(iCurAngleDif) > 180 then
                        if iCurAngleDif > 180 then
                            --iFacingDirection is too high so decrease the angle difference
                            iCurAngleDif = iCurAngleDif - 360
                        else --Curangledif must be < -180, so angletotarget is too high
                            iCurAngleDif = iCurAngleDif + 360
                        end
                    end


                    if iCurAngleDif < 0 then
                        iAngleAdjustToUse = iAngleAdjust
                    else iAngleAdjustToUse = -iAngleAdjust
                    end

                    --Are we close enough to the direction wanted?
                    iCurAngleDif = math.abs(iCurAngleDif)
                    if iCurAngleDif <= (iMaxAcceptableAngleDif or 15) then
                        --Are close enough in angle so can stop the micro
                        break
                    else
                        if iCurTick == 1 then
                            iActualAngleToUse = iFacingDirection + iAngleAdjustToUse
                            tTempTarget = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iActualAngleToUse, iDistanceAwayToMove, true, false, true)
                            AiBotOrders.IssueTrackedMove(oBomber, tTempTarget, 0, false, 'BMicrM1', true)
                            if bDebugMessages == true then LOG(sFunctionRef..': Just issued move order, iFacingDirection='..iFacingDirection..'; iCurAngleDif='..iCurAngleDif..'; iAngleAdjustToUse='..iAngleAdjustToUse..'; iActualAngleToUse='..iActualAngleToUse..'; angle from bomber to target='..AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tDirectionToMoveTo)) end
                        elseif iCurTick >= iTicksBetweenOrders then iCurTick = 0
                        end

                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(1)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        if not(AiBotUnitInfo.IsUnitValid(oBomber)) then
                            break
                        end
                    end
                end
            else
                --Wait a few ticks so definitely cant be as good as normal
                WaitTicks(8)
            end

            if bAdjustHoverMicroCount then aiBrain[refiCurUnitsHoverMicroing] = aiBrain[refiCurUnitsHoverMicroing] - 1 end

            if AiBotUnitInfo.IsUnitValid(oBomber) then
                AiBotOrders.IssueTrackedMove(oBomber, tDirectionToMoveTo, 5, false, 'BMicMTR', true)
                if bDebugMessages == true then LOG(sFunctionRef..': Just cleared bomber '..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..' commands and told it to move to '..repru(tDirectionToMoveTo)..'; Dist to target='..AiBotUtilities.GetDistanceBetweenPositions(tDirectionToMoveTo, oBomber:GetPosition())..'; GameTime='..GetGameTimeSeconds()..'; iOptionalSecondsToMoveAtEndIfFarFromTarget='..(iOptionalSecondsToMoveAtEndIfFarFromTarget or 'nil')) end
                if iOptionalSecondsToMoveAtEndIfFarFromTarget then
                    local iTimeToWait = math.min(iOptionalSecondsToMoveAtEndIfFarFromTarget, AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tDirectionToMoveTo) / (oBomber:GetBlueprint().Physics.MaxSpeed or 10))
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitSeconds(iTimeToWait)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                end

                oBomber[AiBotUnitInfo.refbSpecialMicroActive] = false
                if bDebugMessages == true then LOG(sFunctionRef..': Turning off special micro2') end
                oBomber[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds()
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function TurnAirUnitAndAttackTarget(oBomber, oTarget, bDontAdjustMicroFlag, bContinueAttackingUntilTargetDead, bContinueAttackUntilFiredBomb, iAcceptableAngleDifOverride)
    --Currently just used for ahwassa and T1 bomber
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TurnAirUnitAndAttackTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..'; bDontAdjustMicroFlag='..tostring(bDontAdjustMicroFlag or false)..'; bContinueAttackUntilFiredBomb='..tostring((bContinueAttackUntilFiredBomb or false))..'; GameTime='..GetGameTimeSeconds()) end
    if AiBotUnitInfo.IsUnitValid(oBomber) and AiBotUnitInfo.IsUnitValid(oTarget) then
        local aiBrain = oBomber:GetAIBrain()
        local bAdjustHoverMicroCount = false
        local iStraightLineLeeway
        local bContinue = true
        if not(AiBotUtilities.bFAFActive) or (oBomber[AiBotUnitInfo.refbEasyBrain] and not(EntityCategoryContains(categories.EXPERIMENTAL, oBomber.UnitId))) then
            bContinue = false
            if bDebugMessages == true then LOG(sFunctionRef..': Wont try bomber micro as not sure it will work') end
        elseif aiBrain[refiMaxUnitsToHoverMicroAtOnce] then
            local iCurUnitsHoverMicroing = aiBrain[refiCurUnitsHoverMicroing]
            local iMaxUnitsToHover = aiBrain[refiMaxUnitsToHoverMicroAtOnce]
            if type(iCurUnitsHoverMicroing) == 'number' and type(iMaxUnitsToHover) == 'number' and iCurUnitsHoverMicroing >= iMaxUnitsToHover then
                AiBotOrders.IssueTrackedAttack(oBomber, oTarget, false, 'NoMiAtck', false)
                bContinue = false
            else
                aiBrain[refiCurUnitsHoverMicroing] = (type(iCurUnitsHoverMicroing) == 'number' and iCurUnitsHoverMicroing or 0) + 1
                bAdjustHoverMicroCount = true
            end
        end
        if bContinue then
            local iStartTime = GetGameTimeSeconds()
            --local iAngleToTarget

            --Config:
            local iTicksBetweenOrders = 5
            local iDistanceAwayToMove = 10
            local iAngleAdjust = 50
            local iMaxAcceptableAngleDif = iAcceptableAngleDifOverride or 30
            local iAOE, iDamage = AiBotUnitInfo.GetBomberAOEAndStrikeDamage(oBomber)
            local iBombStraightLineDistance = 8.5 --i.e. will consider firing a bomb in bombers current facing direction by this distance, and seeing if the aoe will hit the target
            --strat bomber failed at the default (which is currently as of v141 a dist of 8.5); however when increased by leeway of 2.5 it dropped; so if change the 8.5 value for strats probably want to increase slightly to somewhere between the two
            local iPotentialAbortDistance = iBombStraightLineDistance + iAOE - 1
            local tGroundTarget
            --local iReloadTime = oBomber[AiBotUnitInfo.refiTimeBetweenBombs] + iDelayForHoverBomb
            --local iTimeUntilCanFire = GetGameTimeSeconds() + math.max(0, iReloadTime - GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0))

            --Other variables:
            local bConsiderIfTooFast = true
            local iTooCloseIfFastDist, iFastSpeedThreshold, iCurSpeed
            local iActualAngleToUse
            local iCurAngleDif
            local iAngleAdjustToUse
            local iFacingDirection
            local iAngleToTarget

            local iCurTick = 0
            local iDistToTarget
            local tTempTarget

            local iMaxMicroTime = 5 --will micro for up to 5 seconds
            if EntityCategoryContains(categories.EXPERIMENTAL, oBomber.UnitId) then
                iMaxMicroTime = 10
                bConsiderIfTooFast = false
            elseif bContinueAttackingUntilTargetDead then iMaxMicroTime = 1000
            end
            if bConsiderIfTooFast then
                iTooCloseIfFastDist = (oBomber[AiBotUnitInfo.refiBomberRange] or 40) * 0.75
                iFastSpeedThreshold = oBomber:GetBlueprint().Air.MaxAirspeed * 0.85 --the function to get a units speed typically gives higher than actual speed since it is measuring 2 axis
            end

            if not(bDontAdjustMicroFlag) then
                EnableUnitMicroUntilManuallyTurnOff(oBomber)
            end

            while GetGameTimeSeconds() - iStartTime < iMaxMicroTime do
                iCurTick = iCurTick + 1

                iFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oBomber)
                iAngleToTarget = AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oTarget:GetPosition())
                iCurAngleDif = iFacingDirection - iAngleToTarget
                iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), oTarget:GetPosition())
                --e.g. if bomber is facing 350 degrees, and the target is at 10 degrees, then it means there's only a dif of 20 degrees, but we want the bomber to go 350+50, rather than 350-50.  Facing - Angle would result in a positive value
                --if instead bomber was facing 10 degrees, and the target was 30 degrees, then would get -20 as the result, and so want to also increase
                --the effect of the below is that when bomber is facing 350 degrees and target 10 degrees, it will treat the difference as being 350 - 10 - 360 = -20, and want the bomber to go 350+50; if insteadbomber 10 and target 30, then dif = -20 and no adjustment made
                if math.abs(iCurAngleDif) > 180 then
                    if iCurAngleDif > 180 then
                        --iFacingDirection is too high so decrease the angle difference
                        iCurAngleDif = iCurAngleDif - 360
                    else --Curangledif must be < -180, so angletotarget is too high
                        iCurAngleDif = iCurAngleDif + 360
                    end
                end

                if iCurAngleDif < 0 then
                    iAngleAdjustToUse = iAngleAdjust
                else iAngleAdjustToUse = -iAngleAdjust
                end

                --Are we close enough to the direction wanted?
                iCurAngleDif = math.abs(iCurAngleDif)
                if iCurAngleDif <= (iMaxAcceptableAngleDif or 15) or iDistToTarget <= iPotentialAbortDistance then
                    --Are close enough in angle so can stop the micro
                    if iDistToTarget <= iPotentialAbortDistance then

                        local tPotentialTarget = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iFacingDirection, iBombStraightLineDistance, true, false, true)
                        iStraightLineLeeway = -(AiBotUtilities.GetDistanceBetweenPositions(tPotentialTarget, oTarget:GetPosition()) - iAOE + 1)
                        if tPotentialTarget and iStraightLineLeeway >= 0 then
                            if bDebugMessages == true then LOG(sFunctionRef..': If we drop infront of the bomber the aoe should hit the target, so setting the ground target based on bomber direction, iStraightLineLeeway='..iStraightLineLeeway) end
                            if EntityCategoryContains(categories.TECH3, oBomber.UnitId) then --strat bomber failed at the default (which is currently as of v141 a dist of 8.5); however when increased by leeway of 2.5 it dropped; so if change the 8.5 value for strats probably want to increase slightly to somewhere between the two
                                local tAltPotentialTarget = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iFacingDirection, iBombStraightLineDistance + iStraightLineLeeway, true, false, true)
                                if tAltPotentialTarget then
                                    tPotentialTarget = {tAltPotentialTarget[1],tAltPotentialTarget[2],tAltPotentialTarget[3]}
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adjusting further to increase the dist by the leeway') end
                                end
                            end
                            tGroundTarget = {tPotentialTarget[1], tPotentialTarget[2], tPotentialTarget[3]}
                        elseif iCurAngleDif <= (iMaxAcceptableAngleDif or 15) * 0.6 then
                            --We are fairly close and aiming in the right direction so just attack rather than trying aoe attack to reduce the risk we just stay hovering in the air never attacking
                            if bDebugMessages == true then LOG(sFunctionRef..': Angle dif is within acceptable range so will try and ground-fire the target') end
                            tGroundTarget = oTarget:GetPosition()
                        end
                    else
                        tGroundTarget = oTarget:GetPosition()
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iCurAngleDif='..iCurAngleDif..'; iMaxAcceptableAngleDif='..iMaxAcceptableAngleDif..'; iDistToTarget='..iDistToTarget..'; iTooCloseIfFastDist='..(iTooCloseIfFastDist or 'nil')..'; iPotentialAbortDistance='..iPotentialAbortDistance..'; Is tGroundTarget empty='..tostring(AiBotUtilities.IsTableEmpty(tGroundTarget))..'; Time='..GetGameTimeSeconds()) end
                if tGroundTarget and AiBotUnitInfo.GetTimeUntilReadyToFireBomb(oBomber) > 0 then
                    --If we cant fire yet then clear the ground target and keep microing
                    tGroundTarget = nil
                    if bDebugMessages == true then LOG(sFunctionRef..': We cant fire yet so wont do ground attack yet, time until can fire='..AiBotUnitInfo.GetTimeUntilReadyToFireBomb(oBomber)..'; oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)) end
                elseif bConsiderIfTooFast and iDistToTarget < iTooCloseIfFastDist then
                    iCurSpeed = AiBotUnitInfo.GetUnitSpeed(oBomber)
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurSpeed='..iCurSpeed..'; iFastSpeedThreshold='..iFastSpeedThreshold..'; Will we clear target due to going too fast='..tostring(iCurSpeed > iFastSpeedThreshold)) end
                    if iCurSpeed > iFastSpeedThreshold then

                        tGroundTarget = nil
                    end

                end
                if tGroundTarget then
                    break
                else
                    if iCurTick == 1 then
                        iActualAngleToUse = iFacingDirection + iAngleAdjustToUse
                        tTempTarget = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iActualAngleToUse, iDistanceAwayToMove, true, false, true)
                        AiBotOrders.IssueTrackedMove(oBomber, tTempTarget, 0, false, 'BMicrM2', true)
                        if bDebugMessages == true then LOG(sFunctionRef..': Just issued move order, iFacingDirection='..iFacingDirection..'; iCurAngleDif='..iCurAngleDif..'; iAngleAdjustToUse='..iAngleAdjustToUse..'; iActualAngleToUse='..iActualAngleToUse..'; angle from bomber to target='..AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tTempTarget)) end
                    elseif iCurTick >= iTicksBetweenOrders then iCurTick = 0
                    end

                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitTicks(1)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    if not(AiBotUnitInfo.IsUnitValid(oBomber)) or not(AiBotUnitInfo.IsUnitValid(oTarget)) then
                        break
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': end of loop for turning to face the target, is tGroundTarget empty='..tostring(AiBotUtilities.IsTableEmpty(tGroundTarget))..'; Is bomber valid='..tostring(AiBotUnitInfo.IsUnitValid(oBomber))..'; Is target valid='..tostring(AiBotUnitInfo.IsUnitValid(oTarget))) end
            if bAdjustHoverMicroCount then aiBrain[refiCurUnitsHoverMicroing] = aiBrain[refiCurUnitsHoverMicroing] - 1 end
            if tGroundTarget and AiBotUnitInfo.IsUnitValid(oBomber) and AiBotUnitInfo.IsUnitValid(oTarget) then
                --Fire the bomb
                --T1 bombers - dont ground-fire engineers that are moving or else we wont hit them
                if iAOE <= 4 and oTarget:IsUnitState('Moving') and AiBotUnitInfo.GetUnitSpeed(oTarget) >= 0.5 then
                    AiBotOrders.IssueTrackedAttack(oBomber, oTarget, false, 'BMicMA', true)
                    if bDebugMessages == true then LOG(sFunctionRef..': Will do manual attack order') end
                else
                    AiBotOrders.IssueTrackedGroundAttack(oBomber, tGroundTarget, 1, false, 'BMicGA', true, oTarget)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Just cleared bomber '..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..' commands and told it to attack tGroundTarget='..repru(tGroundTarget)..'which is expected to hit oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..'; bContinueAttackingUntilTargetDead='..tostring(bContinueAttackingUntilTargetDead or false)..'; bDontAdjustMicroFlag='..tostring(bDontAdjustMicroFlag or false)..'; oBomber[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; GameTime='..GetGameTimeSeconds()) end
                if bContinueAttackingUntilTargetDead then
                    local iDelayForHoverBomb = 0
                    if AiBotUnitInfo.DoesBomberFireSalvo(oBomber) then iDelayForHoverBomb = 2 end
                    if bDebugMessages == true then LOG(sFunctionRef..': Will wait '..iDelayForHoverBomb..' seconds (or 1, if higher), does bomber fire salvo='..tostring(AiBotUnitInfo.DoesBomberFireSalvo(oBomber) or false)) end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitSeconds(math.max(1, iDelayForHoverBomb))
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    --If we have fired recently then wait some more
                    if iDelayForHoverBomb > 0 and oBomber[AiBotUnitInfo.refiLastBombFired] and GetGameTimeSeconds() - oBomber[AiBotUnitInfo.refiLastBombFired] < iDelayForHoverBomb then
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitSeconds(iDelayForHoverBomb - (GetGameTimeSeconds() - oBomber[AiBotUnitInfo.refiLastBombFired]))
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': want to keep attacking target so will call this function again') end
                    if not(bDontAdjustMicroFlag) then
                        oBomber[AiBotUnitInfo.refbSpecialMicroActive] = false
                        if bDebugMessages == true then LOG(sFunctionRef..': Turning off special micro3a') end
                        oBomber[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds()
                    end
                    TurnAirUnitAndAttackTarget(oBomber, oTarget, bDontAdjustMicroFlag, bContinueAttackingUntilTargetDead)
                    --Hover-bomber - wait to see if we fire a bomb as soemtimes we fail to fire which can lead to us not firing for a long time
                elseif bContinueAttackUntilFiredBomb then
                    local iTimeOfOrder = GetGameTimeSeconds()
                    while AiBotUnitInfo.IsUnitValid(oBomber) and AiBotUnitInfo.IsUnitValid(oTarget) do
                        if not(oBomber[AiBotUnitInfo.refiLastBombFired]) or oBomber[AiBotUnitInfo.refiLastBombFired] < iTimeOfOrder then
                            if bDebugMessages == true then LOG(sFunctionRef..': Not fired bomb yet so will wait for bomber to fire, unless we think we have gone passed the target, facing direction='..AiBotUnitInfo.GetUnitFacingAngle(oBomber)..'; Angle to target='..AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tGroundTarget)..'; Special micro flag='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                            if AiBotUtilities.GetAngleDifference(AiBotUnitInfo.GetUnitFacingAngle(oBomber), AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tGroundTarget)) >= 90 then
                                if bDebugMessages == true then LOG(sFunctionRef..': think we have overshot the target, will increase refiBombMissedCount by 1 and abort') end
                                oTarget[AiBotUnitInfo.refiBombMissedCount] = (oTarget[AiBotUnitInfo.refiBombMissedCount] or 0) + 1
                                break
                            else
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                WaitTicks(1)
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                            end
                        else
                            break
                        end
                    end
                    if not(bDontAdjustMicroFlag) then
                        oBomber[AiBotUnitInfo.refbSpecialMicroActive] = false
                        oBomber[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds()
                        if bDebugMessages == true then LOG(sFunctionRef..': Turning off special micro3b') end
                    end
                elseif not(bDontAdjustMicroFlag) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Turning off special micro4') end
                    oBomber[AiBotUnitInfo.refbSpecialMicroActive] = false
                    oBomber[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds()
                end
            elseif not(bDontAdjustMicroFlag) then
                oBomber[AiBotUnitInfo.refbSpecialMicroActive] = false
                oBomber[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds()
                if bDebugMessages == true then LOG(sFunctionRef..': Turning off special micro5') end
            end
        else
            AiBotOrders.IssueTrackedAttack(oBomber, oTarget, false, 'NoMicrAt', false)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MoveAwayFromFactory(oUnit, oEngineerOrFactory)
    --If mobile land has been built by an engineer, check for a factory that built it as well
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MoveAwayFromFactory'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oFactory
    if EntityCategoryContains(categories.STRUCTURE, oEngineerOrFactory.UnitId) then oFactory = oEngineerOrFactory
    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMobileLand, oUnit.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oEngineerOrFactory.UnitId) then
        local aiBrain = oEngineerOrFactory:GetAIBrain()
        local toNearbyFactories = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryFactory, oUnit:GetPosition(), 5, 'Ally') --tried with 4 and didnt work
        if bDebugMessages == true then LOG(sFunctionRef..': Is toNearbyFactories empty='..tostring(AiBotUtilities.IsTableEmpty(toNearbyFactories))) end
        if AiBotUtilities.IsTableEmpty(toNearbyFactories) == false then
            local AiBotFactory = import('/lua/AiBot/AI/AiBotFactory.lua')
            for iNearbyFactory, oNearbyFactory in toNearbyFactories do
                --Have issue where factory can be at say 99% completion, and an assisting engineer triggers the unit completion instead of the factory itself
                if bDebugMessages == true then LOG(sFunctionRef..': oNearbyFactory='..oNearbyFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearbyFactory)..'; work progress='..oNearbyFactory:GetWorkProgress()..'; refsLastBlueprintBuilt='..(oNearbyFactory[AiBotFactory.refsLastBlueprintBuilt] or 'nil')) end
                if oNearbyFactory:GetFractionComplete() == 1 and ((oNearbyFactory:GetWorkProgress() >= 0.99 and oNearbyFactory[AiBotFactory.refsLastBlueprintBuilt] == oUnit.UnitId) or oNearbyFactory:GetWorkProgress() == 0) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Assuming this unit was the underlying factory') end
                    oFactory = oNearbyFactory
                    break
                end
            end
        end
    end

    if oFactory then --and not(EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId)) then

        local aiBrain = oFactory:GetAIBrain()
        if aiBrain.AiBotAI then --redundancy
            local iTeam = aiBrain.AiBotTeam
            local tLZOrWZData, tLZOrWZTeamData
            local iPlateauOrZero, iLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oFactory:GetPosition())
            if bDebugMessages == true then LOG(sFunctionRef..': Near start, iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLZOrWZ='..(iLZOrWZ or 'nil')..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oFactory='..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..'; Time='..GetGameTimeSeconds()) end
            if iLZOrWZ > 0 then
                if iPlateauOrZero == 0 then
                    tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLZOrWZ]][AiBotMap.subrefPondWaterZones][iLZOrWZ]
                    tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                else
                    tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLZOrWZ]
                    tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                end
                if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) == false then
                    local iFactorySize = AiBotUnitInfo.GetBuildingSize(oFactory.UnitId)
                    local tOrderPosition = AiBotUtilities.MoveInDirection(oFactory:GetPosition(), AiBotUtilities.GetAngleFromAToB(oFactory:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]), iFactorySize + 2, true, false, true)
                    --If dealing with land fac then rotate engineer
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oFactory.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) then
                        local iAngleToDestination = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tOrderPosition)
                        if oUnit.SetRotation then oUnit:SetRotation(iAngleToDestination) end

                        if bDebugMessages == true then
                            LOG(sFunctionRef..': Will try and rotate engineer '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..' since FAF code does this, unit facing direction='..AiBotUnitInfo.GetUnitFacingAngle(oUnit)..'; Angle to factory rally='..iAngleToDestination..'; will draw tOrderPosition, is set rotation nil='..tostring(oUnit.SetRotation == nil))
                            AiBotUtilities.DrawLocation(tOrderPosition)
                        end
                    end
                    AiBotOrders.IssueTrackedMove(oUnit, tOrderPosition, 0, false, 'JustBuilt', true)
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': Just told unit to move to tOrderPosition, will draw in blue')
                        AiBotUtilities.DrawLocation(tOrderPosition)
                    end
                    local iMicroDelay = 1.5
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryQuantumGateway, oFactory.UnitId) then iMicroDelay = 4 --done as when was 1.5 would have RAS SACUs given new orders like GE template just after being built and getting stuck
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oFactory.UnitId) and EntityCategoryContains(AiBotUnitInfo.categories.TECH3 * AiBotUnitInfo.refCategoryNavalSurface, oUnit.UnitId) then iMicroDelay = 4
                    end
                    TrackTemporaryUnitMicro(oUnit, 1.5)
                end

            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' built from factory '..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..' at time='..GetGameTimeSeconds()) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedUnitMove(oUnit, tMoveDirection, iMoveThreshold, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder, iSecondsToWait)

    WaitSeconds(iSecondsToWait)
    if AiBotUnitInfo.IsUnitValid(oUnit) then
        AiBotOrders.IssueTrackedMove(oUnit, tMoveDirection, iMoveThreshold, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    end
end

function MegalithRetreatMicro(oUnit, tRallyPoint, tClosestFriendlyBase, oClosestEnemyUnit)
    --Tries to retreat the unit, returns false if couldnt find suitable retreat location
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MegalithRetreatMicro'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bGivenOrder = false

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Time since last weapon event='..(GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0))..'; refiTimeBetweenDFShots='..(oUnit[AiBotUnitInfo.refiTimeBetweenDFShots] or 'nil')) end
    if not(oUnit[AiBotUnitInfo.refbEasyBrain]) and (oUnit[AiBotUnitInfo.refiLastWeaponEvent] and GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiLastWeaponEvent]) < (oUnit[AiBotUnitInfo.refiTimeBetweenDFShots] or 1.2) + 0.5 then

        --Only consider applying micro if moving in opposite direction to that which we are facing should result in us moving in similar direction to rally point or closest base
        local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tRallyPoint)
        local iAngleToClosestBase = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tClosestFriendlyBase)
        local iFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oUnit)
        local iAngleIfMoving = iFacingDirection + 180
        if iAngleIfMoving > 360 then iAngleIfMoving = iAngleIfMoving - 360 end
        local tMoveDirection



        if AiBotUtilities.GetAngleDifference(iAngleToRally, iAngleIfMoving) <= 60 or AiBotUtilities.GetAngleDifference(iAngleToClosestBase, iAngleIfMoving) <= 60 then
            --Do we have an enemy in our range that we are near facing?
            local iMaxAngleDif
            if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= oUnit[AiBotUnitInfo.refiTimeBetweenDFShots] then
                iMaxAngleDif = 40
            else
                iMaxAngleDif = 30
            end
            local bFacingEnemy = false
            if AiBotUnitInfo.IsUnitValid(oClosestEnemyUnit) and AiBotUtilities.GetAngleDifference(iFacingDirection, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oClosestEnemyUnit:GetPosition())) <= iMaxAngleDif then
                if bDebugMessages == true then LOG(sFunctionRef..': Angle to closest enemy='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oClosestEnemyUnit:GetPosition())..'; iFacingDirection='..iFacingDirection..'; ANgle dif='..AiBotUtilities.GetAngleDifference(iFacingDirection, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oClosestEnemyUnit:GetPosition()))) end
                bFacingEnemy = true
            else
                --Check all nearby enemies
                local tNearbyEnemyUnits = oUnit:GetAIBrain():GetUnitsAroundPoint(categories.DIRECTFIRE + categories.INDIRECTFIRE + AiBotUnitInfo.refCategoryExperimentalLevel - categories.AIR * categories.MOBILE, oUnit:GetPosition(), oUnit[AiBotUnitInfo.refiDFRange], 'Enemy')
                if AiBotUtilities.IsTableEmpty(tNearbyEnemyUnits) == false then
                    for iEnemy, oEnemy in tNearbyEnemyUnits do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; Angle to enemy='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemy:GetPosition())..'; iFacingDirection='..iFacingDirection..'; ANgle dif='..AiBotUtilities.GetAngleDifference(iFacingDirection, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemy:GetPosition()))..'; iMaxAngleDif='..iMaxAngleDif) end
                        if AiBotUtilities.GetAngleDifference(iFacingDirection, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemy:GetPosition())) <= iMaxAngleDif and not(AiBotUnitInfo.IsUnitUnderwater(oEnemy)) then
                            bFacingEnemy = true
                            break
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bFacingEnemy='..tostring(bFacingEnemy or false)) end
            if bFacingEnemy then
                local iDistanceToMove = 8 --worked ok with value of 5
                tMoveDirection = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleIfMoving, iDistanceToMove, true, false, true)
                if AiBotUtilities.IsTableEmpty(tMoveDirection) == false then
                    local t60thpoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleIfMoving, iDistanceToMove * 0.6, true, false, true)
                    if AiBotUtilities.IsTableEmpty(t60thpoint) == false then
                        --If there are buildings around here then megalith wont go backwards but instead will turn around
                        local tUnitsAroundDestination = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(t60thpoint, 5))
                        if AiBotUtilities.IsTableEmpty(tUnitsAroundDestination) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure, tUnitsAroundDestination)) then


                            --Looks like megalith has to be stationery or reversing for this to work?
                            local tCurOrder = oUnit[AiBotOrders.reftiLastOrders][1]
                            local bClearAndWait = false
                            if tCurOrder then
                                if tCurOrder[AiBotOrders.refiOrderIssueMove] == AiBotOrders.refiOrderIssueMove and AiBotUtilities.IsTableEmpty(tCurOrder[AiBotOrders.subreftOrderPosition]) == false then
                                    if AiBotUtilities.GetDistanceBetweenPositions(tMoveDirection, tCurOrder[AiBotOrders.subreftOrderPosition]) >= iDistanceToMove then
                                        bClearAndWait = true
                                    end
                                else
                                    bClearAndWait = true
                                end

                            end
                            if bClearAndWait then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will clear orders then do delayed move') end
                                AiBotOrders.IssueTrackedClearCommands(oUnit)
                                ForkThread(DelayedUnitMove, oUnit, tMoveDirection, iDistanceToMove * 0.45, false, 'MegDelM', false, 0.75) --tried with 0.25s delay and led to megalith turning around; 0.75 worked in the replay where megalith moved in a circle before; if find it doesnt work in other caess though the nincrease to 1s and add unit micro tracking
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Are already trying to kite so will just check if move order needs updating') end
                                AiBotOrders.IssueTrackedMove(oUnit, tMoveDirection, iDistanceToMove * 0.45, false, 'MegMiRM', false)
                            end
                            bGivenOrder = true
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Have buildings around the target destination so dont want to try and move there') end
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Near end of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bGivenOrder='..tostring(bGivenOrder or false)..'; tMoveDirection='..repru(tMoveDirection)..'; iFacingDirection='..iFacingDirection..'; iAngleToRally='..iAngleToRally..'; iAngleToClosestBase='..iAngleToClosestBase..'; iAngleIfMoving='..iAngleIfMoving..'; oClosestEnemyUnit='..(oClosestEnemyUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemyUnit) or 'nil')..'; Time since last fired weapon='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; Time='..GetGameTimeSeconds()) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bGivenOrder
end

function MonkeylordRetreatMicro(oUnit, tRallyPoint, tClosestFriendlyBase, oClosestEnemyUnit)
    --Tries to retreat the unit, returns false if couldnt find suitable retreat location
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MonkeylordRetreatMicro'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bGivenOrder = false

    if not(oUnit[AiBotUnitInfo.refbEasyBrain]) then

        --Only consider applying micro if moving in opposite direction to that which we are facing should result in us moving in similar direction to rally point or closest base
        local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tRallyPoint)
        local tRallyOrBaseToGoTo
        local iAngleToRallyOrBase
        local iAngleDifToRallyOrBase
        local iFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oUnit)
        local iAngleIfMoving = iFacingDirection + 180
        if iAngleIfMoving > 360 then iAngleIfMoving = iAngleIfMoving - 360 end
        local tMoveDirection


        iAngleDifToRallyOrBase = AiBotUtilities.GetAngleDifference(iAngleToRally, iAngleIfMoving)
        if iAngleDifToRallyOrBase <= 60 then
            tRallyOrBaseToGoTo = {tRallyPoint[1], tRallyPoint[2], tRallyPoint[3]}
            iAngleToRallyOrBase = iAngleToRally
        else
            local iAngleToClosestBase = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tClosestFriendlyBase)
            iAngleDifToRallyOrBase = AiBotUtilities.GetAngleDifference(iAngleToClosestBase, iAngleIfMoving)
            if iAngleDifToRallyOrBase <= 60 then
                tRallyOrBaseToGoTo = {tClosestFriendlyBase[1], tClosestFriendlyBase[2], tClosestFriendlyBase[3]}
                iAngleToRallyOrBase = iAngleToClosestBase
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iAngleToRallyOrBase='..(iAngleToRallyOrBase or 'nil')..'; iAngleDifToRallyOrBase='..(iAngleDifToRallyOrBase or 'nil')..'; iAngleIfMoving='..iAngleIfMoving..'; tRallyOrBaseToGoTo='..repru(tRallyOrBaseToGoTo)..'; oUnit:GetPosition()='..repru(oUnit:GetPosition())..'; Time='..GetGameTimeSeconds()) end
        if tRallyOrBaseToGoTo then
            --Do we have an enemy in our range that we are near facing?
            local iMaxAngleDif
            if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= 1 then --incase we dont have proper time betweenshots due to laser and bolters being dif
                iMaxAngleDif = 50
            else
                iMaxAngleDif = 40
            end
            local bFacingEnemy = false
            if AiBotUnitInfo.IsUnitValid(oClosestEnemyUnit) and AiBotUtilities.GetAngleDifference(iFacingDirection, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oClosestEnemyUnit:GetPosition())) <= iMaxAngleDif then
                if bDebugMessages == true then LOG(sFunctionRef..': Angle to closest enemy='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oClosestEnemyUnit:GetPosition())..'; iFacingDirection='..iFacingDirection..'; ANgle dif='..AiBotUtilities.GetAngleDifference(iFacingDirection, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oClosestEnemyUnit:GetPosition()))) end
                bFacingEnemy = true
            else
                --Check all nearby enemies
                local tNearbyEnemyUnits = oUnit:GetAIBrain():GetUnitsAroundPoint(categories.DIRECTFIRE + categories.INDIRECTFIRE + AiBotUnitInfo.refCategoryExperimentalLevel - categories.AIR * categories.MOBILE, oUnit:GetPosition(), math.max(64, oUnit[AiBotUnitInfo.refiDFRange]) + 12, 'Enemy')
                if AiBotUtilities.IsTableEmpty(tNearbyEnemyUnits) == false then
                    for iEnemy, oEnemy in tNearbyEnemyUnits do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; Angle to enemy='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemy:GetPosition())..'; iFacingDirection='..iFacingDirection..'; ANgle dif='..AiBotUtilities.GetAngleDifference(iFacingDirection, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemy:GetPosition()))..'; iMaxAngleDif='..iMaxAngleDif) end
                        if AiBotUtilities.GetAngleDifference(iFacingDirection, AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemy:GetPosition())) <= iMaxAngleDif and not(AiBotUnitInfo.IsUnitUnderwater(oEnemy)) then
                            bFacingEnemy = true
                            break
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bFacingEnemy='..tostring(bFacingEnemy or false)) end
            if bFacingEnemy then
                local iDistanceToMove = 8
                --Monkeylord - want to move/rotate to one side to move backwards
                local iAngleAdjustmentWanted = 20
                --base angle dif is iAngleDifToRallyOrBase
                --NOTE: In contrast to normally where would want to move with the smallest angle dif, here we want to move with the biggest angle dif, since that should cause us to then turn in the opposite direction
                if AiBotUtilities.GetAngleDifference(iAngleIfMoving + iAngleAdjustmentWanted, iAngleToRallyOrBase) < iAngleDifToRallyOrBase + iAngleAdjustmentWanted then
                    iAngleAdjustmentWanted = iAngleAdjustmentWanted * -1
                end
                iAngleIfMoving = iAngleIfMoving + iAngleAdjustmentWanted

                tMoveDirection = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleIfMoving, iDistanceToMove, true, false, true)
                if AiBotUtilities.IsTableEmpty(tMoveDirection) == false then
                    --if bDebugMessages == true then AiBotUtilities.DrawLocation(tMoveDirection) end
                    local t60thpoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleIfMoving, iDistanceToMove * 0.6, true, false, true)
                    if AiBotUtilities.IsTableEmpty(t60thpoint) == false then
                        --If there are buildings around here then megalith wont go backwards but instead will turn around; so a good chance monkeylord will also suffer problems
                        local tUnitsAroundDestination = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(t60thpoint, 5))
                        if bDebugMessages == true then LOG(sFunctionRef..': Is tUnitsAroundDestination empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsAroundDestination))) end
                        if AiBotUtilities.IsTableEmpty(tUnitsAroundDestination) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure, tUnitsAroundDestination)) then


                            local tCurOrder = oUnit[AiBotOrders.reftiLastOrders][1]
                            local bClearAndWait = false
                            --If monkeylord is advancing and then starts doing this micro, it causes it to keep moving forwards when turning
                            if tCurOrder then
                                if tCurOrder[AiBotOrders.refiOrderIssueMove] == AiBotOrders.refiOrderIssueMove and AiBotUtilities.IsTableEmpty(tCurOrder[AiBotOrders.subreftOrderPosition]) == false then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Monkeylord last order was a move order, dist from cur position to order position='..AiBotUtilities.GetDistanceBetweenPositions(tMoveDirection, tCurOrder[AiBotOrders.subreftOrderPosition])..'; Monkeylord speed='..AiBotUnitInfo.GetUnitSpeed(oUnit)) end
                                    if AiBotUtilities.GetDistanceBetweenPositions(tMoveDirection, tCurOrder[AiBotOrders.subreftOrderPosition]) > iDistanceToMove and AiBotUnitInfo.GetUnitSpeed(oUnit) > 0  then
                                        bClearAndWait = true
                                    end
                                else
                                    bClearAndWait = true
                                end

                            end
                            if not(bClearAndWait) then
                                --Check monkeylord speed and direction
                                local iVelocityX, iVelocityY, iVelocityZ = oUnit:GetVelocity()
                                --What direction do we want to be moving? e.g. if enemy is below us then we want velocityZ to be negative (or almost 0); if enemy is to our left we want velocityX to be positive (or almost 0)
                                --So vertical: if angle to retreat location is 270+ or <= 90 then we want to be moving up (so negative Z); will ignore angles close to neutral re this though
                                local iThresholdWhereIgnore = 0.03 --when having monkeylord retreat north-east the highest value when it was retreating correctly was 0.094 in one direction, while other was 0.05 at the time; so if it is less than 0.03 then will ignore, otherwise will want correct signage
                                if math.abs(iVelocityZ) > iThresholdWhereIgnore then
                                    if iAngleToRallyOrBase <= 80 or iAngleToRallyOrBase >= 280 then
                                        --Want negative Z or almost 0
                                        if iVelocityZ > 0 then
                                            bClearAndWait = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Z movement is in the wrong direction (we are going south and want to go north)') end
                                        end
                                    elseif iAngleToRallyOrBase <= 260 and iAngleToRallyOrBase >= 100 then --we want to go down, so want Z to be positive
                                        if iVelocityZ < 0 then
                                            bClearAndWait = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Z movement is in the wrong direction (we are going north and want to go south)') end
                                        end
                                    end
                                end
                                if not(bClearAndWait) and math.abs(iVelocityX) > iThresholdWhereIgnore then
                                    if iAngleToRallyOrBase >= 10 and iAngleToRallyOrBase <= 170 then
                                        --Want to move east, i.e. want X to be positive
                                        if iVelocityX < 0 then
                                            bClearAndWait = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': X movement is in wrong direction (we are going west when want to go east') end
                                        end
                                    elseif iAngleToRallyOrBase >= 190 and iAngleToRallyOrBase <= 350 then
                                        --Want to move west, i.e. want X to be negative
                                        if iVelocityX > 0 then
                                            bClearAndWait = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': X movement is in wrong direction (we are going east when want to go west') end
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iVelocityX='..iVelocityX..'; iVelocityZ='..iVelocityZ..'; bClearAndWait after checks='..tostring(bClearAndWait)) end
                            end
                            if bClearAndWait then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will clear orders then do delayed move') end
                                AiBotOrders.IssueTrackedClearCommands(oUnit)
                                ForkThread(DelayedUnitMove, oUnit, tMoveDirection, iDistanceToMove * 0.45, false, 'MonkDelM', false, 0.75) --tried with 0.25s delay and led to megalith turning around; 0.75 worked in the replay where megalith moved in a circle before; if find it doesnt work in other caess though the nincrease to 1s and add unit micro tracking
                                bGivenOrder = true
                            else


                                --Revise move direction


                                if bDebugMessages == true then LOG(sFunctionRef..': will just check if move order needs updating') end
                                AiBotOrders.IssueTrackedMove(oUnit, tMoveDirection, iDistanceToMove * 0.45, false, 'MonMiRM', false)
                                --end
                                bGivenOrder = true
                            end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Have buildings around the target destination so dont want to try and move there') end
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Near end of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bGivenOrder='..tostring(bGivenOrder or false)..'; tMoveDirection='..repru(tMoveDirection)..'; iFacingDirection='..iFacingDirection..'; iAngleToRally='..iAngleToRally..'; iAngleIfMoving='..iAngleIfMoving..'; oClosestEnemyUnit='..(oClosestEnemyUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemyUnit) or 'nil')..'; Time since last fired weapon='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; Time='..GetGameTimeSeconds()) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bGivenOrder
end

function MoveAndKillAirUnit(oUnit)
    --Move to a random nearby positionand then ctrl-k; reason is to reduce likelihood we are detsroying existing wrecks
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MoveAndKillAirUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oUnit) then --redundancy
        if bDebugMessages == true then LOG(sFunctionRef..': About to give more and kill order to unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; time='..GetGameTimeSeconds()) end
        if oUnit[AiBotUnitInfo.refbEasyBrain] then
            AiBotOrders.IssueTrackedKillUnit(oUnit)
        else
            local iPotentialXAdjust, iPotentialZAdjust
            local iSearchRadius = 30
            local bHaveLowHealthUnitOrReclaim
            local iMaxSearchAttempt = 10
            for iSearchAttempt = 1, iMaxSearchAttempt do
                bHaveLowHealthUnitOrReclaim = false
                iPotentialXAdjust = math.random(1,iSearchRadius*2) - iSearchRadius
                iPotentialZAdjust = math.random(1,iSearchRadius*2) - iSearchRadius
                local tPotentialPosition = oUnit:GetPosition()
                tPotentialPosition[1] = tPotentialPosition[1] + iPotentialXAdjust
                tPotentialPosition[3] = tPotentialPosition[3] + iPotentialXAdjust
                --Check no low health units (e.g. radar, shields) at the target position unless cant find any
                if iSearchAttempt < iMaxSearchAttempt then
                    local rRectangleToSearch = AiBotUtilities.GetRectAroundLocation(tPotentialPosition, 1)
                    local tUnitsNearPosition = GetUnitsInRect(rRectangleToSearch)
                    if AiBotUtilities.IsTableEmpty(tUnitsNearPosition) == false then
                        local tBuildings = EntityCategoryFilterDown(categories.STRUCTURE + categories.EXPERIMENTAL,  tUnitsNearPosition)
                        if AiBotUtilities.IsTableEmpty(tBuildings) == false then
                            for iNearbyUnit, oNearbyUnit in tBuildings do
                                if oNearbyUnit:GetHealth() <= 110 then
                                    bHaveLowHealthUnitOrReclaim = true
                                    break
                                end
                            end
                        end
                    end
                    if not(bHaveLowHealthUnitOrReclaim) then
                        local iReclaimNearby = AiBotMap.GetReclaimInRectangle(3, rRectangleToSearch)
                        if iReclaimNearby >= 10 then
                            bHaveLowHealthUnitOrReclaim = true
                        end
                        --iReturnType: 1 = true/false; 2 = number of wrecks; 3 = total mass, 4 = valid wrecks, 5 = energy
                    end
                end
                if not(bHaveLowHealthUnitOrReclaim) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have got location to move to for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; .Dead='..tostring(oUnit.Dead or false)..'; been destroyed='..tostring(oUnit:BeenDestroyed())..'; tPotentialPosition='..repru(tPotentialPosition)) end
                    AiBotOrders.IssueTrackedMove(oUnit, tPotentialPosition, 0, false, 'MveToDie', true)
                    TrackTemporaryUnitMicro(oUnit, 3)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitSeconds(3)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        AiBotOrders.IssueTrackedKillUnit(oUnit)
                    end
                    break
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function KeepUnitsAwayFromNukeOrTMLTarget(oProjectile, oLauncher, iTeam, bEnemyNuke)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'KeepUnitsAwayFromNukeOrTMLTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(oProjectile:BeenDestroyed()) and oProjectile.GetCurrentTargetPosition then
        --LOG('Blueprint for projectile repru='..repru(oProjectile.Blueprint))
        local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
        if aiBrain then
            if bDebugMessages == true then LOG(sFunctionRef..': Outer ring='..repru(oProjectile.OuterRing)..'; Inner ring='..repru(oProjectile.InnerRing)..'; oLauncher='..(oLauncher.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oLauncher) or 'nil')) end
            --Record in friendly nuke table
            local tTarget = oProjectile:GetCurrentTargetPosition()
            local iSearchArea, iCategoriesToSearch
            local iSpeed = (oProjectile.Blueprint.Physics.MaxSpeed or 10)

            local bIsTML = EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oLauncher.UnitId)
            if bIsTML then
                iSearchArea = (oProjectile.CreatedByWeapon.Blueprint.DamageRadius or 2) + 2
                iCategoriesToSearch = categories.COMMAND + categories.SUBCOMMANDER + AiBotUnitInfo.refCategoryLandExperimental + categories.LAND * categories.TECH2 * categories.MOBILE + categories.LAND * categories.TECH3 * categories.MOBILE
            else
                --Nuke
                iSearchArea = math.min((oProjectile.OuterRing.Radius or 50), math.max(56, (oProjectile.InnerRing.Radius or 35) + 15)) + 4
                iCategoriesToSearch = AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryMobileLand * categories.TECH3 + AiBotUnitInfo.refCategoryAllNavy * categories.MOBILE - categories.TECH1 + categories.COMMAND + categories.SUBCOMMANDER
                ForkThread(AiBotBuilding.RecordNukeTarget, iTeam, tTarget)
            end

            local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(tTarget, oProjectile:GetPosition())
            local iTimeToTarget = iDistToTarget / iSpeed
            if bDebugMessages == true then LOG(sFunctionRef..': iSpeed='..iSpeed..'; iDistToTarget='..iDistToTarget..'; iTimeToTarget='..iTimeToTarget..'; iSearchArea='..iSearchArea..'; Excess time='..(iTimeToTarget - iSearchArea / 2)*10) end
            if iTimeToTarget >= iSearchArea / 2 + 1 and (not(bIsTML) or iTimeToTarget >= iSearchArea / 2 + 2) then --wait until almost the last moment before moving away; however want to allow enough time for a unit in the middle of the target to get out of the way
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                if bIsTML then --when testing, missile hit when timetotarget was less than 1s, but dodged when it was 2.1s (campaign mission Cybran TML)
                    if bDebugMessages == true then LOG(sFunctionRef..': Will wait '..math.max(1, math.floor((iTimeToTarget - 2 - iSearchArea / 2)*10))..' ticks before giving move orders to move away') end
                    WaitTicks(math.max(1, math.floor((iTimeToTarget - 2 - iSearchArea / 2)*10)))
                else
                    WaitTicks(math.max(1, math.floor((iTimeToTarget - 1 - iSearchArea / 2)*10)))
                end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
            local iAngleToUnit
            local iMoveDistance = iSearchArea + 15
            local bKeepInCampaignArea = AiBotMap.bIsCampaignMap
            local iAngleToTMLLauncher, iAngleDifToLauncher

            while not(oProjectile:BeenDestroyed()) and not(aiBrain.AiBotIsDefeated)  do
                --Every second check for friendly experimental, ACU, and T3 land units around the target area and have them move away
                --First check the missile is close enough that we should try and have units run
                local tFriendlyUnitsNearTarget = aiBrain:GetUnitsAroundPoint(iCategoriesToSearch, tTarget, iSearchArea, 'Ally')
                if bDebugMessages == true then LOG(sFunctionRef..': Is tFriendlyUnitsNearTarget empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyUnitsNearTarget))..'; Time='..GetGameTimeSeconds()) end
                if AiBotUtilities.IsTableEmpty(tFriendlyUnitsNearTarget) == false then
                    for iUnit, oUnit in tFriendlyUnitsNearTarget do
                        if oUnit:GetAIBrain().AiBotAI and (not(oUnit[AiBotUnitInfo.refbEasyBrain]) or (not(bEnemyNuke) and EntityCategoryContains(categories.COMMAND + categories.SUBCOMMANDER + AiBotUnitInfo.refCategoryExperimentalLevel, oUnit.UnitId))) then
                            iAngleToUnit = AiBotUtilities.GetAngleFromAToB(tTarget, oUnit:GetPosition())
                            if bIsTML then
                                iAngleToTMLLauncher = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oLauncher:GetPosition())
                                iAngleDifToLauncher = AiBotUtilities.GetAngleDifference(iAngleToUnit, iAngleToTMLLauncher)
                                if bDebugMessages == true then LOG(sFunctionRef..': iAngleToTMLLauncher='..iAngleToTMLLauncher..'; iAngleDifToLauncher='..iAngleDifToLauncher) end
                                if iAngleDifToLauncher < 20 then --TML missiles can hit us if we are moving in similar path as they fly lower than nukes
                                    if AiBotUtilities.GetAngleDifference(iAngleToUnit + 15, iAngleToTMLLauncher) > AiBotUtilities.GetAngleDifference(iAngleToUnit - 15, iAngleToTMLLauncher) then
                                        iAngleToUnit = iAngleToUnit + 15
                                    else
                                        iAngleToUnit = iAngleToUnit - 15
                                    end
                                end
                            end
                            local tMoveAwayPoint = AiBotUtilities.MoveInDirection(tTarget, iAngleToUnit, iMoveDistance, true, false, bKeepInCampaignArea)
                            AiBotOrders.IssueTrackedMove(oUnit, tMoveAwayPoint, 5, false, 'NukeDodge', true)
                            TrackTemporaryUnitMicro(oUnit, 1)
                        end
                    end
                end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MonitorEnemyNukeOrTMLMissileForIntel(oProjectile, iTeam)
    --Intended for hostile nuke - want to try and take evasive action once we see hten uke being launched
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MonitorEnemyNukeOrTMLMissileForIntel'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of loop for iTeam='..iTeam..'; oProjectile.Launcher='..(oProjectile.Launcher.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oProjectile.Launcher) or 'nil')..'; oProjectile.GetCurrentTargetPosition='..reprs(oProjectile.GetCurrentTargetPosition)..'; Time='..GetGameTimeSeconds()) end
    if not(oProjectile:BeenDestroyed()) and oProjectile.GetCurrentTargetPosition then
        if bDebugMessages == true then LOG(sFunctionRef..': GetCurrentTargetPosition()='..reprs(oProjectile:GetCurrentTargetPosition())) end
        local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
        if aiBrain then
            local iCurDist
            local iTickDelayBetweenChecks = 1
            if AiBotLand.iTicksPerLandCycle > 11 then iTickDelayBetweenChecks = math.max(1, math.floor(AiBotLand.iTicksPerLandCycle / 10)) end
            local bHaveIntel = false
            while not(oProjectile:BeenDestroyed()) do
                --Check if we have intel of this position (i.e. visual)
                local tCurLZData, tCurLZTeamData = AiBotMap.GetLandOrWaterZoneData(oProjectile:GetPosition(), true, iTeam)
                if bDebugMessages == true then
                    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oProjectile:GetPosition())
                    LOG(sFunctionRef..': Considering if we have units in the zone where the missile is, iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; is table of units empty='..tostring(AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))..'; Time='..GetGameTimeSeconds())
                end
                if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    local tCurMissilePosition = oProjectile:GetPosition()
                    for iUnit, oUnit in tCurLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] do
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tCurMissilePosition, oUnit:GetPosition())
                            if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurDist='..iCurDist..'; Dist less vision='..iCurDist - (oUnit:GetBlueprint().Intel.VisionRadius or 0)) end
                            if iCurDist <= 100 and iCurDist - (oUnit:GetBlueprint().Intel.VisionRadius or 0) < 0 then
                                if bDebugMessages == true then LOG(sFunctionRef..': We have intel so aborting') end
                                bHaveIntel = true
                                break
                            end
                        end
                    end
                    if bHaveIntel then break end
                end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitTicks(iTickDelayBetweenChecks)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Exited the projectile monitor loop, bHaveIntel='..tostring(bHaveIntel)..'; Time='..GetGameTimeSeconds()) end
            if bHaveIntel then
                if EntityCategoryContains(AiBotUnitInfo.refCategorySML, oProjectile.Launcher.UnitId)
                or EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oProjectile.Launcher.UnitId) then
                    if bDebugMessages == true then LOG(sFunctionRef..': We have intel of enemy TML or nuke so will make units avoid the target') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    KeepUnitsAwayFromNukeOrTMLTarget(oProjectile, oProjectile.Launcher, iTeam, true)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                else
                    AiBotUtilities.ErrorHandler('Unrecognised missile launcher type, need code adding')
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderAirAAHoverAttackTowardsTarget(oUnit, oWeapon)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderAirAAHoverAttackTowardsTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oTarget = oWeapon:GetCurrentTarget()
    if bDebugMessages == true then
        LOG(sFunctionRef..': Start of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is oTarget valid='..tostring(AiBotUnitInfo.IsUnitValid(oTarget))..'; oTarget='..(oTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTarget) or 'nil')..'; Is special micro active='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive]))
        if AiBotUnitInfo.IsUnitValid(oTarget) then
            LOG(sFunctionRef..': Unit state of target='..AiBotUnitInfo.GetUnitState(oTarget)..'; Time since oUnit last fired='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0))
        end
    end
    if AiBotUnitInfo.IsUnitValid(oTarget) and oTarget:GetFractionComplete() == 1 and not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then

        --LOUD - check unit isn't on ground
        local bProceedWithMicro = true
        if oUnit.Dead or oTarget.Dead then
            bProceedWithMicro = false
        elseif (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and not(oTarget:IsUnitState('Moving')) and not(oTarget:IsUnitState('Attacking')) then
            local tTargetPosition = oTarget:GetPosition()
            if tTargetPosition[2] - GetSurfaceHeight(tTargetPosition[1], tTargetPosition[3]) < 1 then
                bProceedWithMicro = false
            end
        end
        if bProceedWithMicro then
            local iOurMaxSpeed = oUnit:GetBlueprint().Air.MaxAirspeed
            local iEnemyMaxSpeed = oTarget:GetBlueprint().Air.MaxAirspeed
            --local iMaxAngleToTryAndTurn = 20
            --Want to consider hover-turning against enemy asfs if we have same speed as them and we arent chasing them (suggesting they might be turning or they might be facing us)
            --(wont use hover-logic on enemy asfs once we have reached 100+ asfs to avoid massive slowdown)
            if bDebugMessages == true then LOG(sFunctionRef..': iOurMaxSpeed='..(iOurMaxSpeed or 'nil')..'; iEnemyMaxSpeed='..(iEnemyMaxSpeed or 'nil')..'; Our facing angle='..AiBotUnitInfo.GetUnitFacingAngle(oUnit)..'; Enemy unit facing angle='..AiBotUnitInfo.GetUnitFacingAngle(oTarget)..'; Angle dif='..AiBotUtilities.GetAngleDifference(AiBotUnitInfo.GetUnitFacingAngle(oUnit), AiBotUnitInfo.GetUnitFacingAngle(oTarget))..'; Dist to enemy='..AiBotUtilities.GetDistanceBetweenPositions(oTarget:GetPosition(), oUnit:GetPosition())) end
            --If our max speed isnt much dif to enemy, and we are facing them, and they are facing away from us, then dont consider hovering (as we are better off with normal logic that sees us close in to them)
            if iOurMaxSpeed and iEnemyMaxSpeed and iOurMaxSpeed >= iEnemyMaxSpeed and (iOurMaxSpeed >= iEnemyMaxSpeed * 1.2 or (AiBotUnitInfo.GetUnitLifetimeCount(oUnit) <= 100 and AiBotUtilities.GetAngleDifference(AiBotUnitInfo.GetUnitFacingAngle(oUnit), AiBotUnitInfo.GetUnitFacingAngle(oTarget)) <= 130)) then
                local iOurRange = (oUnit[AiBotUnitInfo.refiAARange] or 0)
                if bDebugMessages == true then LOG(sFunctionRef..': iOurRange='..iOurRange..'; oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..'; Is it an air unit='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryAllAir, oTarget.UnitId))) end
                if iOurRange > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryAllAir, oTarget.UnitId) then
                    --Want to try and do hover-micro
                    EnableUnitMicroUntilManuallyTurnOff(oUnit)
                    --oUnit[AiBotUnitInfo.refbSpecialMicroActive] = true
                    local iCurDistToTarget
                    local iCurAngleToTarget
                    local iCurFacingAngle
                    local iCurSpeed, iTargetCurSpeed
                    local iOrigDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oTarget:GetPosition())
                    local iMaxDistToTargetBeforeAborting
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oTarget.UnitId) then
                        iMaxDistToTargetBeforeAborting = math.max(110, iOrigDistToTarget + 50, iOurRange + 40)
                    else
                        iMaxDistToTargetBeforeAborting = math.max(60, iOrigDistToTarget + 20, iOurRange + 20)
                    end
                    --[[local iMinDistToTarget = math.min(iOurRange * 0.8, math.max(iOurRange * 0.5, iOurRange - 5))
                    local iMaxDistToConsiderHoverTurn = 50
                    local iHalfDistThreshold = iOurRange * 0.5
                    local iCurAngleDif
                    local bTurnClockwise--]]
                    local bEnemyIsCloseToOurSpeed = false
                    if iEnemyMaxSpeed >= iOurMaxSpeed * 0.95 then bEnemyIsCloseToOurSpeed = true end
                    local iReorderDist = 0.1
                    --local iDistToMoveTowardsTarget, iAngleToMove
                    local iMaxTimeBetweenShotsWanted = oUnit[AiBotUnitInfo.refiTimeBetweenAirAAShots]
                    if not(iMaxTimeBetweenShotsWanted) then iMaxTimeBetweenShotsWanted = 8
                    else iMaxTimeBetweenShotsWanted = iMaxTimeBetweenShotsWanted + math.max(3, iMaxTimeBetweenShotsWanted * 0.5) --see v307 notes for detailed scenarios and testing to come up with this value; high variability from different replay sandbox tests
                    end
                    local iMaxDistForStopMicro = iOurRange + math.max(iOurRange, 45) --see v307 notes for detailed scenarios and testing to come up with this value; high variability from different replay sandbox tests
                    --v306 and earlier:
                    local iMaxTimeBetweenShotsWanted = oUnit[AiBotUnitInfo.refiTimeBetweenAirAAShots]
                    if not(iMaxTimeBetweenShotsWanted) then iMaxTimeBetweenShotsWanted = 5
                    else iMaxTimeBetweenShotsWanted = iMaxTimeBetweenShotsWanted + math.max(2, iMaxTimeBetweenShotsWanted * 0.25)
                        --v306 and earlier: else iMaxTimeBetweenShotsWanted = iMaxTimeBetweenShotsWanted + math.max(0.5, iMaxTimeBetweenShotsWanted * 0.15)
                    end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitTicks(1)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

                    --local bManualAttack, iCurSpeed
                    local bUseStopMicro = EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA *  categories.TECH3, oTarget.UnitId)
                    local bLastOrderWasStopOrder = false
                    local bShowUnitOrdersInName = import('/lua/AiBot/AiBotConfig.lua').AiBotShowUnitNames


                    while AiBotUnitInfo.IsUnitValid(oTarget) and AiBotUnitInfo.IsUnitValid(oUnit) do
                        local tMoveViaPoint = oTarget:GetPosition()
                        iCurFacingAngle = nil
                        iCurSpeed = nil
                        iCurDistToTarget = VDist3(oUnit:GetPosition(), oTarget:GetPosition())
                        if bDebugMessages == true then LOG(sFunctionRef..': 3d dist to target='..iCurDistToTarget..'; Time since last weapon event='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; iOurRange='..iOurRange..'; iMaxTimeBetweenShotsWanted='..iMaxTimeBetweenShotsWanted..'; bLastOrderWasStopOrder='..tostring(bLastOrderWasStopOrder or false)..'; iMaxDistForStopMicro='..iMaxDistForStopMicro..'; Time='..GetGameTimeSeconds()) end
                        --Chasing gunship/similar that has gotten too far away
                        if iCurDistToTarget > iMaxDistToTargetBeforeAborting then
                            if bDebugMessages == true then LOG(sFunctionRef..': Aborting as target gotten too far away') end
                            break
                        elseif bUseStopMicro and iCurDistToTarget < iOurRange and oUnit[AiBotUnitInfo.refiLastWeaponEvent] and GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiLastWeaponEvent] <= 2 then
                            if not(bLastOrderWasStopOrder) then
                                AiBotOrders.IssueTrackedClearCommands(oUnit)
                                if bShowUnitOrdersInName then AiBotOrders.UpdateUnitNameForOrder(oUnit, 'StopMicro') end
                            end
                            bLastOrderWasStopOrder = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Cleared orders so can do stop micro') end
                        elseif not(bLastOrderWasStopOrder) or (iCurDistToTarget >= iMaxDistForStopMicro and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0) >= iMaxTimeBetweenShotsWanted) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will move to target') end
                            AiBotOrders.IssueTrackedMove(oUnit, tMoveViaPoint, iReorderDist, false, 'AAM2T', true)
                        elseif bDebugMessages == true then LOG(sFunctionRef..': Doing stop micro')
                        end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(1)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        --Select new target if are currently stopped and cur target is dead
                        if bDebugMessages == true then LOG(sFunctionRef..': Will select new target if currently stopped and cur target is dead, is oUnit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; Is oTarget valid='..tostring(AiBotUnitInfo.IsUnitValid(oTarget))..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Time='..GetGameTimeSeconds()) end
                        if AiBotUnitInfo.IsUnitValid(oUnit) and ((bUseStopMicro and bLastOrderWasStopOrder and not(AiBotUnitInfo.IsUnitValid(oTarget)))
                                or (AiBotUnitInfo.IsUnitValid(oTarget) and iOurMaxSpeed <= iEnemyMaxSpeed + 0.5 and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0) >= iMaxTimeBetweenShotsWanted and IsTargetRunningAway(oTarget, oUnit, iCurSpeed, iOurMaxSpeed, iTargetCurSpeed, iEnemyMaxSpeed, iOurRange, iCurFacingAngle))) then
                            oTarget = nil

                            local oAltTarget
                            local toNearbyEnemyAirAA = oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryAirAA * categories.TECH3, oUnit:GetPosition(), iMaxDistForStopMicro + 5, 'Enemy')
                            if AiBotUtilities.IsTableEmpty( toNearbyEnemyAirAA) == false then
                                local iClosestDist = iMaxDistForStopMicro
                                local iCurDist
                                for iEnemy, oEnemy in toNearbyEnemyAirAA do
                                    if not(oEnemy.Dead) then --redundancy
                                        iCurDist = VDist3(oUnit:GetPosition(), oEnemy:GetPosition())
                                        if iCurDist < iClosestDist and not(IsTargetRunningAway(oEnemy, oUnit, iCurSpeed, iOurMaxSpeed, iTargetCurSpeed, iEnemyMaxSpeed, iOurRange, iCurFacingAngle)) then
                                            oAltTarget = oEnemy
                                            iClosestDist = iCurDist
                                        end
                                    end
                                end
                            end
                            if AiBotUnitInfo.IsUnitValid(oAltTarget) then
                                oUnit[AiBotAir.refoAirAACurTarget] = oAltTarget
                                oTarget = oAltTarget
                                iEnemyMaxSpeed = oTarget:GetBlueprint().Air.MaxAirspeed
                            end
                        end
                    end

                    --Other code when doing testing for v307 as alternative to stop micro:
                    --[[iCurAngleToTarget = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oTarget:GetPosition())
                    iCurFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oUnit)
                    iCurAngleDif = AiBotUtilities.GetAngleDifference(iCurAngleToTarget, iCurFacingAngle)
                    if bDebugMessages == true then LOG(sFunctionRef..': start of loop, iCurDistToTarget='..iCurDistToTarget..'; iCurANgleToTarget='..iCurANgleToTarget..'; iCurFacingANgle='..iCurFacingAngle..'; iCurAngleDif='..iCurAngleDif..'; TIme='..GetGameTimeSeconds()) end
                    if iCurAngleToTarget > iCurFacingAngle then
                        if iCurAngleToTarget - iCurFacingAngle > 180 then
                            --Clockwise means increasing our cur facing angle; however if gap between the angles is more than 180 would be better to decrease our facing angle
                            bTurnClockwise = false
                        else
                            bTurnClockwise = true
                        end
                    else --curfacingangle is >= angle to target
                        if iCurFacingAngle - iCurAngleToTarget > 180 then
                            --Gap between the two is so large, that increasing our facing angle should get us to the target quicker
                            bTurnClockwise = true
                        else
                            bTurnClockwise = false
                        end
                    end

                    iAngleToMove = math.min(iMaxAngleToTryAndTurn, iCurAngleDif)
                    if not(bTurnClockwise) then iAngleToMove = -iAngleToMove end
                    iReorderDist = 0.1

                    tMoveViaPoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iCurFacingAngle + iAngleToMove, iDistToMoveTowardsTarget, true, false, false)
                    tMoveViaPoint = oTarget:GetPosition()
                    AiBotOrders.IssueTrackedMove(oUnit, tMoveViaPoint, iReorderDist, false, 'NAAHvM', true)--]]

                    --else
                    --Old code from v306 and earlier - per v307 notes compared this to new logic and alternatives and it was significantly worse
                    --First decide if we want to move towards target
                    --[[iCurDistToTarget = VDist3(oUnit:GetPosition(), oTarget:GetPosition())

                    if bDebugMessages == true then LOG(sFunctionRef..': iCurDistToTarget (using vdist3)='..iCurDistToTarget..'; Straightline dist='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oTarget:GetPosition())..'; our speed='..AiBotUnitInfo.GetUnitSpeed(oUnit)..'; Time='..GetGameTimeSeconds()) end
                    if iCurDistToTarget > iMinDistToTarget then
                        if iCurDistToTarget > iMaxDistToConsiderHoverTurn then
                            tMoveViaPoint = oTarget:GetPosition()
                            iReorderDist = 0.5
                            if bDebugMessages == true then LOG(sFunctionRef..': Too far from target so want to move to target, iCurDistToTarget='..iCurDistToTarget..'; Target unit state='..AiBotUnitInfo.GetUnitState(oTarget)) end
                        else
                            iCurAngleToTarget = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oTarget:GetPosition())
                            iCurFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oUnit)
                            iCurAngleDif = AiBotUtilities.GetAngleDifference(iCurAngleToTarget, iCurFacingAngle)
                            iDistToMoveTowardsTarget = 15
                            if iCurAngleDif >= iMaxAngleToTryAndTurn * 2 then
                                --Want to try and hover-turn
                                if iCurAngleToTarget > iCurFacingAngle then
                                    if iCurAngleToTarget - iCurFacingAngle > 180 then
                                        --Clockwise means increasing our cur facing angle; however if gap between the angles is more than 180 would be better to decrease our facing angle
                                        bTurnClockwise = false
                                    else
                                        bTurnClockwise = true
                                    end
                                else --curfacingangle is >= angle to target
                                    if iCurFacingAngle - iCurAngleToTarget > 180 then
                                        --Gap between the two is so large, that increasing our facing angle should get us to the target quicker
                                        bTurnClockwise = true
                                    else
                                        bTurnClockwise = false
                                    end
                                end
                                iAngleToMove = iMaxAngleToTryAndTurn
                                if bTurnClockwise then
                                    tMoveViaPoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iCurFacingAngle + iAngleToMove, iDistToMoveTowardsTarget, true, false, false)
                                else
                                    tMoveViaPoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iCurFacingAngle - iAngleToMove, iDistToMoveTowardsTarget, true, false, false)
                                end
                                tMoveViaPoint[2] = oTarget:GetPosition()[2]
                                if bDebugMessages == true then LOG(sFunctionRef..': Relatively far away and at a bad angle so will try hover-turning') end
                            else
                                tMoveViaPoint = oTarget:GetPosition()
                                iReorderDist = 0.5
                                if bDebugMessages == true then LOG(sFunctionRef..': Relatively far from target but at a reasonably similar angle so want to move to target, iCurDistToTarget='..iCurDistToTarget..'; Target unit state='..AiBotUnitInfo.GetUnitState(oTarget)) end
                            end
                        end
                    else
                        --Move towards target
                        --Check target is in the air not on the ground (if on the ground then want to issue manual attack order)
                        bManualAttack = false
                        if not(oTarget:IsUnitState('Moving') or oTarget:IsUnitState('Attacking')) then
                            local tCurTargetPosition = oTarget:GetPosition()
                            if bDebugMessages == true then LOG(sFunctionRef..': Consideringi f want manual attack, target vertical dist from surface='..tCurTargetPosition[2] - GetSurfaceHeight(tCurTargetPosition[1], tCurTargetPosition[3])) end
                            if tCurTargetPosition[2] - GetSurfaceHeight(tCurTargetPosition[1], tCurTargetPosition[3]) <= 1 then
                                bManualAttack = true
                            end
                        end
                        if bManualAttack then
                            if bDebugMessages == true then LOG(sFunctionRef..': Target appears to be on ground so will do manual attack') end
                            tMoveViaPoint = nil
                        else
                            iCurAngleToTarget = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oTarget:GetPosition())
                            iCurFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oUnit)
                            iCurAngleDif = AiBotUtilities.GetAngleDifference(iCurAngleToTarget, iCurFacingAngle)
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurDistToTarget='..iCurDistToTarget..'; iCurAngleToTarget='..iCurAngleToTarget..'; iCurFacingAngle='..iCurFacingAngle..'; iCurAngleDif='..iCurAngleDif..'; Target unit state='..AiBotUnitInfo.GetUnitState(oTarget)..'; Dist from ground='..(oTarget:GetPosition()[2] - GetSurfaceHeight(oTarget:GetPosition()[1], oTarget:GetPosition()[3]))..'; Time since last fired weapon='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0)) end
                            if iCurAngleDif > iMaxAngleToTryAndTurn then
                                iReorderDist = 0.1
                                --Turn towards target - decide which is closest way

                                if iCurAngleToTarget > iCurFacingAngle then
                                    if iCurAngleToTarget - iCurFacingAngle > 180 then
                                        --Clockwise means increasing our cur facing angle; however if gap between the angles is more than 180 would be better to decrease our facing angle
                                        bTurnClockwise = false
                                    else
                                        bTurnClockwise = true
                                    end
                                else --curfacingangle is >= angle to target
                                    if iCurFacingAngle - iCurAngleToTarget > 180 then
                                        --Gap between the two is so large, that increasing our facing angle should get us to the target quicker
                                        bTurnClockwise = true
                                    else
                                        bTurnClockwise = false
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Will turn towards target, bTurnClockwise='..tostring(bTurnClockwise)) end

                                if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0) > iMaxTimeBetweenShotsWanted then
                                    if iCurDistToTarget >= 10 then
                                        iDistToMoveTowardsTarget = math.max(2, iCurDistToTarget * 0.3)
                                    else
                                        bManualAttack = true --issues with asfs not turning properly when facing a target when they have got too close, so if we are close to a taret and facing the wrong direction, will switch to a manual attack
                                    end
                                    iAngleToMove = iMaxAngleToTryAndTurn
                                else
                                    iDistToMoveTowardsTarget = 0.1
                                    iAngleToMove = iMaxAngleToTryAndTurn
                                end
                                if bManualAttack then
                                    tMoveViaPoint = nil
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will switch to manual attack as been a while since we have moved') end
                                else
                                    iCurSpeed = AiBotUnitInfo.GetUnitSpeed(oUnit)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering adjusting iDistToMoveTowardsTarget if moving slowly, iCurSpeed='..iCurSpeed..'; iDistToMoveTowardsTarget before adjust='..iDistToMoveTowardsTarget..'; iCurDistToTarget='..iCurDistToTarget) end
                                    if iCurSpeed <= 1.5 and iDistToMoveTowardsTarget < 10 and iCurDistToTarget > iDistToMoveTowardsTarget then
                                        if iCurSpeed <= 0.5 then iDistToMoveTowardsTarget = math.max(iDistToMoveTowardsTarget, math.min(10, iCurDistToTarget))
                                        else iDistToMoveTowardsTarget = math.max(iDistToMoveTowardsTarget, math.min(10, 10 * (1.5 - iCurSpeed), iCurDistToTarget)) --/1 (/1 is unnecessary, i.e. doesnt change things, so left out for simplicity)
                                        end
                                    end

                                    iDistToMoveTowardsTarget = iTempMoveLimit
                                    if bTurnClockwise then
                                        tMoveViaPoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iCurFacingAngle + iAngleToMove, iDistToMoveTowardsTarget, true, false, false)
                                    else
                                        tMoveViaPoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iCurFacingAngle - iAngleToMove, iDistToMoveTowardsTarget, true, false, false)
                                    end
                                    tMoveViaPoint[2] = oTarget:GetPosition()[2]
                                    if bDebugMessages == true then
                                        LOG(sFunctionRef..': Dist to tMoveViaPoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tMoveViaPoint)..'; Angle='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tMoveViaPoint)..'; Time between shots='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; iMaxTimeBetweenShotsWanted='..iMaxTimeBetweenShotsWanted..'; iDistToMoveTowardsTarget='..iDistToMoveTowardsTarget)
                                        AiBotUtilities.DrawLocation(oUnit:GetPosition(), 2)
                                        AiBotUtilities.DrawLocation(tMoveViaPoint, 1)
                                    end
                                end
                            elseif bEnemyIsCloseToOurSpeed and iCurDistToTarget + 2 >= oUnit[AiBotUnitInfo.refiAARange] then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will try and move to target since are almost out of range and enemy is similar speed to us') end
                                tMoveViaPoint = oTarget:GetPosition()

                            elseif iCurDistToTarget < iHalfDistThreshold then
                                --Move a fraction of the way towards target
                                iReorderDist = 0.1
                                tMoveViaPoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iCurAngleToTarget, 0.1, true, false, false)
                                if bDebugMessages == true then LOG(sFunctionRef..': Will move towards unti by 0.1 distance but with the correct angle') end
                            else
                                --Move 25% towards target
                                iReorderDist = math.min(iCurDistToTarget * 0.25, iCurDistToTarget - iHalfDistThreshold)

                                tMoveViaPoint = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iCurAngleToTarget, iReorderDist, true, false, false)
                                if iReorderDist > 5 then iReorderDist = 5 end
                                if bDebugMessages == true then LOG(sFunctionRef..': will move 25% of the way towards the target') end
                            end
                        end
                    end
                    iReorderDist = nil
                    if bDebugMessages == true then LOG(sFunctionRef..': Unit cur position='..repru(oUnit:GetPosition())..'; tMoveViaPoint='..repru(tMoveViaPoint)..'; Time='..GetGameTimeSeconds()..'; Time since last weapon event='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0)) end
                    if tMoveViaPoint then
                        AiBotOrders.IssueTrackedMove(oUnit, tMoveViaPoint, iReorderDist, false, 'AAHvM', true)
                    elseif bManualAttack then
                        --LOUD - abort as cant actually target air units on the ground
                        if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then break end
                        AiBotOrders.IssueTrackedAttack(oUnit, oTarget, false, 'AMAHvM', true)
                    else
                        AiBotUtilities.ErrorHandler('Made mistake have nil move via point')
                    end
                    --Abort if enemy same speed as us and out of our range
                    if bEnemyIsCloseToOurSpeed and iCurDistToTarget > iOurRange and (iCurDistToTarget > iOurRange + 15 or iEnemyMaxSpeed >= iOurMaxSpeed or not(EntityCategoryContains(AiBotUnitInfo.refCategoryTransport, oTarget.UnitId)) or not(oTarget.GetCargo) or AiBotUtilities.IsTableEmpty(oTarget:GetCargo())) then
                        if bDebugMessages == true then LOG(sFunctionRef..': enemy is similar speed and outside our range so will abort the loop') end
                        break
                    end
                end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(1)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    end
                    --]]
                    if bDebugMessages == true then LOG(sFunctionRef..': Turning off special micro6') end
                    oUnit[AiBotUnitInfo.refbSpecialMicroActive] = false
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function T1OrT3HoverBombTarget(oBomber, oTarget, bDontAdjustMicroFlag, bContinueAttackingUntilTargetDead, bAbortForGroundAAUnlessTargetIsEngineer, bAbortOnceDroppedBomb)
    --Based on combination of ahwassa approach and hoverAA approach
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'T1OrT3HoverBombTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..'; bDontAdjustMicroFlag='..tostring(bDontAdjustMicroFlag or false)..'; bContinueAttackingUntilTargetDead='..tostring(bContinueAttackingUntilTargetDead or false)..'; bAbortForGroundAAUnlessTargetIsEngineer='..tostring(bAbortForGroundAAUnlessTargetIsEngineer or false)..'; refbSpecialMicroActive='..tostring((oBomber[AiBotUnitInfo.refbSpecialMicroActive] or false))..'; GameTime='..GetGameTimeSeconds()) end
    if AiBotUnitInfo.IsUnitValid(oBomber) and AiBotUnitInfo.IsUnitValid(oTarget) and (not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) or oBomber[AiBotUnitInfo.refbLowerPriorityMicroActive]) then
        local iStartTime = GetGameTimeSeconds()
        local iCurAngleDif
        local iMaxMicroTime = 10 --v249 - t1 bomber hover-bombing didnt have enough time to attack the target with 5s so switched to 10s (prev was 5s for non-experimental and 10s for experiemntal)
        if bContinueAttackingUntilTargetDead then iMaxMicroTime = 60 end

        if not(bDontAdjustMicroFlag) then
            TrackTemporaryUnitMicro(oBomber, iMaxMicroTime)
            if bDebugMessages == true then LOG(sFunctionRef..': Will track temporary unit micro for '..iMaxMicroTime..' or until this logic ends') end
        end --60s is redundancy
        local iMaxTimeBetweenShotsWanted = oBomber[AiBotUnitInfo.refiTimeBetweenBombs]
        local iCurAngleToTarget, iCurFacingAngle, iReorderDist, iCurDistToTarget, bTurnClockwise, iDistToMoveTowardsTarget, bManualAttack, iAngleToMove, tMoveViaPoint
        local iHalfDistThreshold = (oBomber[AiBotUnitInfo.refiBomberRange] or 40) * 0.5
        local iQuarterDistThreshold = (oBomber[AiBotUnitInfo.refiBomberRange] or 40) * 0.25
        local iFastSpeedDistThreshold = (oBomber[AiBotUnitInfo.refiBomberRange] or 40) * 0.8
        local iFastSpeedThreshold = 10 --if going faster than this and below the fastspeedistthreshold then will try and slow down
        local iFurthestDistWhenAtCorrectAngle, iSlowestSpeedWhenAtCorrectAngle
        if iQuarterDistThreshold <= 15 then iQuarterDistThreshold = math.max(iHalfDistThreshold * 0.8, math.min(iHalfDistThreshold, 16)) end
        local iMinTimeAfterFiringBeforeGivingNewOrders = 0
        if AiBotUnitInfo.DoesBomberFireSalvo(oBomber) then iMinTimeAfterFiringBeforeGivingNewOrders = 1.1 end
        local iTeam = oBomber:GetAIBrain().AiBotTeam
        local bAbortForGroundAA = (bAbortForGroundAAUnlessTargetIsEngineer and not(EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oTarget.UnitId)))
        local iBomberSpeed
        local iTimeSinceLastFiredBomb
        if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop, bAbortForGroundAA='..tostring(bAbortForGroundAA or false)..'; iStartTime='..iStartTime..'; Cur time='..GetGameTimeSeconds()..'; iMaxMicroTime='..iMaxMicroTime..'; Is bomber valid='..tostring(AiBotUnitInfo.IsUnitValid(oBomber) )..'; Is target valid='..tostring(AiBotUnitInfo.IsUnitValid(oTarget))..'; iMinTimeAfterFiringBeforeGivingNewOrders='..(iMinTimeAfterFiringBeforeGivingNewOrders or 'nil')..'; Does bomber fire salv='..tostring(AiBotUnitInfo.DoesBomberFireSalvo(oBomber) or false)) end
        local bAiBotEasyOrNotFAF = (oBomber[AiBotUnitInfo.refbEasyBrain] and not(EntityCategoryContains(categories.EXPERIMENTAL, oBomber.UnitId))) or not(AiBotUtilities.bFAFActive)
        while GetGameTimeSeconds() - iStartTime < iMaxMicroTime and AiBotUnitInfo.IsUnitValid(oBomber) and AiBotUnitInfo.IsUnitValid(oTarget) do
            --Abort if recently dropped bomb and we think it will kill the target
            iTimeSinceLastFiredBomb = GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0)

            --If have recently fired then dont want to give orders if have a salvo
            if iMinTimeAfterFiringBeforeGivingNewOrders > 0 and iTimeSinceLastFiredBomb < iMinTimeAfterFiringBeforeGivingNewOrders then
                --Just wait, dont give orders, so all our bombs can drop
                if bDebugMessages == true then LOG(sFunctionRef..': Bomber fired recently so wont give new orders, time since last fired='..iTimeSinceLastFiredBomb) end
            elseif bAbortOnceDroppedBomb and iTimeSinceLastFiredBomb <= 0.2 and GetGameTimeSeconds() - iStartTime > 0.2 then
                if bDebugMessages == true then LOG(sFunctionRef..': Aborting as we have recently dropped a bomb, iTimeSinceLastFiredBomb='..iTimeSinceLastFiredBomb) end
                break
            else
                --Do we want to abort  micro?
                if bAbortForGroundAA then
                    local tTargetLZData, tTargetLZTeamData = AiBotMap.GetLandOrWaterZoneData(oTarget:GetPosition(), true, iTeam)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to abort due to enemy groundAA='..tTargetLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]..'; Does the zone have too much AA for base bomber='..tostring(AiBotConditions.EnemyZoneHasTooMuchAAForBaseBomber(tTargetLZTeamData, tTargetLZData, oBomber) or false)) end
                    if AiBotConditions.EnemyZoneHasTooMuchAAForBaseBomber(tTargetLZTeamData, tTargetLZData, oBomber) then
                        --Return to nearest base
                        if oBomber[AiBotAir.rebEarlyBomberTargetBase] then oBomber[AiBotAir.rebEarlyBomberTargetBase] = false end
                        AiBotOrders.IssueTrackedMove(oBomber, tTargetLZTeamData[AiBotMap.reftClosestFriendlyBase], 5, false, 'AbortHBM', true)
                        break
                    end
                end
                if bAiBotEasyOrNotFAF then
                    bManualAttack = true
                else
                    iCurDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), oTarget:GetPosition())
                    iCurAngleToTarget = AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oTarget:GetPosition())
                    iCurFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oBomber)
                    iCurAngleDif = AiBotUtilities.GetAngleDifference(iCurAngleToTarget, iCurFacingAngle)
                    iBomberSpeed = AiBotUnitInfo.GetUnitSpeed(oBomber)
                    bManualAttack = false

                    --Are we facing the target? if not, then turn towards them
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurDistToTarget='..iCurDistToTarget..'; iCurAngleToTarget='..iCurAngleToTarget..'; iCurFacingAngle='..iCurFacingAngle..'; iCurAngleDif='..iCurAngleDif..'; Target unit state='..AiBotUnitInfo.GetUnitState(oTarget)..'; Dist from ground='..(oTarget:GetPosition()[2] - GetSurfaceHeight(oTarget:GetPosition()[1], oTarget:GetPosition()[3]))..'; Time since last fired weapon='..GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; time since last fired bomb='..(GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0))..'; oBomber[AiBotUnitInfo.refiTimeBetweenBombs]='..(oBomber[AiBotUnitInfo.refiTimeBetweenBombs] or 'nil')..'; iHalfDistThreshold='..iHalfDistThreshold) end
                    if iCurAngleDif > 15 then
                        if iBomberSpeed <= 0.1 and iCurDistToTarget > iQuarterDistThreshold and (iBomberSpeed <= 0.05 or iCurDistToTarget >= iHalfDistThreshold) then
                            iReorderDist = 1
                        else
                            iReorderDist = 0.1
                        end
                        --Turn towards target - decide which is closest way

                        if iCurAngleToTarget > iCurFacingAngle then
                            if iCurAngleToTarget - iCurFacingAngle > 180 then
                                --Clockwise means increasing our cur facing angle; however if gap between the angles is more than 180 would be better to decrease our facing angle
                                bTurnClockwise = false
                            else
                                bTurnClockwise = true
                            end
                        else --curfacingangle is >= angle to target
                            if iCurFacingAngle - iCurAngleToTarget > 180 then
                                --Gap between the two is so large, that increasing our facing angle should get us to the target quicker
                                bTurnClockwise = true
                            else
                                bTurnClockwise = false
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Will turn towards target, bTurnClockwise='..tostring(bTurnClockwise)) end

                        if iTimeSinceLastFiredBomb > iMaxTimeBetweenShotsWanted then
                            if iCurDistToTarget >= 10 then
                                iDistToMoveTowardsTarget = math.max(2, iCurDistToTarget * 0.3)
                                if bDebugMessages == true then LOG(sFunctionRef..': Will move 30% towards target') end
                            else
                                bManualAttack = true --issues with asfs not turning properly when facing a target when they have got too close, so if we are close to a taret and facing the wrong direction, will switch to a manual attack
                            end
                            iAngleToMove = 15
                        elseif (iCurDistToTarget >= 30 and iCurAngleDif <= 60 and iBomberSpeed <= 5) and (iCurDistToTarget >= 60 or (oBomber[AiBotUnitInfo.refiLastBombFired] and iMaxTimeBetweenShotsWanted - iTimeSinceLastFiredBomb  <= 2)) then
                            iDistToMoveTowardsTarget = 10
                            iAngleToMove = 15
                        else
                            iDistToMoveTowardsTarget = 0.1
                            iAngleToMove = 15
                        end
                        if bManualAttack then
                            tMoveViaPoint = nil
                            if bDebugMessages == true then LOG(sFunctionRef..': Will switch to manual attack as been a while since we have moved') end
                        else
                            if bTurnClockwise then
                                tMoveViaPoint = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iCurFacingAngle + iAngleToMove, iDistToMoveTowardsTarget, true, false, false)
                            else
                                tMoveViaPoint = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iCurFacingAngle - iAngleToMove, iDistToMoveTowardsTarget, true, false, false)
                            end
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': Dist to tMoveViaPoint='..AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tMoveViaPoint)..'; Angle='..AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tMoveViaPoint)..'; Time between shots='..GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; iMaxTimeBetweenShotsWanted='..iMaxTimeBetweenShotsWanted..'; iDistToMoveTowardsTarget='..iDistToMoveTowardsTarget)
                                --AiBotUtilities.DrawLocation(oBomber:GetPosition(), 2)
                                --AiBotUtilities.DrawLocation(tMoveViaPoint, 1)
                            end
                        end
                        --We are facing the target, if we are able to fire then drop a bomb, otherwise slowly approach
                    elseif GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0) > iMaxTimeBetweenShotsWanted then
                        --Are facing the right direction and able to fire
                        --First time we are at the right angle - consider slowing down slightly if we dont have that far to reach target and are going quite fast
                        if not(iFurthestDistWhenAtCorrectAngle) then iFurthestDistWhenAtCorrectAngle = iCurDistToTarget end
                        iSlowestSpeedWhenAtCorrectAngle = math.min((iSlowestSpeedWhenAtCorrectAngle or 100), iBomberSpeed)
                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy at right angle, and we should be able to fire bomb, so switching to manual attack unless want to slow down, iFurthestDistWhenAtCorrectAngle='..iFurthestDistWhenAtCorrectAngle..'; iFastSpeedDistThreshold='..iFastSpeedDistThreshold..'; iSlowestSpeedWhenAtCorrectAngle='..iSlowestSpeedWhenAtCorrectAngle) end
                        if iFurthestDistWhenAtCorrectAngle < iFastSpeedDistThreshold and iSlowestSpeedWhenAtCorrectAngle > iFastSpeedThreshold then
                            --Want to slow down
                            iReorderDist = 0.1
                            if iCurDistToTarget > iQuarterDistThreshold and iBomberSpeed <= 4 then iReorderDist = 4 end
                            tMoveViaPoint = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iCurAngleToTarget, iReorderDist, true, false, false)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will move towards unti by 0.1 distance, with the correct angle, to slow down') end
                        else
                            --if iBomberSpeed < iFastestSpeedWhenAtCorreectAngle
                            bManualAttack = true

                        end
                    else
                        --Facing the right direction but unable to fire, so move closer
                        if iCurDistToTarget > oBomber[AiBotUnitInfo.refiBomberRange] + 5 then
                            bManualAttack = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy at right angle, and outside bomber range, so will do manual attack') end
                        elseif iCurDistToTarget < iHalfDistThreshold then
                            --Move a fraction of the way towards target, unless we are greater than quarter dist and moving slow
                            iReorderDist = 0.1
                            if iCurDistToTarget > iQuarterDistThreshold and iBomberSpeed <= 4 then iReorderDist = 4 end
                            tMoveViaPoint = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iCurAngleToTarget, iReorderDist, true, false, false)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will move towards unti by 0.1 distance but with the correct angle') end
                        elseif iBomberSpeed <= 4 and (iCurDistToTarget >= 60 or (oBomber[AiBotUnitInfo.refiLastBombFired] and iMaxTimeBetweenShotsWanted - iTimeSinceLastFiredBomb  <= 2) or (iMaxTimeBetweenShotsWanted - iTimeSinceLastFiredBomb) <= 3 and iBomberSpeed <= 0.5) then
                            if bDebugMessages == true then LOG(sFunctionRef..': We are going slowly and cant yet fire our bomb so want to move to target and not reissue order if last order was to do the same') end
                            iReorderDist = math.min(iCurDistToTarget * 0.2, iCurDistToTarget - iHalfDistThreshold)
                            tMoveViaPoint = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iCurAngleToTarget, iReorderDist, true, false, false)
                        else
                            --Move 25% towards target
                            iReorderDist = math.min(iCurDistToTarget * 0.25, iCurDistToTarget - iHalfDistThreshold)
                            tMoveViaPoint = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iCurAngleToTarget, iReorderDist, true, false, false)
                            if iReorderDist > 5 then iReorderDist = 5 end
                            if bDebugMessages == true then LOG(sFunctionRef..': will move 25% of the way towards the target') end
                        end
                    end
                end
                if bManualAttack then
                    if bDebugMessages == true then LOG(sFunctionRef..': Given order to attack oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)) end
                    AiBotOrders.IssueTrackedAttack(oBomber, oTarget, false, 'HoverBmA', true)
                elseif tMoveViaPoint then
                    if bDebugMessages == true then LOG(sFunctionRef..': Given order to move to via point, iReorderDist='..iReorderDist) end
                    AiBotOrders.IssueTrackedMove(oBomber, tMoveViaPoint, iReorderDist, false, 'HverBmM', true)
                else
                    AiBotUtilities.ErrorHandler('Made mistake have nil move via point')
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': end of loop, will repeat unless have reached max microing time, Time='..GetGameTimeSeconds()..'; iMaxMicroTime is '..iMaxMicroTime..'; Time spent so far='..GetGameTimeSeconds() - iStartTime..'; Bomber speed='..iBomberSpeed..'; oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)) end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        if oBomber[AiBotUnitInfo.refbSpecialMicroActive] and not(bDontAdjustMicroFlag) then
            if bDebugMessages == true then LOG(sFunctionRef..': Turning off special micro8') end
            oBomber[AiBotUnitInfo.refbSpecialMicroActive] = false
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of hover bomb code, is bomber valid='..tostring(AiBotUnitInfo.IsUnitValid(oBomber))..'; Is target valid='..tostring(AiBotUnitInfo.IsUnitValid(oTarget))..'; Time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function SuicideExperimentalIntoEnemyACU(oUnit, oClosestACUNearUnit, iOrigDistFromEnemyACU)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SuicideExperimentalIntoEnemyACU'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; Time='..GetGameTimeSeconds()) end
    if AiBotUnitInfo.IsUnitValid(oUnit) and AiBotUnitInfo.IsUnitValid(oClosestACUNearUnit) and not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
        EnableUnitMicroUntilManuallyTurnOff(oUnit, false)
        --Set weapon prioritisation
        AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityExpSnipeACU, false)
        local iCurDist
        local bLastOrderWasManualAttack
        local bCheckForExperimentals = EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oUnit.UnitId) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0
        local iTeam = oUnit:GetAIBrain().AiBotTeam
        local iCurExpDist
        local iDistUntilInRangeOfACU

        if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop, oUnit (experimental)='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by brain '..oUnit:GetAIBrain().Nickname..'; oClosestACUNearUnit='..oClosestACUNearUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestACUNearUnit)..' owned by '..oClosestACUNearUnit:GetAIBrain().Nickname..'; Dist between them='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestACUNearUnit:GetPosition())..'; iOrigDistFromEnemyACU='..iOrigDistFromEnemyACU) end
        while AiBotUnitInfo.IsUnitValid(oUnit) and AiBotUnitInfo.IsUnitValid(oClosestACUNearUnit) and not(oClosestACUNearUnit:IsUnitState('Attached')) and not(AiBotUnitInfo.IsUnitUnderwater(oClosestACUNearUnit)) do
            --Move towards the ACU
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestACUNearUnit:GetPosition())
            iDistUntilInRangeOfACU = iCurDist - (oUnit[AiBotUnitInfo.refiDFRange] or 0)
            if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..'; iCurDist='..iCurDist..'; bLastOrderWasManualAttack='..tostring(bLastOrderWasManualAttack)..'; Will do attack move intead of manual attack this time='..tostring(iCurDist >= 8 or (iCurDist >= 5 and not(bLastOrderWasManualAttack)))..'; iDistUntilInRangeOfACU='..iDistUntilInRangeOfACU..'; Time='..GetGameTimeSeconds()) end
            if iCurDist >= 8 or (iCurDist >= 5 and not(bLastOrderWasManualAttack)) then
                --Check we dont have enemy experimental in our range that we should try and kill instead
                if iCurDist > iOrigDistFromEnemyACU and iCurDist > iOrigDistFromEnemyACU + 5 and iDistUntilInRangeOfACU >= 10 then --e.g. we switched to attack enemy exp and now the ACU is too far away to try and run down
                    if bDebugMessages == true then LOG(sFunctionRef..': ACU too far away from us now so will abort') end
                    break
                end
                local oEnemyExpToAttackInstead
                local iClosestEnemyExpToAttack = 1000
                if bCheckForExperimentals and iDistUntilInRangeOfACU >= 8 then
                    local tLZData = AiBotMap.tAllPlateaus[oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]][AiBotMap.subrefPlateauLandZones][oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]]
                    if tLZData then
                        local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                            local tEnemyExp = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental, tLZTeamData[AiBotMap.reftoNearestDFEnemies])
                            if AiBotUtilities.IsTableEmpty(tEnemyExp) == false then
                                for iEnemyExp, oEnemyExp in tEnemyExp do
                                    if not(oEnemyExp.Dead) and (oEnemyExp[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                                        iCurExpDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemyExp:GetPosition(), oUnit:GetPosition())
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want t o attack enemy experimental instead, iCurExpDist='..iCurExpDist..'; Our DF range='..oUnit[AiBotUnitInfo.refiDFRange]..'; Enemy Exp DF range='..oEnemyExp[AiBotUnitInfo.refiDFRange]..'; oEnemyExp='..oEnemyExp.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyExp)) end
                                        if iCurExpDist <= oUnit[AiBotUnitInfo.refiDFRange] or (oEnemyExp[AiBotUnitInfo.refiDFRange] > oUnit[AiBotUnitInfo.refiDFRange] and iCurExpDist < oEnemyExp[AiBotUnitInfo.refiDFRange] and iCurExpDist <= oUnit[AiBotUnitInfo.refiDFRange] + iDistUntilInRangeOfACU - 12) then
                                            if iCurExpDist < iClosestEnemyExpToAttack or (iCurExpDist < oUnit[AiBotUnitInfo.refiDFRange] and oEnemyExpToAttackInstead and AiBotUnitInfo.GetUnitHealthPercent(oEnemyExp) < AiBotUnitInfo.GetUnitHealthPercent(oEnemyExpToAttackInstead)) then
                                                oEnemyExpToAttackInstead = oEnemyExp
                                                iClosestEnemyExpToAttack = iCurExpDist
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                if oEnemyExpToAttackInstead then
                    AiBotOrders.IssueTrackedAttack(oUnit, oEnemyExpToAttackInstead, false, 'ExpKACUEA', true)
                else
                    AiBotOrders.IssueTrackedMove(oUnit, oClosestACUNearUnit:GetPosition(), 0.5, false, 'ExpKACUM', true)
                    bLastOrderWasManualAttack = false
                end
            else
                --Manual attack
                bLastOrderWasManualAttack = true
                AiBotOrders.IssueTrackedAttack(oUnit, oClosestACUNearUnit, false, 'ExpKACUA', true)
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        if AiBotUnitInfo.IsUnitValid(oUnit) then
            oUnit[AiBotUnitInfo.refbSpecialMicroActive] = false
            --Use megalith weapon prioritisation as a proxy for what we are likely to want
            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityMegalith, false)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderAllInLandPushOnACU(aiBrain, oACU)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderAllInLandPushOnACU'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --Separate to the snipe logic, this instead considers if we have enough threat in the vicinity to do an all-in push with just our tanks
    if AiBotUnitInfo.IsUnitValid(oACU) and not(aiBrain.AiBotIsDefeated) then
        local iEnemyACUThreat = AiBotUnitInfo.GetCombatThreatRating({ oACU}, true)
        if bDebugMessages == true then LOG(sFunctionRef..': iEnemyACUThreat='..iEnemyACUThreat..'; ACU owner='..oACU:GetAIBrain().Nickname..'; our brain='..aiBrain.Nickname..'; Time='..GetGameTimeSeconds()) end
        if iEnemyACUThreat <= 3000 then
            local tNearbyFriendlyTanks = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileDFLand - AiBotUnitInfo.refCategorySkirmisher - categories.COMMAND, oACU:GetPosition(), 60, 'Ally')
            if AiBotUtilities.IsTableEmpty(tNearbyFriendlyTanks) == false then
                local iFriendlyTankThreat = AiBotUnitInfo.GetCombatThreatRating(tNearbyFriendlyTanks, false)
                if bDebugMessages == true then LOG(sFunctionRef..': iFriendlyTankThreat='..iFriendlyTankThreat) end
                if iFriendlyTankThreat > math.max(800, iEnemyACUThreat + math.max(400, iEnemyACUThreat * 0.4)) then --Min wanted for an unupgraded enemy ACU
                    local tEnemyThreat = oACU:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileDFLand + AiBotUnitInfo.refCategoryPD  - AiBotUnitInfo.refCategorySkirmisher + categories.COMMAND, oACU:GetPosition(), 90, 'Ally')
                    local iEnemyTotalThreat = AiBotUnitInfo.GetCombatThreatRating(tEnemyThreat, true)
                    if bDebugMessages == true then LOG(sFunctionRef..': iEnemyTotalThreat='..iEnemyTotalThreat) end
                    if iFriendlyTankThreat > iEnemyTotalThreat then
                        --Doublecheck the threat incase we have lost intel of the units near the ACU
                        local iTeam = aiBrain.AiBotTeam
                        if oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] then
                            local iACUPlateau = oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
                            local iACULandZone = oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                            local tACULZData = AiBotMap.tAllPlateaus[iACUPlateau][AiBotMap.subrefPlateauLandZones][iACULandZone]
                            local tACULZTeamData = tACULZData[AiBotMap.subrefLZTeamData][iTeam]
                            local toNearbyEnemies = {}
                            if AiBotUtilities.IsTableEmpty( tACULZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                for iEnemy, oEnemy in tACULZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                    if not(oEnemy.Dead) and oEnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iACULandZone and AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oACU:GetPosition()) - oEnemy[AiBotUnitInfo.refiDFRange] <= 60 then
                                        table.insert(toNearbyEnemies, oEnemy)
                                    end
                                end
                            end
                            if AiBotUtilities.IsTableEmpty(tACULZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for _, iAdjLZ in tACULZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    local tAdjLZData = AiBotMap.tAllPlateaus[iACUPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                    local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if AiBotUtilities.IsTableEmpty( tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                        for iEnemy, oEnemy in tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                            if not(oEnemy.Dead) and oEnemy[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iACULandZone and AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oACU:GetPosition()) - (oEnemy[AiBotUnitInfo.refiDFRange] or 0) <= 60 then
                                                table.insert(toNearbyEnemies, oEnemy)
                                            end
                                        end
                                    end
                                end
                            end
                            if AiBotUtilities.IsTableEmpty(toNearbyEnemies) == false then
                                local iEnemyNearbyThreat = AiBotUnitInfo.GetCombatThreatRating(toNearbyEnemies, true)
                                if iEnemyNearbyThreat > iEnemyTotalThreat then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Going on our memory the enemy has a larger threat than getunitsaroundpoint would indicate, iEnemyTotalThreat before update='..iEnemyTotalThreat..'; iEnemyNearbyThreat='..iEnemyNearbyThreat) end
                                    iEnemyTotalThreat = iEnemyNearbyThreat
                                end
                            end
                            if iFriendlyTankThreat > iEnemyTotalThreat then
                                --Suicide all the tanks into the ACU
                                if bDebugMessages == true then LOG(sFunctionRef..': Will suicide tanks into enemy ACU') end
                                AssignACUAttackGridSlot(tNearbyFriendlyTanks, oACU)
                                for iUnit, oUnit in tNearbyFriendlyTanks do
                                    if not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
                                        ForkThread(MoveLandUnitNearACU, oUnit, oACU)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will send unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to suicide into enemy ACU') end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MoveLandUnitNearACU(oUnit, oACU)
    --If we are on the same island/plateau as the ACU then will move towards it, switching to attack-move once close
    if AiBotUnitInfo.IsUnitValid(oUnit) and AiBotUnitInfo.IsUnitValid(oACU) then
        TrackTemporaryUnitMicro(oUnit, 0, nil, true) --i.e. still want to dodge t1 arti shots
        local sPathingRef
        if EntityCategoryContains(categories.HOVER, oUnit.UnitId) then sPathingRef = AiBotMap.refPathingTypeHover
        elseif (oUnit[AiBotUnitInfo.refiAntiNavyRange] or 0) > 0 then sPathingRef = AiBotMap.refPathingTypeAmphibious
        else sPathingRef = AiBotMap.refPathingTypeLand
        end
        local iNavUtilsWanted = NavUtils.GetLabel(sPathingRef, oUnit:GetPosition())
        if NavUtils.GetLabel(sPathingRef, oACU:GetPosition()) == iNavUtilsWanted then
            --Focus down ACU
            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityExpSnipeACU, false)
            local tMovePosition
            local iXOffset
            local iZOffset
            if oUnit[AiBotUnitInfo.refiACUGridSlot] and oACU[AiBotUnitInfo.reftoGridXZAdjust][oUnit[AiBotUnitInfo.refiACUGridSlot]] then
                iXOffset = oACU[AiBotUnitInfo.reftoGridXZAdjust][oUnit[AiBotUnitInfo.refiACUGridSlot]][1]
                iZOffset = oACU[AiBotUnitInfo.reftoGridXZAdjust][oUnit[AiBotUnitInfo.refiACUGridSlot]][2]
            else
                iXOffset = 0
                iZOffset = 0
                AiBotUtilities.ErrorHandler('Dont have a valid ACU grid slot assigned')
            end

            local bConsiderAttackMove = false
            if oUnit[AiBotUnitInfo.refiCombatRange] > (oACU[AiBotUnitInfo.refiDFRange] or 0) + 2 and (oUnit.UnitId == 'ual0201' or EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher, oUnit.UnitId)) then bConsiderAttackMove = true end
            local aiBrain = oUnit:GetAIBrain()

            while AiBotUnitInfo.IsUnitValid(oUnit) and AiBotUnitInfo.IsUnitValid(oACU) and not(oACU:IsUnitState('Attached')) and NavUtils.GetLabel(sPathingRef, oACU:GetPosition()) == iNavUtilsWanted do
                tMovePosition = oACU:GetPosition()
                tMovePosition[1] = tMovePosition[1] + iXOffset
                tMovePosition[3] = tMovePosition[3] + iZOffset
                tMovePosition[2] = GetSurfaceHeight(tMovePosition[1], tMovePosition[3])
                if AiBotUtilities.IsTableEmpty(tMovePosition) or not(NavUtils.GetLabel(sPathingRef, tMovePosition) == iNavUtilsWanted) then
                    tMovePosition = oACU:GetPosition()
                end
                if bConsiderAttackMove and AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) <= oUnit[AiBotUnitInfo.refiDFRange] - 1 then
                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tMovePosition, 3, false, 'ACUAllInAM', true)
                else
                    AiBotOrders.IssueTrackedMove(oUnit, tMovePosition, 3, false, 'ACUAllInM', true)
                end
                WaitSeconds(1)
            end
            if AiBotUnitInfo.IsUnitValid(oUnit) then
                oUnit[AiBotUnitInfo.refbSpecialMicroActive] = false
                oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds()
            end
        end
    end
end

function AssignACUAttackGridSlot(tUnits, oACU)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssignACUAttackGridSlot'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --First setup the grid slots for the ACU - for now will just do the same every time, but in theory could adjust these baesd on the size of tUnits

    local iMaxGridSize = 64 --8x8
    if not(oACU[AiBotUnitInfo.reftoGridXZAdjust]) then
        oACU[AiBotUnitInfo.reftoUnitAssignedToGridSlot] = {}
        oACU[AiBotUnitInfo.reftoGridXZAdjust] = {}
        local iSpacingBetweenPositions = 3 --so for an 8x8 grid this means a radius of 12
        local iCurSlot = 1
        local iCycleLength = 1
        local iCurX = 0
        local iCurZ = 0
        local iXAdj = 0
        local iPrevXAdj = iSpacingBetweenPositions
        local iZAdj = iSpacingBetweenPositions
        local iPrevZAdj = -iSpacingBetweenPositions
        local iTimeOfXAdjust = 0
        local iTimeOfZAdjust = 0
        local iSwitchCount = 0
        while iCurSlot <= iMaxGridSize do --i.e. an 8x8 grid around the ACU
            --Move in clockwise manner
            if iZAdj == 0 then
                iCurX = iCurX + iXAdj
                iTimeOfXAdjust = iTimeOfXAdjust + 1
                if iTimeOfXAdjust == iCycleLength then
                    iTimeOfXAdjust = 0
                    iPrevXAdj = iXAdj
                    iXAdj = 0
                    --Move up/down for Z now
                    iZAdj = iPrevZAdj * -1
                    iSwitchCount = iSwitchCount + 1
                end
            else
                --Presumably have iXAdj that is zero
                iCurZ = iCurZ + iZAdj
                iTimeOfZAdjust = iTimeOfZAdjust + 1
                if iTimeOfZAdjust == iCycleLength then
                    iTimeOfZAdjust = 0
                    iPrevZAdj = iZAdj
                    iZAdj = 0
                    --Move up/down for Z now
                    iXAdj = iPrevXAdj * -1
                    iSwitchCount = iSwitchCount + 1
                end
            end
            if iSwitchCount >= 2 then
                iCycleLength = iCycleLength + 1
                iSwitchCount = 0
            end
            oACU[AiBotUnitInfo.reftoGridXZAdjust][iCurSlot] = {iCurX, iCurZ}

            iCurSlot = iCurSlot + 1
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished recording, iMaxGridSize='..iMaxGridSize..'; iCurX and Z for this=X'..oACU[AiBotUnitInfo.reftoGridXZAdjust][iMaxGridSize][1]..'Z'..oACU[AiBotUnitInfo.reftoGridXZAdjust][iMaxGridSize][2]) end
    end

    local iUnitsWithoutAssignment = 0
    local toUnassignedUnits = {}
    local toUnassignedRefByDistance = {}
    for iUnit, oUnit in tUnits do
        if not(oUnit[AiBotUnitInfo.refiACUGridSlot]) then
            iUnitsWithoutAssignment = iUnitsWithoutAssignment + 1
            table.insert(toUnassignedUnits, oUnit)
            table.insert(toUnassignedRefByDistance, AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()))
        end
    end

    if iUnitsWithoutAssignment > 0 then
        --Check we have enough slots
        local iSlotsAvailable = 0
        local iSlotsWanted = math.max(30, iUnitsWithoutAssignment) --i.e. 8+8+7+7
        local iCurUnitCount = table.getn(tUnits)
        if bDebugMessages == true then LOG(sFunctionRef..': iCurUnitCount='..iCurUnitCount..'; Do we have a slot for this already? repru='..repru(oACU[AiBotUnitInfo.reftoGridXZAdjust][iCurUnitCount] or 'nil')) end

        --Record available slots
        local iCurSlot = 0
        local tiAvailableSlots = {}
        local iLastAvailableSlot
        while iSlotsAvailable < iSlotsWanted do
            iCurSlot = iCurSlot + 1
            if not(AiBotUnitInfo.IsUnitValid(oACU[AiBotUnitInfo.reftoUnitAssignedToGridSlot][iCurSlot])) then
                oACU[AiBotUnitInfo.reftoUnitAssignedToGridSlot][iCurSlot] = nil
                iSlotsAvailable = iSlotsAvailable + 1
                table.insert(tiAvailableSlots, iCurSlot)
                if bDebugMessages == true then LOG(sFunctionRef..': No valid unit is assigned to slot '..iCurSlot..' so will increase available slots by 1 to '..iSlotsAvailable) end
            end
            if not(oACU[AiBotUnitInfo.reftoGridXZAdjust][iCurSlot]) then
                iLastAvailableSlot = iCurSlot - 1
                break
            end
        end

        if iLastAvailableSlot then
            local iExtraSlotsWanted = iSlotsWanted - iLastAvailableSlot
            if iExtraSlotsWanted <= 0 then iExtraSlotsWanted= 1 end --redundancy
            local iRecordedSize = iMaxGridSize
            while oACU[AiBotUnitInfo.reftoGridXZAdjust][iRecordedSize] do
                iRecordedSize = iRecordedSize + iMaxGridSize
            end
            iRecordedSize = iRecordedSize - iMaxGridSize
            local iSizeToRecord = math.round(iExtraSlotsWanted / iMaxGridSize) * iMaxGridSize + iRecordedSize
            if bDebugMessages == true then LOG(sFunctionRef..': iRecordedSize by interval='..iRecordedSize..'; iSizeToRecord='..iSizeToRecord..'; iSlotsWanted='..iSlotsWanted..'; iLastAvailableSlot='..iLastAvailableSlot..'; iExtraSlotsWanted='..iExtraSlotsWanted) end
            for iCurSlot = iRecordedSize + 1, iSizeToRecord, 1 do
                oACU[AiBotUnitInfo.reftoGridXZAdjust][iCurSlot] = {oACU[AiBotUnitInfo.reftoGridXZAdjust][iCurSlot - iMaxGridSize][1], oACU[AiBotUnitInfo.reftoGridXZAdjust][iCurSlot - iMaxGridSize][2]}
                if iSlotsAvailable <= iSlotsWanted then
                    table.insert(tiAvailableSlots, iCurSlot)
                    iSlotsAvailable = iSlotsAvailable + 1
                    if bDebugMessages == true then LOG(sFunctionRef..': Recording new slot as available, iCurSLot='..iCurSlot..'; oACU[AiBotUnitInfo.reftoGridXZAdjust][iCurSlot]=X'..oACU[AiBotUnitInfo.reftoGridXZAdjust][iCurSlot][1]..'Z'..oACU[AiBotUnitInfo.reftoGridXZAdjust][iCurSlot][2]) end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished recording extra slots, iSizeToRecord='..iSizeToRecord..'; oACU[AiBotUnitInfo.reftoGridXZAdjust][iSizeToRecord]='..repru(oACU[AiBotUnitInfo.reftoGridXZAdjust][iSizeToRecord] or 'nil')..'; iSlotsAvailable (stopping once reach iSlotsWanted)='..iSlotsAvailable..'; iSlotsWanted='..iSlotsWanted) end
        end


        --Sort units awaiting for assignment by distance to the ACU, starting with the fursthest away
        local iClosestDist, iCurDist
        local iClosestSlot
        local iClosestAvailableSlotRef
        local iBaseX = oACU:GetPosition()[1]
        local iBaseZ = oACU:GetPosition()[3]
        local tGrid = oACU[AiBotUnitInfo.reftoGridXZAdjust]
        if bDebugMessages == true then LOG(sFunctionRef..': iSlotsAvailable='..iSlotsAvailable..'; iUnitsWithoutAssignment='..iUnitsWithoutAssignment) end
        for iUnitRef, iDistance in AiBotUtilities.SortTableByValue(toUnassignedRefByDistance, true) do
            local oUnit = toUnassignedUnits[iUnitRef]
            --Find the closest available slot
            iClosestSlot = nil
            iClosestAvailableSlotRef = nil
            iClosestDist = 10000
            if iSlotsAvailable > 0 then
                if bDebugMessages == true then LOG(sFunctionRef..': Sorting through available slots for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                for iAvailableTableEntry, iSlot in tiAvailableSlots do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iAvailableTableEntry='..iAvailableTableEntry..'; iSlot='..iSlot..'; Is tGrid[iSlot] nil='..tostring(tGrid[iSlot] == nil)) end
                    if tGrid[iSlot] then --Im guessing that removing slots can lead to the table having nil entries at the end
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions({iBaseX + tGrid[iSlot][1], 0, iBaseZ + tGrid[iSlot][2]}, oUnit:GetPosition())
                        if iCurDist < iClosestDist then
                            iClosestDist = iCurDist
                            iClosestSlot = iSlot
                            iClosestAvailableSlotRef = iAvailableTableEntry
                        end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': No valid ref so will abort if have a valid ref from earlier') end
                        if iClosestAvailableSlotRef then break end
                    end
                end
                if iClosestSlot and iClosestAvailableSlotRef then
                    oUnit[AiBotUnitInfo.refiACUGridSlot] = iClosestSlot
                    oACU[AiBotUnitInfo.reftoUnitAssignedToGridSlot][iClosestSlot] = oUnit
                    if bDebugMessages == true then LOG(sFunctionRef..': removing entry '..iClosestAvailableSlotRef..' from the table of available slots, iClosestSlot='..iClosestSlot) end
                    table.remove(tiAvailableSlots, iClosestAvailableSlotRef)
                else
                    --Redundancy
                    oUnit[AiBotUnitInfo.refiACUGridSlot] = 1
                end
            else
                --Redundancy
                oUnit[AiBotUnitInfo.refiACUGridSlot] = 1
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function SuicideExperimentalIntoFatboy(oUnit, oFatboy, iTeam, iPlateau)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SuicideExperimentalIntoFatboy'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iDistanceFromFatboyWanted = math.max(oUnit[AiBotUnitInfo.refiDFRange], 40)
    local iCurFacingAngle
    local iAngleToFatboy
    local iCurAngleAdjust
    local iAngleAdjustFactor = 30 --amount we will move by
    local iReadjustInterval = 2.2 --better than 1.5 and 3.0 in a simple ythotha vs fatboy sandbox test
    local iDistToAbort = 10
    local iDistanceToMove = iDistanceFromFatboyWanted
    local iPlateauWanted = iPlateau
    local iCurDist
    if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
        EnableUnitMicroUntilManuallyTurnOff(oUnit, false)

        while AiBotUnitInfo.IsUnitValid(oUnit) and AiBotUnitInfo.IsUnitValid(oFatboy) and not(AiBotUnitInfo.IsUnitUnderwater(oFatboy)) do
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oFatboy:GetPosition())
            if bDebugMessages == true then LOG(sFunctionRef..': iCurDist='..iCurDist) end
            if iCurDist > iDistanceFromFatboyWanted then
                iCurFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oUnit)
                iAngleToFatboy = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oFatboy:GetPosition())
                if AiBotUtilities.GetAngleDifference(iCurFacingAngle + iAngleAdjustFactor, iAngleToFatboy) <= AiBotUtilities.GetAngleDifference(iCurFacingAngle - iAngleAdjustFactor, iAngleToFatboy) then
                    iCurAngleAdjust = iAngleAdjustFactor
                else
                    iCurAngleAdjust = -iAngleAdjustFactor
                end
                local tPotentialMoveLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iCurFacingAngle + iCurAngleAdjust, iDistanceToMove, true, true, false)
                if not(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPotentialMoveLocation) == iPlateauWanted) then
                    tPotentialMoveLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iCurFacingAngle + iCurAngleAdjust * 0.5, iDistanceToMove, true, true, false)
                    if not(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPotentialMoveLocation) == iPlateauWanted) then
                        --Revert to normal logic
                        AiBotOrders.IssueTrackedMove(oUnit, oFatboy:GetPosition(), 5, false, 'SuicFBAb', true)
                        break
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iCurFacingAngle='..iCurFacingAngle..'; iAngleToFatboy='..iAngleToFatboy..'; iCurAngleAdjust='..iCurAngleAdjust..'; Angle to potential move location='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tPotentialMoveLocation)..'; Time='..GetGameTimeSeconds()) end
                AiBotOrders.IssueTrackedMove(oUnit, tPotentialMoveLocation, 5, false, 'SuicFBM', true)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(iReadjustInterval)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            else
                break
                --Tried with the below but it actually performed slightly worse than just having the default logic apply!
                --[[if iCurDist <= iDistToAbort then
                    --Are presumably in range so will revert to normal logic
                    break
                else
                    --Move directly to the fatboy
                    AiBotOrders.IssueTrackedMove(oUnit, oFatboy:GetPosition(), 5, false, 'SuicFBNr', true)
                    WaitSeconds(10)
                end--]]
            end

        end
        if AiBotUnitInfo.IsUnitValid(oUnit) then
            oUnit[AiBotUnitInfo.refbSpecialMicroActive] = false
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderSurfacingAtlantisToReleaseCargo(oUnit)
    if not(oUnit.Dead) then
        local toCargo = oUnit:GetCargo()
        if AiBotUtilities.IsTableEmpty(toCargo) == false then
            local iTeam = oUnit:GetAIBrain().AiBotTeam
            local refbCheckingToUnload = 'AiBotAtlUnC'
            if not(oUnit[refbCheckingToUnload]) then
                oUnit[refbCheckingToUnload] = true
                --Do we want to surface to release? Check nearby enemy AA threat
                local bHaveUnloaded = false
                local iTimeToWait
                local iCargoSize
                while not(bHaveUnloaded) and not(oUnit.Dead) and AiBotUtilities.IsTableEmpty(oUnit:GetCargo()) == false do
                    iTimeToWait = 40
                    iCargoSize = table.getn(oUnit:GetCargo())

                    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                    if tLZOrWZTeamData then
                        if (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) < 1000 then
                            if not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                                --Just release current cargo
                                TrackTemporaryUnitMicro(oUnit, 2, nil, false)
                                AiBotOrders.ReleaseStoredUnits(oUnit, false, 'AtlUnl', true)
                                bHaveUnloaded = true
                                break
                            else
                                --Do we want to surface to release? check for nearby enemy antisurface threats
                                local iCargoWantedToSurface = 1
                                if (tLZOrWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 0) > 2000 then
                                    iCargoWantedToSurface = 5
                                elseif AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftEnemyLongRangeUnits]) == false then
                                    iCargoWantedToSurface = 4
                                elseif AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                                    local iNearbySurfaceThreat = (tLZOrWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 0)
                                    for _, iAdjWZ in tLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                                        local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                                        iNearbySurfaceThreat = iNearbySurfaceThreat + (tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 0)
                                        if iNearbySurfaceThreat >= 4000 then
                                            iCargoWantedToSurface = 4
                                            break
                                        end
                                    end
                                end
                                if iCargoSize >= iCargoWantedToSurface then
                                    --Surface unit
                                    AiBotUnitInfo.ToggleUnitDiveOrSurfaceStatus(oUnit)
                                    local iMicroTotalTime = 15
                                    TrackTemporaryUnitMicro(oUnit, iMicroTotalTime, nil, false)
                                    local iTimeToWaitUntil = GetGameTimeSeconds() + iMicroTotalTime - 2
                                    while AiBotUnitInfo.IsUnitUnderwater(oUnit) do
                                        WaitSeconds(1)
                                        if GetGameTimeSeconds() >= iTimeToWaitUntil then break end
                                    end
                                    WaitSeconds(1)
                                    AiBotOrders.ReleaseStoredUnits(oUnit, false, 'AtlUnl', true)
                                    bHaveUnloaded = true
                                    ForkThread(SubmergeSubIfNoLongerWantSurfaced, oUnit, math.max(2, iTimeToWaitUntil + 2 - GetGameTimeSeconds())+0.1)
                                    break
                                end
                            end
                        end
                    end
                    if iCargoSize > 1 then iTimeToWait = iTimeToWait * (1 - 0.15 * math.min(iCargoSize, 6)) end
                    WaitSeconds(iTimeToWait)
                end
                oUnit[refbCheckingToUnload] = false
            end
        end
    end
end

function IsTargetRunningAway(oPotentialTarget, oUnit, iCurSpeed, iOurMaxSpeed, iTargetCurSpeed, iEnemyMaxSpeed, iOurRange, iCurFacingAngle)
    --For some reason have to have this as a standalone function for the code to run
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'IsTargetRunningAway'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(oUnit.Dead) then --wierd bug where despite exact same timestamp oUnit returns valid before function is called, and dead/invalid during the function
        if not(iCurSpeed) then iCurSpeed = AiBotUnitInfo.GetUnitSpeed(oUnit) end
        --Are we going near our max speed (allowance given because the speed values may not be that consistent)
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if oPotentialTarget is running away and is outside our range, oPotentialTarget='..oPotentialTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oPotentialTarget)..'; iCurSpeed='..iCurSpeed..'; iOurMaxSpeed='..iOurMaxSpeed..'; Target speed='..AiBotUnitInfo.GetUnitSpeed(oPotentialTarget)..'; Target max speed='..iEnemyMaxSpeed..'; Dist to enemy='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oPotentialTarget:GetPosition())..'; Our range='..iOurRange..'; oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; oUnit.Dead='..tostring(oUnit.Dead or false)..'; Time='..GetGameTimeSeconds()) end
        if iCurSpeed >= iOurMaxSpeed * 0.7 then
            --Is enemy going near their max speed, and almsot as fast as us or faster?
            iTargetCurSpeed = AiBotUnitInfo.GetUnitSpeed(oPotentialTarget)
            if iTargetCurSpeed >= iEnemyMaxSpeed * 0.7 and iTargetCurSpeed >= iCurSpeed - 0.25 then
                --Is enemy out of our range?
                local iCurDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oPotentialTarget:GetPosition())
                if iCurDistToTarget > iOurRange + 1 then
                    --is enemy infront of us?
                    local iCurAngleToTarget = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oPotentialTarget:GetPosition())
                    if not(iCurFacingAngle) then
                        if bDebugMessages == true then LOG(sFunctionRef..': About to get oUnit facing angle, is oUnit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; Time='..GetGameTimeSeconds()) end
                        iCurFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oUnit)
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurANgleToTarget='..iCurAngleToTarget..'; iCurFacingAngle='..iCurFacingAngle..'; AngleDif='..AiBotUtilities.GetAngleDifference(iCurAngleToTarget, iCurFacingAngle)..'; Target facing angle='..AiBotUnitInfo.GetUnitFacingAngle(oPotentialTarget)..'; Dif to our facing angle='..AiBotUtilities.GetAngleDifference(iCurFacingAngle, AiBotUnitInfo.GetUnitFacingAngle(oPotentialTarget))) end
                    if AiBotUtilities.GetAngleDifference(iCurAngleToTarget, iCurFacingAngle) <= 10 then
                        --Is enemy going in similar direction to us?
                        if AiBotUtilities.GetAngleDifference(iCurFacingAngle, AiBotUnitInfo.GetUnitFacingAngle(oPotentialTarget)) <= 10 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Target is unsuitable') end
                            return true
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Target is suitable') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function SuicideYthothaIntoEnemyBase(oUnit, tEnemyBaseToSuicideInto, iMaxDistFromBase, iTeam, tFirstTargetLocation)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SuicideYthothaIntoEnemyBase'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
        local iCurDist
        local iBasePlateau, iBaseZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tEnemyBaseToSuicideInto)
        local tBaseLZData = AiBotMap.tAllPlateaus[iBasePlateau][AiBotMap.subrefPlateauLandZones][iBaseZone]
        local tBaseLZTeamData = tBaseLZData[AiBotMap.subrefLZTeamData][iTeam]
        if tBaseLZTeamData then
            EnableUnitMicroUntilManuallyTurnOff(oUnit, false)
            while AiBotUnitInfo.IsUnitValid(oUnit) do

                local tLocationToSuicideInto
                if tFirstTargetLocation then
                    tLocationToSuicideInto = tFirstTargetLocation
                else
                    tLocationToSuicideInto = AiBotLand.GetNearbyEnemyBaseLocationToSuicideYthotha(oUnit, tEnemyBaseToSuicideInto, iMaxDistFromBase, iTeam)
                    if tLocationToSuicideInto then
                        --Check for nearby enemy ACU and experimental to target instead that are in the zone
                        if AiBotUtilities.IsTableEmpty(tBaseLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                            local tNearbyEnemyExperimentalAndACU = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryExperimentalLevel + categories.COMMAND, tBaseLZTeamData[AiBotMap.reftoNearestDFEnemies])
                            if AiBotUtilities.IsTableEmpty(tNearbyEnemyExperimentalAndACU) == false then
                                for iExp, oExp in tNearbyEnemyExperimentalAndACU do
                                    if not(oExp.Dead) and oExp:GetFractionComplete() >= 0.7 then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oExp:GetPosition(), oUnit:GetPosition())
                                        if bDebugMessages == true then LOG(sFunctionRef..': oExp='..oExp.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oExp)..'; Dist to it='..iCurDist..'; oUnit Combat range='..oUnit[AiBotUnitInfo.refiCombatRange]..'; oExp DF range='..(oExp[AiBotUnitInfo.refiDFRange] or 'nil')..'; oExp health%='..AiBotUnitInfo.GetUnitHealthPercent(oExp)..'; oUnit health%='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)) end
                                        if (iCurDist <= oUnit[AiBotUnitInfo.refiCombatRange] + 15 and (iCurDist <= oUnit[AiBotUnitInfo.refiCombatRange] + 5 or EntityCategoryContains(categories.COMMAND, oExp.UnitId)))
                                                or iCurDist < (oExp[AiBotUnitInfo.refiDFRange] or 0) and oExp:GetFractionComplete() >= 0.85 and (AiBotUnitInfo.GetUnitHealthPercent(oUnit) >= 0.2 or AiBotUnitInfo.GetUnitHealthPercent(oUnit) >= AiBotUnitInfo.GetUnitHealthPercent(oExp)) then
                                            tLocationToSuicideInto = nil
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will abort suicide logic so our normal logic can target oExp') end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Loop for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..'; is tLocationToSuicideInto nil='..tostring(tLocationToSuicideInto == nil)..'; Time='..GetGameTimeSeconds()) end
                if tLocationToSuicideInto then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have a location to suicide into, dist to it='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLocationToSuicideInto)) end
                    if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLocationToSuicideInto) <= 5 then
                        AiBotOrders.IssueTrackedAggressiveMove(oUnit, tLocationToSuicideInto, 5, false, 'SuicYthA', true)
                    else
                        AiBotOrders.IssueTrackedMove(oUnit, tLocationToSuicideInto, 5, false, 'SuicYthM', true)
                    end
                else
                    break
                end
                --Clear first value
                tFirstTargetLocation = nil
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
            if AiBotUnitInfo.IsUnitValid(oUnit) then
                oUnit[AiBotUnitInfo.refbSpecialMicroActive] = false
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end